    ["Panicking old soldier"] = {
        ["Don't panic! Don't panic!"] = "¡Que no cunda el pánico! ¡No entrar en pánico!",
        ["You seem a bit agitated. What's wrong?"] = "Pareces un poco agitado. ¿Qué ocurre?",
        ["Don't panic citizen! It's all under control."] = "¡Que no cunda el pánico ciudadano! Está todo bajo control.",
        ["What is under control?"] = "¿Qué está bajo control?",
        ["I am not panicking, citizen!"] = "¡No estoy entrando en pánico, ciudadano!",
        ["Um, yes! Well done, soldier. Now, what is going on?"] = "¡Eh, sí! Bien hecho, soldado. Ahora, ¿qué está pasando?",
        ["It's Lumbridge, citizen."] = "Soy Lumbridge, ciudadano.",
        ["You must have heard - both Saradomin and Zamorak have returned to Gielinor and are fighting there!"] = "Debes haberlo escuchado: ¡tanto Saradomin como Zamorak han regresado a Gielinor y están peleando allí!",
        ["What should I do?"] = "¿Qué debo hacer?",
        ["You should leave it to the professionals, citizen. It is all under control."] = "Deberías dejarlo en manos de los profesionales, ciudadano. Está todo bajo control.",
        ["Lots of people have ignored us and gone to the battlefield, citizen. They've been joining up with Saradomin or Zamorak."] = "Mucha gente nos ha ignorado y se ha ido al campo de batalla, ciudadano. Se han estado uniendo a Saradomin o Zamorak.",
        ["But you don't have to do that, citizen. We have it all under control."] = "Pero no tienes que hacer eso, ciudadano. Lo tenemos todo bajo control.",
        ["So I could join with Saradomin?"] = "¿Entonces podría unirme a Saradomin?",
        ["People have been going to the camp to the north of the battlefield to join Saradomin."] = "La gente ha estado yendo al campamento al norte del campo de batalla para unirse a Saradomin.",
        ["The generals have been offering rewards to everyone who will join their cause!"] = "¡Los generales han estado ofreciendo recompensas a todos los que se unan a su causa!",
        ["But don't panic citizen, because we have it all under control."] = "Pero que no cunda el pánico ciudadano, porque lo tenemos todo bajo control.",
        ["So I could join with Zamorak?"] = "¿Entonces podría unirme a Zamorak?",
        ["People have been going to the camp to the south of the battlefield to join Zamorak."] = "La gente ha estado yendo al campamento al sur del campo de batalla para unirse a Zamorak.",
        ["Where is the battlefield?"] = "¿Dónde está el campo de batalla?",
        ["The battlefield is to the west of Lumbridge castle."] = "El campo de batalla está al oeste del castillo Lumbridge.",
        ["There are camps to the north and south, and there's fighting between the two."] = "Hay campamentos al norte y al sur, y hay combates entre los dos.",
        ["That sounds scary!"] = "¡Eso suena aterrador!",
        ["You should not be scared, citizen. We have it all under control, citizen! Don't panic!"] = "No deberías tener miedo, ciudadano. ¡Lo tenemos todo bajo control, ciudadano! ¡No entrar en pánico!",
        ["Thanks for the advice."] = "Gracias por el consejo.",
        ["Remember, citizen, don't panic!"] = "Recuerda, ciudadano, ¡que no cunda el pánico!",
        ["Well, that's nothing to panic about!"] = "Bueno, ¡eso no es motivo de pánico!",
        ["Yes, citizen. I am not panicking, citizen!"] = "Sí, ciudadano. ¡No me entra el pánico, ciudadano!",
    },
    ["Panning archaeologist (male)"] = {
        ["It would be amazing if I actually found something valuable. That'd be sweet, just... anything. I would celebrate like it was my birthday!"] = "Sería fantástico si realmente encontrara algo valioso. Sería dulce, simplemente... cualquier cosa. ¡Lo celebraría como si fuera mi cumpleaños!",
    },
    ["Panning archaeologist"] = {
        ["It would be amazing if I actually found something valuable. That'd be sweet, just... anything. I would celebrate like it was my birthday!"] = "Sería fantástico si realmente encontrara algo valioso. Sería dulce, simplemente... cualquier cosa. ¡Lo celebraría como si fuera mi cumpleaños!",
    },
    ["Panning guide"] = {
        ["There's no reason to pan anymore, not since the guild got the funding for a screening station."] = "Ya no hay razón para preocuparse, no desde que el gremio obtuvo los fondos para una estación de detección.",
        ["Hello, who are you?"] = "Hola, ¿quién eres?",
        ["Hello, I am the panning guide. I teach students how to pan in these waters. They're not permitted to do so until after they've had training and, of course, they must be invited to pan here too."] = "Hola, soy panning guide. Les enseño a los estudiantes cómo moverse en estas aguas. No se les permite hacerlo hasta que hayan recibido capacitación y, por supuesto, también se les debe invitar a realizar panorámicas aquí.",
        ["So, how do I become invited?"] = "Entonces, ¿cómo puedo recibir una invitación?",
        ["I'm not supposed to let people pan here unless they have permission. Mind you, I could let you have a go if you're willing to do me a favour..."] = "Se supone que no debo permitir que la gente haga panorámicas aquí a menos que tengan permiso. Eso sí, podría dejarte intentarlo si estás dispuesto a hacerme un favor...",
        ["What's that?"] = "¿Qué es eso?",
        ["Well, to be honest, what I would really like is a nice cup of tea!"] = "Bueno, para ser honesto, ¡lo que realmente me gustaría es una buena taza de té!",
        ["Tea?"] = "¿Té?",
        ["Absolutely, I'm parched!"] = "¡Por supuesto, estoy sediento!",
        ["If you could bring me one of those, I would be more than willing to let you pan here. I usually get some from the main campus building, but I'm busy at the moment."] = "Si pudieras traerme uno de esos, estaría más que dispuesto a dejarte explorar aquí. Generalmente recibo algunos en el edificio principal del campus, pero estoy ocupado en este momento.",
        ["Ah, you read my mind - I could murder a good cuppa right now. If I can have that cup of tea, I'd give you permission to pan here. What do you say?"] = "Ah, me leíste la mente. Podría matar una buena taza de té ahora mismo. Si puedo tomar esa taza de té, te daría permiso para explorar aquí. ¿Qué dices?",
        ["Give the panning guide a cuppa?"] = "¿Darle una taza al panning guide?",
        ["Yes."] = "Sí.",
        ["Ah! Lovely! You can't beat a good cuppa! You're free to pan all you want."] = "¡Ah! ¡Hermoso! ¡No hay nada mejor que una buena taza de té! Eres libre de hacer panorámicas todo lo que quieras.",
        ["I've some here that you can have."] = "Aquí tengo algunos que puedes tener.",
        ["Hello, I am the panning guide. I'm here to teach you how to pan for gold."] = "Hola, soy panning guide. Estoy aquí para enseñarte cómo buscar oro.",
        ["Excellent!"] = "¡Excelente!",
        ["Let me explain how panning works. First, you need a panning tray. Use the tray in the panning points in the water and then search your tray. If you find any gold, take it to Terry in the Exam Centre. He will calculate its value for you."] = "Déjame explicarte cómo funciona la panorámica. Primero, necesitas una bandeja panorámica. Utilice la bandeja en los puntos de panorámica en el agua y luego busque su bandeja. Si encuentra oro, lléveselo a Terry en el centro de exámenes. Él calculará su valor por usted.",
        ["Select an option"] = "Seleccione una opción",
        ["Can you tell me more about the tools an archaeologist uses?"] = "¿Puedes contarme más sobre las herramientas que utiliza un arqueólogo?",
        ["Of course! Let's see now... Trowels are vital for fine digging work, so you can be careful to not damage or disturb any artefacts. Rock picks are for splitting rocks or scraping away soil."] = "¡Por supuesto! Veamos ahora... Las paletas son vitales para los trabajos de excavación finos, por lo que debes tener cuidado de no dañar ni alterar ningún artefacto. Los picos de rocas sirven para partir rocas o raspar la tierra.",
        ["What about specimen jars and brushes?"] = "¿Qué pasa con los cepillos y los frascos de muestras?",
        ["Those are essential for carefully cleaning and storing smaller samples."] = "Son esenciales para limpiar y almacenar cuidadosamente muestras más pequeñas.",
        ["Where can I get any of these things?"] = "¿Dónde puedo conseguir cualquiera de estas cosas?",
        ["Well, we've come into a bit more funding of late, so there should be a stock of each of them in the Exam Centre's tools cupboard. We also hand out relevant tools as students complete each level of their Earth Sciences exams."] = "Bueno, últimamente hemos recibido un poco más de financiación, por lo que debería haber un stock de cada uno de ellos en el armario de herramientas del Centro de exámenes. También entregamos herramientas relevantes a medida que los estudiantes completan cada nivel de sus exámenes de Ciencias de la Tierra.",
        ["Anything else?"] = "¿Algo más?",
        ["If you need something identified or are not sure about something, give it to Terry. He's the archaeological expert in the next room."] = "Si necesita identificar algo o no está seguro de algo, dáselo a Terry. Él es el experto en arqueología en la habitación de al lado.",
        ["Ah, okay, thanks."] = "Ah, está bien, gracias.",
        ["Thank you!"] = "¡Gracias!",
        ["Yes, this is a panning tray..."] = "Sí, esta es una bandeja panorámica...",
        ["This is no good to me, I don't deal with finds."] = "Esto no me sirve de nada, no me ocupo de hallazgos.",
    },
    ["Papa Mambo"] = {
        ["Heh heh heh."] = "Je, je, je.",
        ["Select an option"] = "Seleccione una opción",
        ["Why are you laughing?"] = "¿Por qué te ríes?",
        ["Heh heh heh. Can you not hear her joke? It not one of her best, but it's still a good one."] = "Je, je, je. ¿No puedes oír su broma? No es uno de sus mejores, pero sigue siendo bueno.",
        ["Whose joke?"] = "¿De quién es el chiste?",
        ["Whose joke are you talking about?"] = "¿De quién chiste estás hablando?",
        ["Why, the vine's joke, of course. Can you hear someone else round here? Perhaps you're going crazy?"] = "Vaya, el chiste de la vid, por supuesto. ¿Puedes oír a alguien más por aquí? ¿Quizás te estás volviendo loco?",
        ["She?"] = "¿Ella?",
        ["Why do you refer to the vine as 'she'?"] = "¿Por qué te refieres a la vid como \"ella\"?",
        ["Because she is female."] = "Porque es mujer.",
        ["How do you know? I mean...she's a plant."] = "¿Cómo lo sabes? Quiero decir... ella es una planta.",
        ["Heh heh heh, she told me that she's a lady. She's telling you now, can you not hear her?"] = "Je je je, me dijo que es una dama. Ella te lo está diciendo ahora, ¿no puedes oírla?",
        ["Yes I can hear her."] = "Sí, puedo oírla.",
        ["Oh good, ah am so glad you can hear her. She has been nagging me since you arrived. Between you an' me, she can be quite annoying at times."] = "Oh, bien, me alegro mucho de que puedas escucharla. Ella me ha estado molestando desde que llegaste. Entre tú y yo, ella puede ser bastante molesta a veces.",
        ["She's telling me that you should give up all your gold coins."] = "Ella me está diciendo que deberías renunciar a todo tu gold coins.",
        ["Ah. You sadden me. I had hoped you could hear her beautiful singing, but you clearly cannot. I pay you no ill will, the loss is yours my friend."] = "Ah. Me entristeces. Esperaba que pudieras escuchar su hermoso canto, pero claramente no puedes. No te hago ninguna mala voluntad, la pérdida es tuya, amigo mío.",
        ["I thought her joke wasn't that bad."] = "Pensé que su broma no era tan mala.",
        ["Heh heh heh, you should hear her on a full moon. She's always on top form in the moonlight."] = "Je je je, deberías escucharla en luna llena. Ella siempre está en plena forma bajo la luz de la luna.",
        ["Tell me about yourself."] = "Cuéntame sobre ti.",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["I'll leave you be for now."] = "Te dejaré en paz por ahora.",
        ["Obviously not. You're clearly mad."] = "Obviamente no. Estás claramente enojado.",
        ["Oh, she talks, my friend. If only you could listen."] = "Oh, ella habla, amiga mía. Si tan sólo pudieras escuchar.",
        ["Who are you?"] = "¿Quién eres?",
        ["I've talked enough for now."] = "Ya he hablado suficiente por ahora.",
        ["Oh, I see you have taken an interest in this little vine. I grew this vine from a root cutting of the Jade Vine to the north. She was a little clumsy and cut me while I took it. I have since imbued the cutting with my own magic, to help make her what she is today. She grows food for her jadinkos and extends her arms so that they can find home in her shade. And she grows different tings; each ting is nectar to one type of jadinko... but poison to another. Encourage her to grow different combinations of plants and watch as different jadinkos are drawn into her embrace."] = "Oh, veo que te has interesado en esta pequeña enredadera. Cultivé esta enredadera a partir de un corte de raíz de Jade Vine en el norte. Ella fue un poco torpe y me cortó mientras lo tomaba. Desde entonces, he imbuido el corte con mi propia magia, para ayudarla a ser lo que es hoy. Cultiva comida para sus jadinkos y extiende sus brazos para que encuentren un hogar a su sombra. Y a ella le crecen diferentes matices; Cada ting es néctar para un tipo de jadinko... pero veneno para otro. Anímela a cultivar diferentes combinaciones de plantas y observe cómo diferentes jadinkos caen en sus brazos.",
        ["What would be the point of attracting different jadinkos?"] = "¿Cuál sería el punto de atraer diferentes jadinkos?",
        ["Aside from the joy of seeing nature's majesty? Ah suppose you could hunt the jadinkos you attract. They have special properties you could use. I have some special marasamaw traps that will catch them, if you have the skill. The jadinkos here are part of the vine herself. They are infused with her magic. Once hunted, they could provide ingredients for powerful new potions, if you have the know-how."] = "¿Aparte de la alegría de ver la majestuosidad de la naturaleza? Ah, supongo que podrías cazar a los jadinkos que atraes. Tienen propiedades especiales que podrías utilizar. Tengo algunas trampas especiales para marasamaw que los atraparán, si tienes la habilidad. Los jadinkos aquí son parte de la propia vid. Están imbuidos de su magia. Una vez cazados, podrían proporcionar ingredientes para nuevas y poderosas pociones, si tienes los conocimientos necesarios.",
        ["Ere, as you are new to this vine, take this little gift from me."] = "Eh, como eres nuevo en esta vid, acepta este pequeño regalo de mi parte.",
        ["Alas, you not 'ave room for this gift."] = "Lamentablemente, no tienes espacio para este regalo.",
        ["Papa Mambo hands you a red vine blossom seed, a green vine blossom seed and a blue vine blossom seed."] = "Papa Mambo te entrega una semilla de flor de vid roja, una semilla de flor de vid verde y una semilla de flor de vid azul.",
        ["Use them to make this vine bloom an' blossom, so many jadinkos will come. If you run out, you can buy more from me."] = "Úsalos para hacer que esta enredadera florezca y florezca, así vendrán muchos jadinkos. Si se te acaba, puedes comprarme más.",
        ["Ah, but you are skilled with this knowledge. No longer do you need my gifts."] = "Ah, pero eres hábil con este conocimiento. Ya no necesitas mis regalos.",
        ["What are jadinkos?"] = "¿Qué son los jadinkos?",
        ["Heh heh, that is the name I's given to the strange creatures that live here. It has a nice ring to it, I's thinking."] = "Je je, ese es el nombre que le he dado a las extrañas criaturas que viven aquí. Suena muy bien, estoy pensando.",
        ["So, you say that different plants attract different creatures?"] = "Entonces, ¿dices que diferentes plantas atraen a diferentes criaturas?",
        ["Tell me about the potions I can make."] = "Cuéntame sobre las pociones que puedo hacer.",
        ["I'll leave you be."] = "Te dejaré en paz.",
        ["So, you say that different plants attract different jadinkos?"] = "Entonces, ¿dices que diferentes plantas atraen diferentes jadinkos?",
        ["Oh yes. The vine is home to many variations of the strange jadinkos that wander here. Each one is attracted by different combinations of plants and environmental features. And some can only be attracted by those who have used a special juju potion on the flowers. Drawn to the magic like a moth to a flame, they are. Most jadinkos, they like the same ting and will always be attracted by that combination. But there are jadinkos whose tastes are fickle and their requirements change every week or so. These fickle creatures, when captured, give you ingredients that can enhance your mastery of this strange habitat. They can be used to make your experience here...more rewarding... ...if you can attract 'em and catch 'em, that is."] = "Ah, sí. La vid alberga muchas variaciones de los extraños jadinkos que deambulan por aquí. Cada uno se siente atraído por diferentes combinaciones de plantas y características ambientales. Y algunos sólo pueden sentirse atraídos por aquellos que han usado una poción juju especial en las flores. Se sienten atraídos por la magia como una polilla por la llama. A la mayoría de los jadinkos les gusta el mismo toque y siempre se sentirán atraídos por esa combinación. Pero hay jadinkos cuyos gustos son volubles y sus necesidades cambian aproximadamente cada semana. Estas volubles criaturas, cuando son capturadas, te brindan ingredientes que pueden mejorar tu dominio de este extraño hábitat. Pueden usarse para hacer que tu experiencia aquí... sea más gratificante... ...si puedes atraerlos y atraparlos, claro está.",
        ["Is there any reason to catch them all?"] = "¿Hay alguna razón para atraparlos a todos?",
        ["Heh heh heh, of course! If you are skilled enough to catch one of each jadinko type that wander 'ere, come and speak to me. I will have a reward for you."] = "¡Je, je, je, por supuesto! Si tienes la habilidad suficiente para atrapar uno de cada tipo de jadinko que deambula por aquí, ven y habla conmigo. Tendré una recompensa para ti.",
        ["These potions are different from others you can create. First, they be uniquely tied to you, your essence. No other can benefit from them. Second, they open up new ways of seeing the world and finding new rewards. Each is different and provides a special benefit. Perhaps, most important, is the juju hunter potion you can create, for this potion will attract new creatures to this vine. These juju potions cannot be made in a normal potion vial. They must be made in a specially created juju vial, for only they can hold the power."] = "Estas pociones son diferentes de otras que puedes crear. En primer lugar, deben estar exclusivamente vinculados a ti, a tu esencia. Ningún otro puede beneficiarse de ellos. En segundo lugar, abren nuevas formas de ver el mundo y encontrar nuevas recompensas. Cada uno es diferente y proporciona un beneficio especial. Quizás lo más importante sea la poción de cazador de juju que puedes crear, ya que esta poción atraerá nuevas criaturas a esta enredadera. Estas pociones de juju no se pueden preparar en un frasco de poción normal. Deben fabricarse en un vial de juju creado especialmente, ya que solo ellos pueden contener el poder.",
        ["Where can I get a juju vial from?"] = "¿Dónde puedo conseguir un vial de juju?",
        ["Heh heh heh. I's only one that sells them, strangely enough. Heh heh heh."] = "Je, je, je. Soy el único que los vende, aunque parezca extraño. Je je je.",
        ["I am Papa Mambo, shaman and protector of this vine. Once, I was the shaman of Shilo Village, and now I's a keeper of this vine."] = "Soy Papa Mambo, chamán y protector de esta vid. Una vez fui el chamán de Shilo Village y ahora soy el guardián de esta vid.",
        ["Why did you leave the village?"] = "¿Por qué dejaste el pueblo?",
        ["Heh heh heh heh heh. We did not see eye to eye on all tings. Heh heh. Some thought my studies were...unnerving. But it always seemed such a shame leaving the dead buried, when there was such good work they could do."] = "Je, je, je, je, je. No estábamos de acuerdo en todos los aspectos. Je je. Algunos pensaban que mis estudios eran... desconcertantes. Pero siempre me pareció una lástima dejar enterrados a los muertos, cuando podían hacer un trabajo tan bueno.",
        ["You may be wanting to visit the druid. He's learning about this habitat, like you, and may be able to share the knowledge he has gained. Goodbye, ma friend."] = "Quizás quieras visitar al druida. Él está aprendiendo sobre este hábitat, como usted, y es posible que pueda compartir el conocimiento que ha adquirido. Adiós, amiga.",
        ["Heh heh heh. What can I do for you, my friend?"] = "Je, je, je. ¿Qué puedo hacer por ti, amigo mío?",
        ["I just came to chat."] = "Sólo vine a charlar.",
        ["Can I see what's in your shop?"] = "¿Puedo ver qué hay en tu tienda?",
        ["I'd like you to build something for me."] = "Me gustaría que construyeras algo para mí.",
        ["What would you like me to build?"] = "¿Qué te gustaría que construyera?",
        ["Nothing."] = "Nada.",
        ["Oh, starting from scratch, are we?"] = "Oh, empezamos desde cero, ¿verdad?",
        ["Yes, tear it all down."] = "Sí, derribarlo todo.",
        ["You no longer have an environmental feature in place."] = "Ya no tienes ninguna característica ambiental implementada.",
        ["No, leave it as it is!"] = "¡No, déjalo como está!",
        ["Not to worry. Come back to me if you change your mind."] = "No te preocupes. Vuelve conmigo si cambias de opinión.",
        ["Pond."] = "Estanque.",
        ["Building a pond will cost you 65,000 gold."] = "Construir un estanque te costará 65.000 de oro.",
        ["Pay Papa Mambo to build the feature."] = "Pague a Papa Mambo para crear la función.",
        ["Heh heh heh. Good, my friend, I'll start work on your environmental feature. It'll be ready in a heartbeat."] = "Je, je, je. Bien, amigo mío, empezaré a trabajar en tu función medioambiental. Estará listo en un instante.",
        ["Don't pay Papa Mambo to build the feature."] = "No pague a Papa Mambo para crear la función.",
        ["Oh well, perhaps 'nother time."] = "Bueno, tal vez en otro momento.",
        ["*(If a pond is already built:)*"] = "*(Si ya hay un estanque construido:)*",
        ["You already have that feature in place. No need to build it again."] = "Ya tienes esa característica implementada. No es necesario volver a construirlo.",
        ["Tall grass."] = "Hierba alta.",
        ["Building tall grass will cost you 62,000 gold."] = "Construir hierba alta te costará 62.000 de oro.",
        ["Abandoned house."] = "Casa abandonada.",
        ["Building an abandoned house will cost you 57,000 gold."] = "Construir una casa abandonada te costará 57.000 de oro.",
        ["More choices."] = "Más opciones.",
        ["Thermal vent."] = "Ventilación térmica.",
        ["Building a thermal vent will cost you 59,000 gold."] = "Construir un respiradero termal te costará 59 000 de oro.",
        ["Standing stones."] = "Piedras en pie.",
        ["Building standing stones will cost you 70,000 gold."] = "Construir menhires te costará 70.000 de oro.",
        ["Dark pit."] = "Pozo oscuro.",
        ["Building a dark pit will cost you 80,000 gold."] = "Construir un pozo oscuro te costará 80.000 de oro.",
        ["Boneyard."] = "Cementerio.",
        ["Building a boneyard will cost you 56,000 gold."] = "Construir un cementerio te costará 56.000 de oro.",
        ["Back."] = "Atrás.",
        ["Can you ward off certain jadinkos for me?"] = "¿Puedes protegerme de ciertos jadinkos por mí?",
        ["*(If the player has not attracted any jadinkos:)*"] = "*(Si el player no ha atraído a ningún jadinkos:)*",
        ["Heh heh heh, I's can. Heh heh heh. But you best be attracting a jadinko before I's warding them away. I don't believe you've ever even seen one."] = "Je, je, je, puedo. Je je je. Pero será mejor que atraigas a un jadinko antes de que yo los aleje. No creo que hayas visto nunca uno.",
        ["Do you have any free seeds?"] = "¿Tienes semillas gratis?",
        ["Heh heh heh, well done! You have caught all of the normal jadinkos this week. Come talk to me for your reward."] = "Je, je, je, ¡bien hecho! Has atrapado a todos los jadinkos normales esta semana. Ven a hablar conmigo para recibir tu recompensa.",
        ["Heh heh heh. You have hunted at least one of each creature that comes 'ere. I am impressed. For your efforts, I offer a gift of knowledge. But, tell me, what would you like knowledge of?"] = "Je, je, je. Has cazado al menos una de cada criatura que viene aquí. Estoy impresionado. Por sus esfuerzos, le ofrezco un regalo de conocimiento. Pero dime, ¿de qué te gustaría saber?",
        ["Which skill would you like to improve?"] = "¿Qué habilidad te gustaría mejorar?",
        ["I'd like to improve my Farming."] = "Me gustaría mejorar mi Farming.",
        ["I'd like to improve my Hunter."] = "Me gustaría mejorar mi Hunter.",
        ["I'd like to improve my Herblore."] = "Me gustaría mejorar mi Herblore.",
        ["I'll need to think about it for a moment. I'll come back when I've chosen."] = "Tendré que pensarlo un momento. Volveré cuando haya elegido.",
        ["As you wish, but do not take too long."] = "Como quieras, pero no tardes mucho.",
        ["I'd like to improve my [Farming/Hunter/Herblore]."] = "Me gustaría mejorar mi [Farming/Hunter/Herblore].",
        ["You receive [number] [Farming/Hunter/Herblore] experience."] = "Recibes experiencia [número] [Farming/Hunter/Herblore].",
        ["*(If the player is missing witchdoctor robes or legs:)*"] = "*(Si a el player le faltan túnicas o piernas de brujo:)*",
        ["*(Without a free backpack space:)*"] = "*(Sin espacio libre backpack :)*",
        ["Ah, you not have room for my gift. Come back when you have space in your inventory."] = "Ah, no tienes espacio para mi regalo. Vuelve cuando tengas espacio en tu inventario.",
        ["*(With free backpack space:)*"] = "*(Con espacio backpack gratuito:)*",
        ["Here, have a little gift from me."] = "Toma, ten un pequeño regalo de mi parte.",
        ["Papa Mambo gives you some witchdoctor [robes/legs]."] = "Papa Mambo te regala un brujo [robes/legs].",
        ["Heh heh heh. I's impressed. You have caught not only the normal jadinko, but the powerful ones as well. I's got an extra special reward for that feat."] = "Je, je, je. Estoy impresionado. No sólo has atrapado al jadinko normal, sino también a los poderosos. Tengo una recompensa extra especial por esa hazaña.",
        ["Heh heh heh. As you have caught all the special jadinkos, I's be giving you this extra special gift."] = "Je, je, je. Como has atrapado todos los jadinkos especiales, te daré este regalo muy especial.",
        ["As you wish, but do not take long."] = "Como quieras, pero no tardes.",
        ["*(If the player is missing the witchdoctor mask:)*"] = "*(Si a el player le falta la máscara del médico brujo:)*",
        ["You have no room for the mask. Come back to me when you have room for one item. Then I's be finishing your reward."] = "No tienes espacio para la máscara. Vuelve conmigo cuando tengas espacio para un artículo. Entonces estaré terminando tu recompensa.",
        ["Papa Mambo gives you a witchdoctor mask."] = "Papa Mambo te regala una máscara de brujo.",
        ["You be finding that the shaman clothes give you greater...experience, shall we say, for growing plants, finding jadinkos and making juju potions. This gift will only last for half an hour, though."] = "Descubrirás que la ropa de chamán te da mayor... experiencia, digamos, para cultivar plantas, encontrar jadinkos y hacer pociones juju. Sin embargo, este regalo sólo durará media hora.",
        ["I have a special request for [breed]. Especially if it has the [trait] trait!"] = "Tengo una solicitud especial para [breed]. ¡Especialmente si tiene el rasgo [trait]!",
        ["I'm also after some Jadinkos, in fact I'll buy up to [number] more while I'm here."] = "También estoy buscando algunos Jadinkos, de hecho compraré hasta [número] más mientras esté aquí.",
        ["Would you like to sell [name] for [number] beans?"] = "¿Le gustaría vender [name] por frijoles [número]?",
        ["Yes."] = "Sí.",
        ["Your currency pouch is full of beans! You need to spend some beans before you can earn any more."] = "¡Tu bolsa de monedas está llena de frijoles! Necesitas gastar algunos frijoles antes de poder ganar más.",
        ["You can't hold anymore beans, I can't purchase this animal off you."] = "No puedes aguantar más frijoles, no puedo comprarte este animal.",
        ["This transaction would take you over the cap of one million beans. In doing so, you would lose out on [number] beans."] = "Esta transacción le llevaría por encima del límite de un millón de frijoles. Al hacerlo, perdería beans [número].",
        ["**COMPLETE TRANSACTION ANYWAY?**"] = "**¿COMPLETAR LA TRANSACCIÓN DE TODOS MODOS?**",
        ["[number] beans added to your currency pouch."] = "Frijoles [número] agregados a su bolsa de divisas.",
        ["Are you sure you want me to take all the Jadinkos you're holding? I won't take any of your favourites."] = "¿Estás seguro de que quieres que me lleve todos los Jadinkos que tienes? No aceptaré ninguno de tus favoritos.",
        ["**SELL ALL OF YOUR JADINKOS?**"] = "**¿VENDER TODOS TUS JADINKOS?**",
        ["Yes"] = "si",
        ["You don't have any animals to sell. Zero animals, Zero beans!"] = "No tienes animales para vender. ¡Cero animales, cero frijoles!",
    },
    ["Parcel Pete"] = {
        ["*(One of the following is seen occasionally:)*"] = "*(Ocasionalmente se ve uno de los siguientes:)*",
        ["It's time to give back, mail for everyone!"] = "¡Es hora de retribuir, correo para todos!",
        ["Parcels from the Hedge!"] = "¡Paquetes del seto!",
        ["Post! Post! Post! There's so much post!"] = "¡Publicar! ¡Correo! ¡Correo! ¡Hay tantas publicaciones!",
        ["What do you want?"] = "¿Qué quieres?",
        ["What's wrong?"] = "¿Qué pasa?",
        ["Sorry, I'm just frustrated about this 'internship'. My brother won't listen to any of my ideas, and he's only in charge because he's older! Not to mention making me follow adventurers around like a pet..."] = "Lo siento, simplemente estoy frustrado por esta 'pasantía'. ¡Mi hermano no escucha ninguna de mis ideas y solo está a cargo porque es mayor! Sin mencionar hacerme seguir a los aventureros como una mascota...",
        ["*(Returns to the initial options.)*"] = "*(Vuelve a las opciones iniciales.)*",
        ["What happened to the fanmail?"] = "¿Qué pasó con el fanmail?",
        ["Ah yes, the first of my many improvements to the postal service. I simply glued all the fanmail to the parcels. Now we just have to deliver the parcels."] = "Ah, sí, la primera de mis muchas mejoras al servicio postal. Simplemente pegué todo el correo de fans a los paquetes. Ahora sólo nos queda entregar los paquetes.",
        ["Ah, so you just found parcels and fanmail from the same people and bundled them together. Clever!"] = "Ah, entonces encontraste paquetes y correos de fans de las mismas personas y los agrupaste. ¡Inteligente!",
        ["From the same people, that would have made more sense..."] = "De la misma gente, eso habría tenido más sentido...",
        ["Got any interesting rumours?"] = "¿Tienes algún rumor interesante?",
        ["I don't read people's mail, you can't prove anything! I mean, er, I haven't heard any rumours recently."] = "No leo el correo de la gente, ¡no puedes probar nada! Quiero decir, eh, no he escuchado ningún rumor recientemente.",
        ["Would a few coins jog your memory?"] = "¿Algunos coins te refrescarían la memoria?",
        ["Well if you were to hand me a few coins I might remember something..."] = "Bueno, si me pasaras algunos coins, tal vez recordaría algo...",
        ["Anything I can help with?"] = "¿Puedo ayudar en algo?",
        ["Well, if you could find some bone hurting juice, I may have an idea... MWAHAHAHAHAHAHA Anyway, I have no idea where to find such a thing."] = "Bueno, si pudieras encontrar un poco de jugo que lastime los huesos, puede que tenga una idea... MWAHAHAHAHAHAHA De todos modos, no tengo idea de dónde encontrar tal cosa.",
        ["I'll be taking those..."] = "Yo me llevaré esos...",
        ["*NPC may say any one of the following at random:*"] = "*El NPC puede decir cualquiera de las siguientes palabras al azar:*",
        ["Hmm, I don't really feel like sharing anything with you at the moment..."] = "Hmm, realmente no tengo ganas de compartir nada contigo en este momento...",
        ["It seems there's a conspiracy of some sort, cutting down trees and moving shruberries..."] = "Parece que hay algún tipo de conspiración, talando árboles y moviendo arbustos...",
        ["I've read some interesting things about the West Ardougne General Store, I wouldn't eat the meat pies if I were you..."] = "He leído algunas cosas interesantes sobre el West Ardougne General Store, yo no comería los pasteles de carne si fuera tú...",
        ["I saw an undelivered letter for A.R.M.S, warning them of an impending attack by Ninjas..."] = "Vi una carta no entregada para A.R.M.S, advirtiéndoles de un ataque inminente de Ninjas...",
        ["I hear 'somebody' is planning to 'take care' of Postie Pete..."] = "Escuché que 'alguien' está planeando 'cuidar' de Postie Pete...",
        ["I saw an order for 2000 cabbages from someone called 'Bryan', claims to be an expert at cabbage tossing..."] = "Vi un pedido de 2000 repollos de alguien llamado 'Bryan', que dice ser un experto en lanzar repollos...",
        ["Woah buddy! You trying to get me in trouble or something?"] = "¡Guau, amigo! ¿Estás intentando meterme en problemas o algo así?",
        ["Select an option"] = "Seleccione una opción",
        ["How's it going?"] = "¿Cómo te va?",
        ["Not bad actually, this is my second 'internship' for my brother Pete."] = "En realidad no está mal, esta es mi segunda 'pasantía' para mi hermano Pete.",
        ["He's started to listen to some of my ideas!"] = "¡Ha empezado a escuchar algunas de mis ideas!",
        ["Check out the new addition to the post office. I've installed a delivery and collection ssytem where you can exchange your stamps for items that were previously obtainable in those parcels of ours."] = "Vea la nueva incorporación a la oficina de correos. He instalado un sistema de entrega y recogida donde podrás cambiar tus sellos por artículos que anteriormente estaban disponibles en esos paquetes nuestros.",
        ["That's just one of the awesome ideas that's made it into the postal service we've got going on here."] = "Esa es solo una de las increíbles ideas que se incorporaron al servicio postal que tenemos aquí.",
        ["Anything else I should know about?"] = "¿Algo más que deba saber?",
        ["Ah yes! Since sticking fan mail to the parcel worked out so well last time, I've told Pete he should attempt to deliver any lost property you've earned wh en he delivers your daily parcel."] = "¡Ah, sí! Dado que pegar correo de admirador al paquete funcionó tan bien la última vez, le dije a Pete que debería intentar entregar cualquier propiedad perdida que hayas ganado cuando entregue tu paquete diario.",
        ["I don't read people's mail, you can't prove anything!"] = "No leo el correo de la gente, ¡no puedes probar nada!",
        ["I mean, er, I haven't heard any rumours recently."] = "Quiero decir, eh, no he escuchado ningún rumor recientemente.",
        ["Well, if you could find some bone hurting juice, I may have an idea..."] = "Bueno, si pudieras encontrar un poco de jugo que haga daño a los huesos, tal vez tenga una idea...",
        ["Anyway, I have no idea where to find such a thing."] = "De todos modos, no tengo idea de dónde encontrar algo así.",
        ["What can I do for you?"] = "¿Qué puedo hacer por ti?",
        ["Not bad actually, this is my third 'internship' for my brother Pete."] = "En realidad no está mal, esta es mi tercera 'pasantía' para mi hermano Pete.",
        ["Check out the addition to the post office. I've installed a delivery and collection system where you can exchange your stamps for items that were previously obtainable in those parcels of ours."] = "Mira la adición a la oficina de correos. He instalado un sistema de entrega y recogida donde podrás cambiar tus sellos por artículos que anteriormente se podían obtener en esos paquetes nuestros.",
        ["Ah yes! Since sticking fan mail to the parcel worked out so well last time, I've told Pete he should attempt to deliver any lost property you've earned when he delivers your daily parcel."] = "¡Ah, sí! Dado que pegar correo de admirador al paquete funcionó tan bien la última vez, le dije a Pete que debería intentar entregar cualquier propiedad perdida que hayas ganado cuando entregue tu paquete diario.",
        ["Hello Pete. What are you up to?"] = "Hola Pete. ¿Qué estás haciendo?",
        ["Parcel Pete's jawbone moves, but his voice seems to be missing."] = "La mandíbula de Parcel Pete se mueve, pero su voz parece faltar.",
        ["*Clack clack clack clack. Clack. Clack click clack clack. Clack click clack clack. Click click click.*"] = "*Clac clac clac clac. Charla. Clac, clic, clac, clac. Clac, clic, clac, clac. Haga clic, haga clic, haga clic.*",
        ["Don't mind him, Player. He's had a rough year, lost his tongue in an unfortunate stamp licking accident."] = "No le hagas caso, Player. Ha tenido un año difícil, perdió la lengua en un desafortunado accidente lamiendo un sello.",
        ["*Click clack. Click click click... Clack click. Click clack click clack. Click clack click clack. Clack clack. Click clack clack. Clack. Click clack. Click.*"] = "*Haz clic en clac. Clic, clic, clic... Clac, clic. Haga clic, clac, clic, clac. Haga clic, clac, clic, clac. Clac clac. Haz clic, clac, clac. Charla. Haga clic en clac. Haga clic.*",
        ["I could use your help actually, Player, can you come and talk with me?"] = "De hecho, me vendría bien tu ayuda, Player, ¿puedes venir a hablar conmigo?",
        ["Pete whistles a tune with very inconsistent volume, pitch and tone. It's hard to listen to, but he seems content."] = "Pete silba una melodía con volumen, tono y tono muy inconsistentes. Es difícil escucharlo, pero parece contento.",
        ["Don't mind him, Player. He's learning to whistle since losing his tongue in an unfortunate stamp licking accident last year."] = "No le hagas caso, Player. Está aprendiendo a silbar desde que perdió la lengua en un desafortunado accidente lamiendo un sello el año pasado.",
        ["*Toot fwoop. toot toot toot... Fwoop toot. Toot fwoop toot fwoop. Toot fwoop toot fwoop. Fwoop fwoop. toot fwoop fwoop. Fwoop. Toot fwoop. Toot.*"] = "*Toot fwoop. Toot toot toot... Fwoop toot. Toot fwoop toot fwoop. Toot fwoop toot fwoop. Fwoop, fwoop. Toot fwoop fwoop. Vaya. Toot fwoop. Sonar.*",
        ["Anyway, he's on distraction duty, Player, can you come and talk with me?"] = "De todos modos, él está en funciones de distracción, Player, ¿puedes venir a hablar conmigo?",
        ["Hi Pete!"] = "¡Hola Pete!",
        ["*Click click click click. Click. Click clack click click. Click clack clack click.*"] = "*Haga clic, haga clic, haga clic. Hacer clic. Haga clic, haga clic, haga clic. Haz clic, clac, clac, clic.*",
        ["Oh dear, still having trouble speaking?"] = "Dios mío, ¿todavía tienes problemas para hablar?",
        ["*cough* Oh, sorry about that, still getting used to this new tongue."] = "*tos* Oh, lo siento, todavía me estoy acostumbrando a esta nueva lengua.",
        ["Thank goodness it's you, Player; I'm worried about my brother!"] = "Gracias a Dios eres tú, Player; ¡Estoy preocupada por mi hermano!",
        ["Pete has taken on too much yet again, and he's working himself to the bone!"] = "Pete ha vuelto a asumir demasiado y ¡está trabajando hasta los huesos!",
        ["Ahaha, good one! They should call you Punny Pete."] = "¡Jajaja, buena! Deberían llamarte Punny Pete.",
        ["This isn't a laughing matter!"] = "¡Esto no es motivo de risa!",
        ["Oh, sorry. Can I help at all?"] = "Oh, lo siento. ¿Puedo ayudar en algo?",
        ["I'm sure my bother would appreciate the assistance, perhaps ask him."] = "Estoy seguro de que mi hermano agradecería la ayuda, tal vez pregúntele.",
        ["I'm busy with my own responsibilities unfortunately, Pete has given me a new route to run!"] = "Lamentablemente, estoy ocupado con mis propias responsabilidades. ¡Pete me ha dado una nueva ruta para seguir!",
        ["Could I help with that? Where is it?"] = "¿Puedo ayudar con eso? ¿Dónde está?",
        ["Um... I can handle it on my own, don't worry."] = "Um... puedo manejarlo solo, no te preocupes.",
        ["I'll just see if Postie needs my help for now then. See you around!"] = "Entonces veré si Postie necesita mi ayuda por ahora. ¡Ya nos veremos!",
    },
    ["Parroty Pete"] = {
        ["Good day, good day. Come to admire the new parrot aviary have we?"] = "Buenos días, buenos días. Venimos a admirar el nuevo aviario de loros, ¿verdad?",
        ["Select an Option"] = "Selecciona una opción",
        ["It's very nice."] = "Es muy bonito.",
        ["Isn't it just?"] = "¿No es justo?",
        ["When did you add it?"] = "¿Cuándo lo agregaste?",
        ["Just recently. It would have been sooner, but some wretch thought it would be amusing to replace their drinking water with vodka. The vet had to nurse them back to health for weeks!"] = "Recientemente. Habría sido antes, pero algún desgraciado pensó que sería divertido sustituir el agua que bebían por vodka. ¡El veterinario tuvo que cuidarlos hasta que recuperaron la salud durante semanas!",
        ["What do you feed them?"] = "¿Con qué les das de comer?",
        ["Well, fruit and wheat mostly. I try to give them a balanced diet, but their favourite treat is pineapple chunks."] = "Bueno, fruta y trigo principalmente. Intento darles una dieta equilibrada, pero su golosina favorita son los trozos de piña.",
    },
    ["Party Pete"] = {
        ["Hi!"] = "¡Hola!",
        ["Hi! I'm Party Pete. Welcome to the Party Room!"] = "¡Hola! Soy Party Pete. ¡Bienvenidos al Salón de Fiestas!",
        ["*If the achievement 'Going Along With the 'Fro' hasn't been completed:*"] = "*Si no se ha completado el logro 'Seguir con el 'Fro':*",
        ["colour=white"] = "color = blanco",
        ["Select an option"] = "Seleccione una opción",
        ["So, what's this room for?"] = "Entonces, ¿para qué es esta habitación?",
        ["So what's this room for?"] = "Entonces, ¿para qué sirve esta habitación?",
        ["This room is for partying the night away!"] = "¡Esta habitación es para salir de fiesta toda la noche!",
        ["How do you have a party?"] = "¿Cómo se hace una fiesta?",
        ["Get a few mates round, get the beers in and have fun! Some players organise parties so keep an eye open!"] = "¡Reúne algunos amigos, prepara las cervezas y diviértete! Algunos jugadores organizan fiestas, ¡así que mantente atento!",
        ["Woop! Thanks Pete!"] = "¡Vaya! Gracias Pete!",
        ["What's the big lever over there for?"] = "¿Para qué sirve la gran palanca de ahí?",
        ["Simple. With the lever you can do some fun stuff."] = "Sencillo. Con la palanca puedes hacer cosas divertidas.",
        ["What kind of stuff?"] = "¿Qué tipo de cosas?",
        ["A balloon drop costs 1000 gold. For this, you get 200 balloons dropped across the whole of the party room. You can then have fun popping the balloons! Any items in the Party Drop Chest will be put into balloons as soon as you pull the lever. When the balloons are released, you can burst them to get at the items! For 500 gold, you can summon the Party Room Knights, who will dance for your delight. Their singing isn't a delight, though!"] = "La caída de un globo cuesta 1000 de oro. Para esto, se lanzan 200 globos por toda la sala de fiestas. ¡Luego podrás divertirte haciendo estallar los globos! Cualquier artículo en el Party Drop Chest se colocará en globos tan pronto como jales la palanca. Cuando se suelten los globos, ¡puedes reventarlos para alcanzar los objetos! Por 500 de oro, puedes convocar a los Party Room Knights, que bailarán para tu deleite. ¡Sin embargo, su canto no es una delicia!",
        ["What's the gold chest for?"] = "¿Para qué es el cofre dorado?",
        ["Any items in the chest will be dropped inside the balloons when you pull the lever."] = "Cualquier objeto en el cofre caerá dentro de los globos cuando jales la palanca.",
        ["Cool! Sounds like a fun way to do a drop party."] = "¡Genial! Suena como una forma divertida de hacer una fiesta de presentación.",
        ["Exactly! A word of warning, though. Any items that you put into the chest can't be taken out again, and it costs 1000 gold pieces for each drop party."] = "¡Exactamente! Sin embargo, una palabra de advertencia. Cualquier elemento que coloques en el cofre no se puede volver a sacar y cuesta 1000 piezas de oro por cada grupo de entrega.",
        ["I wanna party!"] = "¡Quiero festejar!",
        ["I've won the Dance Trophy at the Kandarin Ball three years in a trot!"] = "¡He ganado el Trofeo de Danza en el Kandarin Ball durante tres años seguidos!",
        ["Show me your moves Pete!"] = "¡Muéstrame tus movimientos, Pete!",
        ["More."] = "Más.",
        ["I love your hair!"] = "¡Me encanta tu cabello!",
        ["Isn't it groovy? I liked it so much, I had extras made for my party goers. Would you like to buy one?"] = "¿No es genial? Me gustó tanto que hice extras para los asistentes a mi fiesta. ¿Quieres comprar uno?",
        ["Yes."] = "Sí.",
        ["Why's there a chameleon in here?"] = "¿Por qué hay un camaleón aquí?",
        ["Karma's my pet. I got him for Christmas one year. He keeps the Party Room free of flies, and he loves watching me dance. Karma karma karma cha..."] = "Karma es mi mascota. Lo compré para Navidad un año. Mantiene el salón de fiestas libre de moscas y le encanta verme bailar. Karma karma karma cha...",
        ["Can you talk to him?"] = "¿Puedes hablar con él?",
        ["Sure, I talk to the little fellow all the time. My Summoning level's not high enough to understand what he says back, but he's still great company."] = "Claro, hablo con el pequeño todo el tiempo. Mi nivel de Summoning no es lo suficientemente alto como para entender lo que me responde, pero sigue siendo una gran compañía.",
        ["Christmas is over."] = "Se acabó la Navidad.",
        ["Christmas is over. Why've you still got him hanging around?"] = "Se acabó la Navidad. ¿Por qué todavía lo tienes dando vueltas?",
        ["I couldn't chuck the little chappy out! A pet is for life!"] = "¡No podía echar al pequeño chappy! ¡Una mascota es para toda la vida!",
        ["Aww, that's nice."] = "Oh, eso es bueno.",
        ["Got any cake?"] = "¿Tienes pastel?",
        ["Do you have any cake I can have?"] = "¿Tienes algún pastel que pueda comer?",
        ["We've all sorts of groovy party treats!"] = "¡Tenemos todo tipo de delicias geniales para la fiesta!",
        ["But do you have any cake? The kind that never ends."] = "¿Pero tienes pastel? Del tipo que nunca termina.",
        ["Ah. You don't have enough room to take this cake."] = "Ah. No tienes suficiente espacio para llevar este pastel.",
        ["Don't get greedy, man, you've already got some! We need all the citizens of Gielinor to enjoy this rad cake."] = "No seas codicioso, hombre, ¡ya tienes algunos! Necesitamos que todos los ciudadanos de Gielinor disfruten de este fantástico pastel.",
        ["Here's some 25th anniversary cake! Happy anniversary, man!"] = "¡Aquí tienes un pastel del 25 aniversario! ¡Feliz aniversario, hombre!",
        ["Sadly no cake at the moment, try coming back January 1st...But the party never ends!"] = "Lamentablemente no hay pastel en este momento, intenta regresar el 1 de enero... ¡Pero la fiesta nunca termina!",
        ["Back."] = "Atrás.",
        ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
        ["You've come to the right place!"] = "¡Has venido al lugar correcto!",
        ["[Party Pete has given you another clue scroll!]"] = "[¡Party Pete te ha dado otro pergamino de pistas!]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
        ["Ask about..."] = "Pregunta sobre...",
        ["New Year Resolutions"] = "Resoluciones de año nuevo",
        ["What's all this about New Year Resolutions."] = "¿Qué es todo eso de los propósitos de Año Nuevo?",
        ["Oh thank goodness, after all those Celebration lamps for the New Year, I'm all partied out!"] = "Oh, gracias a Dios, después de todas esas lámparas de celebración del Año Nuevo, ¡estoy de fiesta!",
        ["So I thought that this year I'd make a list of New Years Resolutions."] = "Así que pensé que este año haría una lista de propósitos de Año Nuevo.",
        ["How can I help?"] = "¿Cómo puedo ayudar?",
        ["*(If a list of resolutions hasn't been claimed:)*"] = "*(Si no se ha reclamado una lista de resoluciones:)*",
        ["*(If a list of resolutions has been claimed:)*"] = "*(Si se ha reclamado una lista de resoluciones:)*",
        ["I see you've already got a copy of my list of resolutions, take a look at the list and good luck dude, we're gonna need it!"] = "Veo que ya tienes una copia de mi lista de resoluciones, échale un vistazo a la lista y buena suerte amigo, ¡la necesitaremos!",
        ["New Years Resolutions"] = "Resoluciones de Año Nuevo",
        ["New Years Resolutions?"] = "¿Resoluciones de Año Nuevo?",
        ["Yeah, it's a tradition thing. At the start of each year you choose some things to do."] = "Sí, es una tradición. Al comienzo de cada año eliges algunas cosas que hacer.",
        ["Now it could be getting fit, or giving up bad habits or trying something new!"] = "¡Ahora podría ser ponerse en forma, dejar los malos hábitos o probar algo nuevo!",
        ["Cool thanks, I'll look into it."] = "Genial, gracias, lo investigaré.",
        ["Detox drink?"] = "¿Bebida desintoxicante?",
        ["Yeah, it's my super secret recipe."] = "Sí, es mi receta súper secreta.",
        ["I could do with a hand with some of the ingredients though."] = "Aunque me vendría bien una mano con algunos de los ingredientes.",
        ["What do you need?"] = "¿Qué necesitas?",
        ["I've got a list here, take a look..."] = "Tengo una lista aquí, échale un vistazo...",
        ["*(The detox drink ingredient book opens.)*"] = "*(Se abre el libro de ingredientes de la bebida detox.)*",
        ["Ingredients list"] = "Lista de ingredientes",
        ["Can I see the list again?"] = "¿Puedo ver la lista nuevamente?",
        ["I've got some ingredients"] = "tengo algunos ingredientes",
        ["*(If a replenishment potion is in inventory and is still needed:)*"] = "*(Si hay una poción de reabastecimiento en el inventario y aún se necesita:)*",
        ["I've brought you a Replenishment Potion."] = "Te he traído una poción de reabastecimiento.",
        ["Cheers dude, that'll make my detox drink a bit more refreshing!"] = "¡Salud amigo, eso hará que mi bebida desintoxicante sea un poco más refrescante!",
        ["*(Continues below.)*"] = "*(Continúa a continuación.)*",
        ["*(If a divine simulacrum II is in inventory and is still needed:)*"] = "*(Si hay un simulacro divino II en el inventario y aún se necesita:)*",
        ["I've brought you a Divine Simulacrum II."] = "Les he traído un Simulacro Divino II.",
        ["Cheers dude, that'll give the detox drink a bit of energy!"] = "¡Salud amigo, eso le dará un poco de energía a la bebida desintoxicante!",
        ["*(If a crystal geode is in inventory and is still needed:)*"] = "*(Si hay una geoda de cristal en el inventario y aún se necesita:)*",
        ["I've brought you a Crystal Geode."] = "Te traje una geoda de cristal.",
        ["Cheers dude, that'll give the detox drink a bit of sparkle!"] = "¡Salud amigo, eso le dará un poco de brillo a la bebida desintoxicante!",
        ["*(If 120 harmonic dust is in inventory and is still needed:)*"] = "*(Si hay polvo de 120 armónicos en el inventario y aún se necesita:)*",
        ["I've brought you 120 Harmonic Dust."] = "Te he traído 120 polvo armónico.",
        ["Cheers dude, that'll give the detox drink some good vibes!"] = "¡Salud amigo, eso le dará buenas vibraciones a la bebida desintoxicante!",
        ["*(If a silverhawk feather is in inventory and is still needed:)*"] = "*(Si hay una pluma de Silverhawk en el inventario y aún se necesita:)*",
        ["I've brought you a Silverhawk Feather."] = "Te he traído una pluma Silverhawk.",
        ["Cheers dude, that'll give the detox drink a bit of a kick!"] = "¡Salud amigo, eso le dará un toque especial a la bebida desintoxicante!",
        ["*(If a basket of tomatoes is in inventory and is still needed:)*"] = "*(Si hay una canasta de tomates en el inventario y aún se necesita:)*",
        ["I've brought you a basket filled with tomatoes."] = "Te he traído una cesta llena de tomates.",
        ["Cheers dude, that'll give the detox drink a bit of flavour!"] = "¡Salud amigo, eso le dará un poco de sabor a la bebida desintoxicante!",
        ["*(If ingredients are still missing:)*"] = "*(Si aún faltan ingredientes:)*",
        ["Looks like we're still missing some ingredients dude. Run along and see if you can get them."] = "Parece que todavía nos faltan algunos ingredientes, amigo. Corre y ve si puedes conseguirlos.",
        ["*(If the task has been completed:)*"] = "*(Si la tarea ha sido completada:)*",
        ["I don't need any more ingredients right now dude."] = "No necesito más ingredientes ahora amigo.",
        ["Something else"] = "algo mas",
        ["*(Non-event dialogue.)*"] = "*(Diálogo sin evento.)*",
        ["Hey, man! It's been a while since we partied. Let me get the balloons ready..."] = "¡Oye, hombre! Ha pasado un tiempo desde que salimos de fiesta. Déjame preparar los globos...",
        ["No need, this is just a flying visit, to check something off my task list."] = "No es necesario, esta es solo una visita rápida para tachar algo de mi lista de tareas.",
        ["Sure you don't want to donate something to the party chest for the next Balloon Bonanza?"] = "¿Seguro que no quieres donar algo al cofre de la fiesta para la próxima Bonanza de Globos?",
        ["Talk to Party Pete in the Falador Party Room."] = "Habla con Party Pete en la sala de fiestas Falador.",
        ["No worries if not, friend. It's all groovy."] = "No te preocupes si no, amigo. Es todo genial.",
        ["Looks like I've completed everything. I'd better go and see Hans about that reward!"] = "Parece que he completado todo. ¡Será mejor que vaya a ver a Hans sobre esa recompensa!",
        ["Hey!"] = "¡Oye!",
        ["Hi! I'm Party Pete. Welcome to the 15th Anniversary garden!"] = "¡Hola! Soy Party Pete. ¡Bienvenidos al jardín del 15º Aniversario!",
        ["So, what's going on here?"] = "Entonces, ¿qué está pasando aquí?",
        ["It's a party! RuneScape has hit the big 15 so I'm throwing it a birthday party nobody will forget!"] = "¡Es una fiesta! ¡RuneScape ha llegado a los 15 grandes, así que le organizaré una fiesta de cumpleaños que nadie olvidará!",
        ["Even if they get too carried away with the party spirit?"] = "¿Incluso si se dejan llevar demasiado por el espíritu de fiesta?",
        ["Even then. This is a party for the ages!"] = "Incluso entonces. ¡Esta es una fiesta para todas las edades!",
        ["What are the plinths for?"] = "¿Para qué sirven los zócalos?",
        ["*If the player has not collected any of the statues*"] = "*Si el player no ha recogido ninguna de las estatuas*",
        ["They're ready to hold statues that celebrate each of the fifteen years of RuneScape. The garden will look awesome when you have them all. They can be found in the balloon drops or by finding special portals around the world. When you fins a portal have a gander and you might have a statue! It'll be delivered directly to the correct plinth, so when you find one make sure to come back here and check it out!"] = "Están listos para sostener estatuas que celebran cada uno de los quince años de RuneScape. El jardín lucirá increíble cuando los tengas todos. Se pueden encontrar en los lanzamientos de globos o buscando portales especiales en todo el mundo. ¡Cuando encuentres un portal, echa un vistazo y es posible que tengas una estatua! Se entregará directamente en el pedestal correcto, así que cuando encuentres uno, ¡asegúrate de volver aquí y comprobarlo!",
        ["*If the player has collected all of the statues*"] = "*Si el player ha recogido todas las estatuas*",
        ["They look great with all of your statues on them! Take some time to have a browse of them and really appreciate their splendour."] = "¡Se ven geniales con todas tus estatuas encima! Tómate un tiempo para echarles un vistazo y apreciar realmente su esplendor.",
        ["Tell me more about the buff."] = "Cuéntame más sobre el beneficio.",
        ["The party spirit is contagious. Just have some food from the tables, or have some of the cake, and it will give you the party spirit too! It's a 5% buff for all skilling that you do in the party area for the following 24 hours. Just click it again after the 24 hours are up to reactivate the bonus!"] = "El espíritu de fiesta es contagioso. Simplemente come algo de comida de las mesas o come un poco del pastel, ¡y eso también te dará el espíritu de fiesta! Es un beneficio del 5% para todas las habilidades que hagas en el área del grupo durante las siguientes 24 horas. ¡Simplemente haz clic nuevamente después de que transcurran las 24 horas para reactivar el bono!",
        ["It certainly seems to have worked on you!"] = "¡Ciertamente parece haber funcionado contigo!",
        ["Yep. Groovy isn't it?"] = "Sí. Genial, ¿no?",
        ["Are there any rewards?"] = "¿Hay alguna recompensa?",
        ["There are lots of fantastic rewards to go alongside the celebrations! Pop 15 balloons for a snazzy extra, and 50 balloons for a present that'll go with a bang! Get the party spirit buff, from eating from the party tables, and unlock another present, this time a tasty one!"] = "¡Hay muchas recompensas fantásticas para acompañar las celebraciones! ¡Explota 15 globos para obtener un toque elegante y 50 globos para un regalo que irá con fuerza! Obtén el beneficio del espíritu de fiesta al comer en las mesas de la fiesta y desbloquea otro regalo, ¡esta vez uno sabroso!",
        ["That all sounds good! Anything else?"] = "¡Todo eso suena bien! ¿Algo más?",
        ["Collecting statues also gives you special rewards, when you have collected 4, 8, 12, and 15. Keep your eye out for special unlock messages! Also, you can get cool things from the balloons, like party hat fragments, starts, lamps and gold, and the chance to unlock a statue!"] = "Coleccionar estatuas también te otorga recompensas especiales cuando hayas recolectado 4, 8, 12 y 15. ¡Esté atento a los mensajes de desbloqueo especiales! Además, puedes obtener cosas interesantes de los globos, como fragmentos de sombreros de fiesta, estrellas, lámparas y oro, ¡y la posibilidad de desbloquear una estatua!",
        ["How long does this party last?"] = "¿Cuánto dura esta fiesta?",
        ["Not everyone has the party stamina that I have, but we're partying hard until the end of January. The statue portals can be found until the end of the year, though, so keep hunting!"] = "No todo el mundo tiene la misma energía para la fiesta que yo, pero estaremos de fiesta hasta finales de enero. Sin embargo, los portales de las estatuas se pueden encontrar hasta fin de año, ¡así que sigue buscando!",
        ["How do the balloon drops work?"] = "¿Cómo funcionan las caídas de globos?",
        ["I've gone all out with the baloon drops for this! They are every half hour and they're at every lodestone except Prifddinas. Just look out for the announcements and confetti, and then head over and pop away! You can pop 50 balloons a day and there are great things to find inside them, like party hat fragments, stars and lamps. Also, if you pop 50 you'll get a special reward!"] = "¡Hice todo lo posible con los globos para esto! Son cada media hora y están en todos los lodestone excepto Prifddinas. ¡Solo busca los anuncios y el confeti, y luego acércate y sal! Puedes hacer estallar 50 globos al día y hay cosas maravillosas que encontrar dentro de ellos, como fragmentos de sombreros de fiesta, estrellas y lámparas. Además, si obtienes 50, ¡obtendrás una recompensa especial!",
        ["Bye."] = "Adiós.",
        ["Catch ya later alligator!"] = "¡Nos vemos luego, caimán!",
        ["Fancy seeing you here Pete, how's things?"] = "Me alegro de verte por aquí Pete, ¿cómo van las cosas?",
        ["I've seen lots of people rocking a cool new hairdo."] = "He visto a mucha gente lucir un peinado nuevo y genial.",
        ["I'd try it myself, but I just couldn't bear to lose the 'fro!"] = "Lo intentaría yo mismo, ¡pero no podía soportar perder el afro!",
        ["Not bad, not bad. I'm getting my groove on to celebrate RuneFest and as I'm sure you already know, partying happens to be one of my specialities!"] = "Nada mal, nada mal. Me estoy poniendo manos a la obra para celebrar RuneFest y, como estoy seguro de que ya sabes, ¡la fiesta es una de mis especialidades!",
        ["I don't suppose you know what I can do here?"] = "Supongo que no sabes lo que puedo hacer aquí.",
        ["Well RuneFest doesn't run all year 'round, but it's always great to kick back with some of the cool dudes and dudettes you shared the experience with there!"] = "Bueno, RuneFest no se lleva a cabo todo el año, ¡pero siempre es genial relajarse con algunos de los tipos geniales con los que compartiste la experiencia allí!",
        ["Pretty radical dude! Although, from time to time this dragon comes after me, but I'm in control of the situation now. Every time he attacks me I end up taming the beast and partying like no man's partied before! So if I'm not here partying you know where I am."] = "¡Un tipo bastante radical! Aunque, de vez en cuando este dragón viene detrás de mí, ahora tengo el control de la situación. ¡Cada vez que me ataca termino domando a the beast y festejando como ningún hombre lo ha hecho antes! Así que si no estoy aquí de fiesta ya sabes dónde estoy.",
    },
    ["Party cake (non-player character)"] = {
        ["You don't have any space to take the slice of cake."] = "No tienes espacio para coger el trozo de tarta.",
        ["You should eat the slice you already have before taking another."] = "Debes comer la porción que ya tienes antes de tomar otra.",
    },
    ["Party cake"] = {
        ["You don't have any space to take the slice of cake."] = "No tienes espacio para coger el trozo de tarta.",
        ["You should eat the slice you already have before taking another."] = "Debes comer la porción que ya tienes antes de tomar otra.",
    },
    ["Party music box (non-player character)"] = {
        ["You listen to the music..."] = "Escuchas la música...",
    },
    ["Party music box"] = {
        ["You listen to the music..."] = "Escuchas la música...",
    },
    ["Party pack (non-player character)"] = {
        ["You must free up inventory space in order to take this item."] = "Debes liberar espacio en el inventario para poder tomar este artículo.",
        ["OK"] = "bien",
    },
    ["Party pack"] = {
        ["You must free up inventory space in order to take this item."] = "Debes liberar espacio en el inventario para poder tomar este artículo.",
        ["OK"] = "bien",
    },
    ["Patchy"] = {
        ["Hello!"] = "¡Hola!",
        ["Arr? Be ye wantin' te go on account with our gang o' fillibusters?"] = "¿Llegó? ¿Quieres ir a cuenta con nuestra banda de filibusteros?",
        ["The powder monkey be takin' a caulk after gettin' rowdy on bumboo, so there be plenty of room for ye."] = "El mono de la pólvora se va a poner masilla después de ponerse alborotado en bumboo, así que habrá mucho espacio para ti.",
        ["Riiiiight..."] = "Correcto...",
        ["I'll just be over here if you need me."] = "Estaré aquí si me necesitas.",
        ["Hello there! Can I sew ye somethin' tegether?"] = "¡Hola! ¿Puedo coseros algo juntos?",
        ["What do you mean?"] = "¿Qué quieres decir?",
        ["Well, ye see it works like this; I can sew yer eye patches onto yer pirate hats or pirate bandanas."] = "Bueno, ya ves, funciona así; Puedo coserles parches en los ojos en sus sombreros de pirata o pañuelos de pirata.",
        ["Just pirate bandanas mind ye, I hate the feel of snakeskin. (Shudder)"] = "Solo pañuelos piratas, claro, odio la sensación de la piel de serpiente. (Estremecimiento)",
        ["It costs 500 gold te do it, and 600 gold te get them separated."] = "Cuesta 500 de oro hacerlo y 600 de oro separarlos.",
        ["Okay, why does it cost more to get them separated than put together?"] = "Bien, ¿por qué cuesta más separarlos que juntarlos?",
        ["Wear and tear on scissors."] = "Desgaste de las tijeras.",
        ["On another note, I also sew crab claw gauntlets on to pirate hooks, highwayman masks to black cavaliers, and mime masks to black berets, if ye have them with ye."] = "Por otra parte, también coso guanteletes de garras de cangrejo en anzuelos piratas, máscaras de bandolero para caballeros negros y máscaras de mimo para boinas negras, si las tienes contigo.",
        ["So, do ye have anything ye wants doin?"] = "Entonces, ¿tienes algo que quieras hacer?",
        ["Select an Option"] = "Selecciona una opción",
        ["Yes"] = "si",
        ["Yes please!"] = "¡Sí, por favor!",
        ["Now, do you want to be sewing items together or separating them?"] = "Ahora, ¿quieres coser prendas juntas o separarlas?",
        ["Sew together"] = "coser juntos",
        ["I'd like something sewn together."] = "Me gustaría coser algo.",
        ["Aye, pick out what items ye be wantin' sewn together."] = "Sí, elige qué artículos quieres coser juntos.",
        ["Separate"] = "Separado",
        ["I need something separated."] = "Necesito algo separado.",
        ["Aye, aye. Just use yer item on me and I'll see if I can separate them."] = "Sí, sí. Solo usa tu artículo conmigo y veré si puedo separarlos.",
        ["Fair enough. See you around!"] = "Bastante bien. ¡Ya nos veremos!",
        ["Your items have been combined!"] = "¡Tus artículos han sido combinados!",
        ["Ye don't seem te have enough free space few the two items. Ye might want te visit the bank."] = "Parece que no tienes suficiente espacio libre para los dos elementos. Quizás quieras visitar el banco.",
        ["You want me te separate these two for ye?"] = "¿Quieres que te separe estos dos?",
        ["Split this item apart? (Costs 600 coins)"] = "¿Separar este artículo? (Cuesta 600 coins)",
        ["Sorry, I can't do anythin' with that."] = "Lo siento, no puedo hacer nada con eso.",
    },
    ["Patron"] = {
        ["*Patrons will say one of the following options after being served:*"] = "*Los clientes dirán una de las siguientes opciones después de ser atendidos:*",
    },
    ["Paul (Slime is of the Essence)"] = {
        ["Oh dear..."] = "Dios mío...",
        ["I'm in charge of spot checking the explosives everyone is making!"] = "¡Estoy a cargo de comprobar los explosivos que todos están fabricando!",
        ["No slacking!"] = "¡Sin aflojar!",
        ["To me!"] = "¡A mí!",
        ["We did it!"] = "¡Lo logramos!",
        ["I knew we could, thanks for your help!"] = "Sabía que podíamos, ¡gracias por tu ayuda!",
        ["You too, we're an unstoppable team!"] = "¡Tú también, somos un equipo imparable!",
    },
    ["Paul"] = {
        ["Oh dear..."] = "Dios mío...",
        ["I'm in charge of spot checking the explosives everyone is making!"] = "¡Estoy a cargo de comprobar los explosivos que todos están fabricando!",
        ["No slacking!"] = "¡Sin aflojar!",
        ["To me!"] = "¡A mí!",
        ["We did it!"] = "¡Lo logramos!",
        ["I knew we could, thanks for your help!"] = "Sabía que podíamos, ¡gracias por tu ayuda!",
        ["You too, we're an unstoppable team!"] = "¡Tú también, somos un equipo imparable!",
        ["Who are you?"] = "¿Quién eres?",
        ["I'm Player. I was wondering if you had any quests for me?"] = "Soy Player. Me preguntaba si tenías alguna misión para mí.",
        ["I have a quest, but I need a more experienced adventurer to help with it."] = "Tengo una misión, pero necesito que un aventurero con más experiencia me ayude.",
        ["You need 34 Quest Points to start Gower Quest."] = "Necesitas 34 puntos de misión para iniciar Gower Quest.",
        ["That was my favourite quest I've ever been in."] = "Esa fue mi misión favorita en la que he estado.",
        ["Choose an option:"] = "Elige una opción:",
        ["Can I be a pmod for Cabbagemud?"] = "¿Puedo ser pmod de Cabbagemud?",
        ["No, sorry. Only players can be pmods, and only cabbages can be players."] = "No, lo siento. Sólo los jugadores pueden ser pmods y sólo las coles pueden ser jugadores.",
        ["Awwwwwww..."] = "Awwwwww...",
        ["Tell you what, you can be an honorary pmod! How about that?"] = "¡Te diré una cosa, puedes ser un pmod honorario! ¿Qué tal eso?",
        ["Yay!"] = "¡Sí!",
        ["Can you return me to the surface?"] = "¿Puedes devolverme a la superficie?",
        ["Try talking to Andrew about that. That's his kind of thing."] = "Intenta hablar con Andrew sobre eso. Ese es su tipo de cosas.",
        ["Goodbye."] = "Adiós.",
        ["Hello, Gower brothers! It's great to see you. I'm feeling nostalgic."] = "¡Hola hermanos Gower! Es genial verte. Siento nostalgia.",
        ["Nostalgia is all well and good, but don't get lost in it. Visit the past, but also look to the future!"] = "La nostalgia está muy bien, pero no te pierdas en ella. ¡Visite el pasado, pero también mire hacia el futuro!",
        ["This world was once great! For some it has remained great! And for others still, it shall be great once again!"] = "¡Este mundo alguna vez fue grandioso! ¡Para algunos ha seguido siendo genial! Y para otros aún, ¡será genial una vez más!",
        ["You're always welcome here where we're at...or you can go old school...or, hey, even visit some wild dragons in the dragon wilds..."] = "Siempre eres bienvenido aquí donde estamos... o puedes ir a la vieja escuela... o, oye, incluso visitar algunos dragones salvajes en Dragon Wilds...",
        ["Gower Power"] = "poder gower",
        ["Talk to any of the Gower brothers at their farm south of Varrock, or, next to the Life altar."] = "Habla con cualquiera de los hermanos Gower en su granja al sur de Varrock o junto al altar de la Vida.",
        ["Yeah! I'm with you!"] = "¡Sí! ¡Estoy contigo!",
        ["Looks like I've completed everything. I'd better go and see Hans about that reward!"] = "Parece que he completado todo. ¡Será mejor que vaya a ver a Hans sobre esa recompensa!",
        ["This looks like a fun adventure!"] = "¡Parece una aventura divertida!",
        ["[You've found another clue!]"] = "[¡Has encontrado otra pista!]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
    },
    ["Pauline Polaris"] = {
        ["What's going on here?"] = "¿Qué está pasando aquí?",
        ["I've livid to cure, fences to fix, patches to fertilise, I'm exhausted and-"] = "Tengo furia por curar, cercas que arreglar, parches que fertilizar, estoy exhausto y-",
        ["Hold on, hold on. Take a deep breath and start from the beginning."] = "Espera, espera. Respira hondo y empieza desde el principio.",
        ["Sorry, this farming is so new to me. A while ago, I was approached by the dashing and brave Lokar Searunner."] = "Lo siento, esta agricultura es muy nueva para mí. Hace un tiempo, se me acercó el apuesto y valiente Lokar Searunner.",
        ["Dashing and brave? I might be thinking of a different guy: a pirate who ferried me to a pirate ship."] = "¿Apuesto y valiente? Quizás esté pensando en otro tipo: un pirata que me llevó a un barco pirata.",
        ["No, that sounds right. In a courageous trip to Karamja, he came across a funny chap called Papa Mambo. Lokar obtained some saplings from a vine that grows in the region and brought them to me. He wanted me to grow and enhance the vine using my magic. We did an experiment on one sapling and quickly discovered that magic enhanced the tenacious attributes of the plant."] = "No, eso suena bien. En un valiente viaje a Karamja, se encontró con un tipo divertido llamado Papa Mambo. Lokar obtuvo algunos retoños de una vid que crece en la región y me los trajo. Quería que creciera y mejorara la vid usando mi magia. Hicimos un experimento con un árbol joven y rápidamente descubrimos que la magia realzaba los atributos tenaces de la planta.",
        ["Lokar named them 'livid'."] = "Lokar los llamó \"lívidos\".",
        ["Livid?"] = "¿Lívido?",
        ["Yes, it likely stands for something clever. But it is clearly quite livid!"] = "Sí, probablemente signifique algo inteligente. ¡Pero claramente está bastante lívido!",
        ["Hmm, I might have to pay a visit to Lokar. I shudder to think what he might be using this 'livid' for."] = "Hmm, quizás tenga que visitar a Lokar. Me estremezco al pensar para qué podría estar usando este \"lívido\".",
        ["Don't be mean: he has admirable intentions. He plans to transport what I grow to Chieftain Brundt, to help protect their village from wild beasts."] = "No seas malo: tiene intenciones admirables. Planea transportar lo que cultivo al cacique Brundt, para ayudar a proteger su aldea de las bestias salvajes.",
        ["Against wild beasts? The livid do sound vicious, I suppose."] = "¿Contra las fieras? Los lívidos suenan crueles, supongo.",
        ["They definitely are. They have a mind of their own, and they carry on living even when cut from their roots. In exchange for the plants, Chieftain Brundt is kindly giving the Moon Clan some trade produce."] = "Definitivamente lo son. Tienen mente propia y siguen viviendo incluso cuando están cortados de raíz. A cambio de las plantas, el cacique Brundt tiene la amabilidad de darle al Clan de la Luna algunos productos comerciales.",
        ["So, how can I help out on your farm?"] = "Entonces, ¿cómo puedo ayudar en tu granja?",
        ["Let me show you!"] = "¡Déjame mostrártelo!",
        ["There are a variety of tasks you can help me out with here. You can do them in any order or just focus on individual tasks, if you want."] = "Hay una variedad de tareas con las que puedes ayudarme aquí. Puedes hacerlos en cualquier orden o simplemente concentrarte en tareas individuales, si lo deseas.",
        ["If you don't perform the tasks, I will eventually advance the farm on to its next stage, but don't expect any reward!"] = "Si no realizas las tareas, eventualmente haré avanzar la granja a la siguiente etapa, ¡pero no esperes ninguna recompensa!",
        ["First there's fertilising patches. I've buried saplings on these patches and they will need fertilising to appear."] = "Primero, están las zonas de fertilización. He enterrado árboles jóvenes en estos parches y necesitarán fertilización para aparecer.",
        ["So, cast the Fertilise Soil spell on the patch..."] = "Entonces, lanza el hechizo Fertilizar suelo en el parche...",
        ["...then the livid will grow and you'll get further knowledge in Magic and Farming."] = "...entonces la furia crecerá y obtendrás más conocimientos sobre Magic y Farming.",
        ["Eventually, the livid will mature..."] = "Con el tiempo, la furia madurará...",
        ["...but you will see that my plants get diseased quite often."] = "...pero verás que mis plantas se enferman con bastante frecuencia.",
        ["It seems they are susceptible to the parasites native to this isle. Cast the Cure Plant spell on the crop and, after a little refinement..."] = "Parece que son susceptibles a los parásitos nativos de esta isla. Lanza el hechizo Cure Plant sobre el cultivo y, después de un poco de refinamiento...",
        ["...Bingo! The livid is fine, and Magic and Farming experience are yours."] = "...¡Bingo! La furia está bien y la experiencia Magic y Farming es tuya.",
        ["It's really tiring running this farm, so, sometimes, I'll need some help."] = "Es muy agotador administrar esta granja, así que, a veces, necesitaré ayuda.",
        ["Simply give me a few encouraging words and I'll be able to draw upon your run energy, making me right-as-rain."] = "Simplemente dame algunas palabras de aliento y podré aprovechar tu energía al correr, lo que me hará sentir como la lluvia.",
        ["In exchange, you'll receive some experience in Agility. I can recover slowly by myself, but your assistance would be much appreciated."] = "A cambio, recibirás algo de experiencia en Agility. Puedo recuperarme lentamente por mi cuenta, pero agradecería mucho su ayuda.",
        ["Once I harvest the livid, I'll teleport it over to the produce pile."] = "Una vez que coseche el lívido, lo teletransportaré a la pila de productos.",
        ["It is here that you can grab up to ten livid and bunch them together with string using the String Jewellery spell."] = "Es aquí donde puedes agarrar hasta diez lívidos y agruparlos con una cuerda usando el hechizo Joyería de cuerdas.",
        ["Then, place the bundled produce in the trade wagon. With this last step, you'll get experience in Magic and Crafting."] = "Luego, coloca el paquete de productos en el vagón comercial. Con este último paso, obtendrás experiencia en Magic y Crafting.",
        ["Why is there a big pile of lumber, I hear you ask? Our fences often get into a state of disrepair. I'm not sure if it's the pesky suqah or the sea breeze, but the wood doesn't last very long here. Pick up some lunar lumber from the corner of the farm and use the Plank Make spell to turn them into fence posts."] = "¿Por qué hay una gran pila de madera? Te oigo preguntar. Nuestras vallas a menudo se deterioran. No estoy seguro de si es la molesta suqah o la brisa del mar, pero la madera no dura mucho aquí. Recoge un poco de madera lunar de la esquina de la granja y usa el hechizo Hacer tabla para convertirla en postes para cerca.",
        ["Then use the post on the broken fence. You'll get Magic and Construction experience for your effort upon affixing the post."] = "Luego usa el poste en la cerca rota. Obtendrás experiencia Magic y Construction por tu esfuerzo al publicar la publicación.",
        ["So, there you have it!"] = "¡Ahí lo tienes!",
        ["Hi Pauline."] = "Hola Paulina.",
        ["Oh, hi. How can I help you?"] = "Oh, hola. ¿Le puedo ayudar en algo?",
        ["Select an Option"] = "Selecciona una opción",
        ["Can you tell me how to work on your farm?"] = "¿Puedes decirme cómo trabajar en tu granja?",
        ["Sure, what part of the farm do you want to know about?"] = "Claro, ¿qué parte de la granja quieres saber?",
        ["How can I fertilise the soil?"] = "¿Cómo puedo fertilizar el suelo?",
        ["After I've harvested a patch, I will replant a livid seed and it will need fertilising for it to appear."] = "Después de haber cosechado un parche, replantaré una semilla lívida y necesitará fertilización para que aparezca.",
        ["I'll get around to this eventually, but, if you cast the Fertilise Soil spell on the patch, you'll get further knowledge in Magic and Farming."] = "Llegaré a esto con el tiempo, pero si lanzas el hechizo Fertilizar suelo en el parche, obtendrás más conocimientos en Magic y Farming.",
        ["How can I cure the diseased plants?"] = "¿Cómo puedo curar las plantas enfermas?",
        ["You will see my plants get diseased quite a lot. It seems they are susceptible to the parasites native to this isle. Cast the Cure Plant spell on the crop and you'll then have to refine your spell to the particular strain of livid you see growing in that patch. Then, bingo: Magic and Farming experience are all yours. If you don't manage to do this, I'll do it myself, although there's no reward in it for you if I do."] = "Verás que mis plantas se enferman bastante. Parece que son susceptibles a los parásitos nativos de esta isla. Lanza el hechizo Cure Plant en el cultivo y luego tendrás que refinar tu hechizo para la cepa particular de lívido que ves creciendo en ese parche. Entonces, bingo: la experiencia Magic y Farming es toda tuya. Si no logras hacer esto, lo haré yo mismo, aunque no hay recompensa para ti si lo hago.",
        ["How can I re-energise you?"] = "¿Cómo puedo revitalizarte?",
        ["Ah, you've noticed how tiring it is running this farm. Well, you can simply cast the Energy Transfer spell on me, followed by a few encouraging words, and I'll be right-as-rain. In exchange, you'll receive some Magic and Agility experience. I can recover by myself, but your assistance would be much appreciated."] = "Ah, has notado lo agotador que es administrar esta granja. Bueno, simplemente puedes lanzarme el hechizo Transferencia de energía, seguido de unas cuantas palabras de aliento, y estaré como la lluvia. A cambio, recibirás experiencia Magic y Agility. Puedo recuperarme solo, pero agradecería mucho su ayuda.",
        ["What do I do with the pile of produce?"] = "¿Qué hago con la pila de productos?",
        ["When I harvest the livid, I'll teleport it over to the produce pile. Here, you can grab up to ten livid and then bunch them together with string using the String Jewellery spell. Then, place the bunched produce in the trade wagon. With this last step, you'll get experience in Magic and Crafting. Be quick, though: like the other tasks, I'll end up doing it myself."] = "Cuando coseche el lívido, lo teletransportaré a la pila de productos. Aquí, puedes agarrar hasta diez lívidos y luego agruparlos con una cuerda usando el hechizo Joyería de hilo. Luego, coloca los productos agrupados en el vagón comercial. Con este último paso, obtendrás experiencia en Magic y Crafting. Pero sé rápido: al igual que las otras tareas, terminaré haciéndolas yo mismo.",
        ["How do I fix the fences?"] = "¿Cómo arreglo las vallas?",
        ["So, you've spotted that the fences often get into a state of disrepair. I'm not sure if it's those pesky suqah or the sea air, but the wood here doesn't last very long. Pick up some Lunar lumber from the corner of the farm and use the Plank Make spell to turn them into fence posts. Then, simply use them on the broken fence. You'll get Magic and Construction experience for your effort upon affixing the post."] = "Entonces, has notado que las cercas a menudo se deterioran. No estoy seguro si son esos molestos suqah o el aire del mar, pero la madera aquí no dura mucho. Recoge un poco de madera lunar de la esquina de la granja y usa el hechizo Plank Make para convertirla en postes de cerca. Luego, simplemente úsalos en la valla rota. Obtendrás experiencia Magic y Construction por tu esfuerzo al publicar la publicación.",
        ["What rewards will I get?"] = "¿Qué recompensas recibiré?",
        ["Mainly experience in your Magic, Farming, Crafting, Agility and Construction skills. I think you'll find your time and effort is well rewarded. You can cast all the spells regardless of your Magic level, but you won't get the Magic XP if you don't have the correct level. I'll also keep an eye on how much produce you're helping to create and, after so much work, it's only fair that I teach you the secrets of some new spells! Each task enables me to ship more produce over to Chieftain Brundt. Here, let me show you."] = "Principalmente experiencia en tus habilidades Magic, Farming, Crafting, Agility y Construction. Creo que encontrará que su tiempo y esfuerzo serán bien recompensados. Puedes lanzar todos los hechizos independientemente de tu nivel de Magic, pero no obtendrás el XP de Magic si no tienes el nivel correcto. También estaré atento a la cantidad de productos que estás ayudando a crear y, después de tanto trabajo, ¡es justo que te enseñe los secretos de algunos hechizos nuevos! Cada tarea me permite enviar más productos a Chieftain Brundt. Aquí, déjame mostrarte.",
        ["Can I claim some rewards now?"] = "¿Puedo reclamar algunas recompensas ahora?",
        ["Can you tell me more about why you started this farm?"] = "¿Puedes contarme más sobre por qué empezaste esta granja?",
        ["Sure. Like I said, Lokar brought me this strain of vine and asked me to enhance it for Chieftain Brundt's use in protecting the province. I imagine it would work well as a particularly vicious fence!"] = "Claro. Como dije, Lokar me trajo esta cepa de vid y me pidió que la mejorara para que el cacique Brundt la use en la protección de la provincia. ¡Me imagino que funcionaría bien como una valla particularmente cruel!",
        ["I get that, but why help Lokar? He's a pirate. How can you trust him?"] = "Lo entiendo, pero ¿por qué ayudar a Lokar? Es un pirata. ¿Cómo puedes confiar en él?",
        ["A pirate?"] = "¿Un pirata?",
        ["I don't think so. He travels the sea in search of treasure and fortune; such an adventurer! I think he's excellent and so exciting."] = "No lo creo. Viaja por el mar en busca de tesoros y fortuna; ¡Qué aventurero! Creo que es excelente y muy emocionante.",
        ["I'm not sure that's true."] = "No estoy seguro de que eso sea cierto.",
        ["I'm not sure that's true. I doubt the innocents he attacks and the villagers he plunders would see it that way."] = "No estoy seguro de que sea cierto. Dudo que los inocentes a los que ataca y los aldeanos a los que saquea lo vean así.",
        ["What? Don't be silly, he's nothing like that. He's travelled to distant lands, experienced the many cultures of our world! He's a fabulous man!"] = "¿Qué? No seas tonto, él no es nada de eso. ¡Ha viajado a tierras lejanas y ha experimentado las muchas culturas de nuestro mundo! ¡Es un hombre fabuloso!",
        ["I'm glad you've found someone that makes you happy."] = "Me alegra que hayas encontrado a alguien que te haga feliz.",
        ["Thank you. I do hope he'll visit me soon."] = "Gracias. Espero que me visite pronto.",
        ["What of giving away the secrets of the Moon Clan magic?"] = "¿Qué tal si revelas los secretos de la magia del Clan Luna?",
        ["It's true, our knowledge is most sacred, but, this way they only receive the end-product of that knowledge. It still rests with the likes of me and, to some extent, you."] = "Es cierto, nuestro conocimiento es muy sagrado, pero de esta manera ellos solo reciben el producto final de ese conocimiento. Todavía corresponde a personas como yo y, hasta cierto punto, a usted.",
        ["Well, you seem to have it all under control."] = "Bueno, parece que lo tienes todo bajo control.",
        ["Yes, I know what I'm doing. You should go talk to Lokar at the dock in Rellekka. If you see him, tell him to come and visit me soon!"] = "Sí, sé lo que estoy haciendo. Deberías ir a hablar con Lokar en el muelle de Rellekka. ¡Si lo ves, dile que venga a visitarme pronto!",
        ["I hope Lokar sees this the same way as you do."] = "Espero que Lokar vea esto de la misma manera que tú.",
        ["I'm sure he does. You should go and talk to him yourself at the dock in Rellekka. If you see him, tell him to come and visit me soon!"] = "Estoy seguro de que sí. Deberías ir a hablar con él tú mismo al muelle de Rellekka. ¡Si lo ves, dile que venga a visitarme pronto!",
        ["See you around!"] = "¡Nos vemos por ahí!",
        ["See you around."] = "Nos vemos por ahí.",
        ["I do hope so."] = "Eso espero.",
        ["Oh, hi. I heard word from Papa Mambo."] = "Oh, hola. Escuché noticias de Papa Mambo.",
        ["Oh? Yes, I've done some work down there on Karamja. How did you hear from him?"] = "¿Ah? Sí, he trabajado un poco en Karamja. ¿Cómo supiste de él?",
        ["Lokar went to barter for some more seeds-"] = "Lokar fue a hacer trueque por más semillas.",
        ["I doubt 'barter' is the correct term for it, but go on."] = "Dudo que \"trueque\" sea el término correcto, pero continúa.",
        ["Apparently, Papa Mambo keeps talking about a great farmer called [Player] and he's really impressed with the way they have been managing the Jade Vine."] = "Aparentemente, Papa Mambo sigue hablando de un gran granjero llamado [Player] y está realmente impresionado con la forma en que han estado administrando Jade Vine.",
        ["Hurrah for me!"] = "¡Hurra por mí!",
        ["It gets better. He handed Lokar a strange vial, which I'll now pass on to you! Apparently, it'll help increase your knowledge of Farming."] = "Se pone mejor. ¡Le entregó a Lokar un extraño frasco, que ahora te pasaré a ti! Aparentemente, te ayudará a aumentar tus conocimientos sobre Farming.",
        ["Pauline hands you a strange-looking vial."] = "Pauline te entrega un frasco de aspecto extraño.",
        ["Thanks!"] = "¡Gracias!",
        ["It's better to talk to Pauline about her farm first."] = "Es mejor hablar primero con Pauline sobre su granja.",
        ["You need to learn the spells in order."] = "Necesitas aprender los hechizos en orden.",
        ["You've helped me lods! Let me teach you about the Teleport to South Falador spell."] = "¡Me has ayudado mucho! Déjame enseñarte sobre el hechizo Teletransportarse al Sur Falador.",
        ["[Congratulations! You've learned how to cast the Teleport to South Falador spell.]"] = "[¡Felicitaciones! Has aprendido a lanzar el hechizo Teletransporte al sur Falador.]",
        ["You've really contributed to this farm! I'll teach you about the Repair Rune Pouch spell."] = "¡Realmente has contribuido a esta granja! Te enseñaré sobre el hechizo Reparar bolsa de runas.",
        ["[Congratulations! You've learned how to cast the Repair Rune Pouch spell.]"] = "[¡Felicitaciones! Has aprendido a lanzar el hechizo Reparar bolsa de runas.]",
        ["You've really helped make a difference! I'll teach you about the Teleport to North Ardougne spell."] = "¡Realmente has ayudado a marcar la diferencia! Te enseñaré sobre el hechizo Teletransportarse al Norte Ardougne.",
        ["[Congratulations! You've learned how to cast the Teleport to North Ardougne spell.]"] = "[¡Felicitaciones! Has aprendido a lanzar el hechizo Teletransporte al norte Ardougne.]",
        ["You've done so much work! I'll teach you about the Remote Farming spell."] = "¡Has trabajado mucho! Te enseñaré sobre el hechizo Remoto Farming.",
        ["[Congratulations! You've learned how to cast the Remote Farming spell.]"] = "[¡Felicitaciones! Has aprendido a lanzar el hechizo Remoto Farming.]",
        ["You've helped me so much! I'll teach you about the Spiritual Healing spell."] = "¡Me has ayudado mucho! Te enseñaré sobre el hechizo de Sanación Espiritual.",
        ["[Congratulations! You've learned how to cast the Spiritual Healing spell.]"] = "[¡Felicitaciones! Has aprendido a lanzar el hechizo de curación espiritual.]",
        ["You've been doing a great job! I'll teach you about the Make Leather spell."] = "¡Has estado haciendo un gran trabajo! Te enseñaré sobre el hechizo Hacer cuero.",
        ["[Congratulations! You've learned how to cast the Make Leather spell.]"] = "[¡Felicitaciones! Has aprendido a lanzar el hechizo Hacer cuero.]",
        ["You've been a fantastic help! I'll teach you about the Disruption Shield spell."] = "¡Has sido de gran ayuda! Te enseñaré sobre el hechizo Escudo de disrupción.",
        ["[Congratulations! You've learned how to cast the Disruption Shield spell.]"] = "[¡Felicitaciones! Has aprendido a lanzar el hechizo Escudo de interrupción.]",
        ["You've gone far in building up this farm! I'll teach you about the Vengeance Group spell."] = "¡Has llegado lejos en la construcción de esta granja! Te enseñaré sobre el hechizo del Grupo Venganza.",
        ["[Congratulations! You've learned how to cast the Vengeance Group spell.]"] = "[¡Felicitaciones! Has aprendido a lanzar el hechizo Grupo Venganza.]",
        ["You've been really helpful! I'll teach you about the Teleport to Trollheim spell."] = "¡Has sido de gran ayuda! Te enseñaré sobre el hechizo Teletransportarse a Trollheim.",
        ["[Congratulations! You've learned how to cast the Teleport to Trollheim spell.]"] = "[¡Felicitaciones! Has aprendido a lanzar el hechizo Teletransporte a Trollheim.]",
        ["You've made a real difference to this farm! Let me teach you about the Trollheim group Teleport spell."] = "¡Has marcado una verdadera diferencia en esta granja! Déjame enseñarte sobre el hechizo Teletransporte del grupo Trollheim.",
        ["[Congratulations! You've learned how to cast the Teleport Group to Trollheim spell.]"] = "[¡Felicitaciones! Has aprendido cómo lanzar el hechizo Teletransportar grupo a Trollheim.]",
        ["You must talk to Pauline before interacting with her farm."] = "Debes hablar con Pauline antes de interactuar con su granja.",
        ["[Pauline's currently fine.]"] = "[Pauline está actualmente bien.]",
        ["*A random dialogue is selected each time Encourage is pressed*"] = "*Se selecciona un diálogo aleatorio cada vez que se presiona Encourage*",
        ["*Option 1*"] = "*Opción 1*",
        ["Choose a line to encourage Pauline."] = "Elija una línea para animar a Pauline.",
        ["Lazybones!"] = "¡Perezosos!",
        ["Pauline didn't seem inspired."] = "Pauline no parecía inspirada.",
        ["Slow-coach!"] = "¡Entrenador lento!",
        ["Sleepy!"] = "¡Sueño!",
        ["Extraordinary!"] = "¡Extraordinario!",
        ["You encourage Pauline with your inspiring words!"] = "¡Animas a Pauline con tus inspiradoras palabras!",
        ["*Option 2*"] = "*Opción 2*",
        ["Come on, you're doing so well."] = "Vamos, lo estás haciendo muy bien.",
        ["Come on or I'm going home."] = "Vamos o me voy a casa.",
        ["Come on, you're rubbish."] = "Vamos, eres basura.",
        ["Come on and help, lazy."] = "Ven y ayuda, vago.",
        ["*Option 3*"] = "*Opción 3*",
        ["You're doing a slow job."] = "Estás haciendo un trabajo lento.",
        ["You're not doing a fantastic job."] = "No estás haciendo un trabajo fantástico.",
        ["You're doing a fantastic job."] = "Estás haciendo un trabajo fantástico.",
        ["You're doing okay, I suppose."] = "Lo estás haciendo bien, supongo.",
        ["*Option 4*"] = "*Opción 4*",
        ["Lokar won't appreciate this."] = "A Lokar no le gustará esto.",
        ["Lokar will really appreciate this."] = "Lokar realmente lo apreciará.",
        ["I don't know why you bother."] = "No sé por qué te molestas.",
        ["Hello? Anybody there?"] = "Hola? ¿Hay alguien ahí?",
        ["*Option 5*"] = "*Opción 5*",
        ["Everyone's working except you."] = "Todos están trabajando menos tú.",
        ["Care to join me?"] = "¿Quieres unirte a mí?",
        ["Look at all the produce being made."] = "Mire todos los productos que se fabrican.",
        ["Wakey wakey."] = "Despierta, despierta.",
        ["*Option 6*"] = "*Opción 6*",
        ["Keep going! I'm not doing this."] = "¡Sigue adelante! No voy a hacer esto.",
        ["Keep going! We can do this."] = "¡Sigue adelante! Podemos hacer esto.",
        ["Keep away! I'll do this."] = "¡Manténgase alejado! Yo haré esto.",
        ["Today would be nice!"] = "¡Hoy estaría bien!",
        ["**Suqah** Rrrghhh!"] = "**Suqa** Rrrghhh!",
        ["It's raining seeds! You'll find them dropping on the ground for the next few seconds. Be quick to pick them up before they vanish!"] = "¡Está lloviendo semillas! Los encontrarás cayendo al suelo durante los próximos segundos. ¡Recógelos rápidamente antes de que desaparezcan!",
        ["Ta-da!"] = "¡Ta-da!",
        ["You don't have any clean herbs to put into vials."] = "No tienes hierbas limpias para poner en viales.",
        ["There you go. I put [number] herbs into vials. Remember, in future, that this wish will do up to 50 in one go."] = "Ahí lo tienes. Puse hierbas [número] en viales. Recuerda, en el futuro, que este deseo cumplirá hasta 50 de una sola vez.",
        ["There you go."] = "Ahí lo tienes.",
        ["You need at least 3 lunar lumber for them to be converted, although it's best to have a full inventory of them."] = "Necesitas al menos 3 maderas lunares para convertirlas, aunque es mejor tener un inventario completo de ellas.",
        ["To make the most of this wish, you're better off having a full inventory of lunar lumber. Still, I can do it on the ones you are holding."] = "Para aprovechar al máximo este deseo, es mejor que tengas un inventario completo de madera lunar. Aún así, puedo hacerlo con los que tienes.",
        ["**CONVERT THE LUMBER BUT RECEIVE FEWER RUNES?**"] = "**¿CONVERTIR LA MADERA PERO RECIBIR MENOS RUNAS?**",
        ["Yes."] = "Sí.",
        ["There you go!"] = "¡Ahí lo tienes!",
        ["There you go, your 'Reduce the Fish I Burn' wish is active."] = "Ahí lo tienes, tu deseo 'Reducir el pescado que quemo' está activo.",
        ["There you go, your 'More Planks Please' wish is active."] = "Ahí lo tienes, tu deseo 'Más Planks, por favor' está activo.",
        ["There you go: a vegetable patch to help keep you occupied. It will vanish when you next clear it."] = "Ahí lo tienes: un huerto que te ayudará a mantenerte ocupado. Desaparecerá la próxima vez que lo borre.",
        ["You are still under the effect of this wish."] = "Aún estás bajo el efecto de este deseo.",
        ["Your Borrowed power spell is already unset!"] = "¡Tu hechizo de poder prestado ya no está activado!",
        ["You are about to reset [number] charges of [Spell]. It will cost you 18,000 produce points to set it again. Are you sure?"] = "Estás a punto de restablecer los cargos de [número] de [Spell]. Le costará 18.000 puntos de producción volver a configurarlo. ¿Está seguro?",
        ["**UNSET BORROWED POWER?**"] = "**¿PODER PRESTADO DESCONFIGADO?**",
        ["Yes"] = "si",
        ["There you go: Borrowed Power spell has been unset."] = "Ahí lo tienes: el hechizo Poder prestado se ha desarmado.",
        ["**WHICH SPELL WOULD YOU LIKE TO STORE?**"] = "**¿QUÉ HECHIZO TE GUSTARÍA ALMACENAR?**",
        ["Elemental Wave Spells"] = "Hechizos de ondas elementales",
        ["Air Wave"] = "Onda de aire",
        ["Water Wave"] = "Ola de agua",
        ["Earth Wave"] = "Onda terrestre",
        ["Fire Wave"] = "Ola de fuego",
        ["Combat spells"] = "Hechizos de combate",
        ["Entangle"] = "enredar",
        ["Enfeeble"] = "debilitar",
        ["Vulnerability"] = "Vulnerabilidad",
        ["Slayer Dart"] = "Dardo Slayer",
        ["Smoke Cloud"] = "Nube de humo",
        ["Transmutation spells"] = "Hechizos de transmutación",
        ["High Level Alchemy"] = "Alquimia de alto nivel",
        ["Bones to Peaches"] = "Huesos a melocotones",
        ["Telekinetic Grab"] = "Agarre telequinético",
        ["House Teleport"] = "Teletransporte de la casa",
        ["You need [number] [runes] in your inventory to set Borrowed Power to this spell."] = "Necesitas [número] [runes] en tu inventario para configurar Borrowed Power para este hechizo.",
        ["You set Borrowed Power to [Spell]."] = "Estableciste Potencia prestada en [Spell].",
        ["Borrowed Power still has [number] charges left of [Spell]. Would you like to get those charges refunded and change the spell?"] = "A Borrowed Power todavía le quedan cargos [número] de [Spell]. ¿Le gustaría que le reembolsaran esos cargos y cambiar el hechizo?",
        ["You need one free space in your inventory for this wish."] = "Necesitas un espacio libre en tu inventario para este deseo.",
        ["Use that scroll on a patch that you would like protected. That patch must already have something growing in it and what's growing cannot be diseased. If you have the right produce in your inventory, that patch will be protected for the next ten times you grow that crop in it."] = "Utilice ese desplazamiento en un parche que le gustaría proteger. En ese parche ya debe haber algo creciendo y lo que está creciendo no puede estar enfermo. Si tiene los productos adecuados en su inventario, esa parcela estará protegida durante las próximas diez veces que cultive ese cultivo en ella.",
        ["*One of these messages appears each time the farm advances by one cycle.*"] = "*Uno de estos mensajes aparece cada vez que la granja avanza un ciclo.*",
        ["You're doing SO well."] = "Lo estás haciendo MUY bien.",
        ["*sigh*"] = "*suspiro*",
        ["WHAT WOULD YOU LIKE TO DO?"] = "¿QUÉ TE GUSTARÍA HACER?",
        ["Ask about their request."] = "Pregunta sobre su solicitud.",
        ["What're you requesting today?"] = "¿Qué pides hoy?",
        ["I've been working on my own farm recently and need a few items to bolster my productivity!"] = "¡He estado trabajando en mi propia granja recientemente y necesito algunos artículos para aumentar mi productividad!",
        ["I'm trying to get some extra crops going, so I'll need : [Seed] x [number]"] = "Estoy intentando conseguir algunos cultivos adicionales, así que necesitaré: [Seed] x [número]",
        ["I'm also looking for a new animal, I'm currently after one of the following : [Animal], or [Animal], or [Animal]"] = "También estoy buscando un nuevo animal. Actualmente busco uno de los siguientes: [Animal], o [Animal], o [Animal].",
        ["I'm also looking for some produce, so I'll need : [Produce] x [number]"] = "También estoy buscando algunos productos, así que necesitaré: [Produce] x [número]",
        ["If you complete this, I'll give you : Livid plant x 1. I'm sure you'll gain some reputation with the farming guild too!"] = "Si completas esto, te daré: Planta lívida x 1. ¡Estoy seguro de que también ganarás reputación en el gremio de agricultores!",
        ["You'll have to be quick though!, I'm only here for [number] days, [number] hours and [number] minutes. To be exact."] = "¡Tendrás que ser rápido!, solo estoy aquí por [número] días, [número] horas y [número] minutos. Para ser exactos.",
        ["Give them the items & animals for their request"] = "Dales los artículos y animales que soliciten.",
        ["You don't have enough items to fulfil my request. I won't take favourited animals."] = "No tienes suficientes artículos para cumplir con mi solicitud. No aceptaré animales favoritos.",
        ["For completing this request you've received Brassica primer x 1."] = "Por completar esta solicitud, recibió 1 imprimación para Brassica.",
        ["[You've received : Livid plant x 1 And 5,500 farming reputation.]"] = "[Has recibido: Planta lívida x 1 Y 5500 de reputación agrícola.]",
        ["Thank you for your help!"] = "¡Gracias por tu ayuda!",
        ["A new request will be available in [time]"] = "Una nueva solicitud estará disponible en [time]",
        ["You've already completed this request, there will be a new tri-daily request in [time]"] = "Ya has completado esta solicitud, habrá una nueva solicitud tridiaria en [time]",
    },
    ["Peasant"] = {
        ["Woe is me! Our crops are all failing... how shall I feed myself this winter?"] = "¡Ay de mí! Todas nuestras cosechas están fallando... ¿Cómo me alimentaré este invierno?",
        ["Oh happy day! Suddenly our crops are growing again! It'll be a bumper harvest this year!"] = "¡Oh, feliz día! ¡De repente nuestros cultivos vuelven a crecer! ¡Será una cosecha excelente este año!",
    },
    ["Peckish"] = {
        ["You got any of that good stuff for me?"] = "¿Tienes algo de eso bueno para mí?",
        ["Select an Option"] = "Selecciona una opción",
        ["What are you after?"] = "¿Qué buscas?",
        ["Valuables, riches, long lost treasures. Anything I can sell to help fill the clan coffers."] = "Objetos de valor, riquezas, tesoros perdidos hace mucho tiempo. Cualquier cosa que pueda vender para ayudar a llenar las arcas del clan.",
        ["You see, things around here don't tend to stay buried. Some of these tombs are so laden in riches they're quite literally bursting."] = "Verás, las cosas por aquí no tienden a permanecer enterradas. Algunas de estas tumbas están tan cargadas de riquezas que literalmente están a punto de estallar.",
        ["Every now and then coffins and mausoleums will spring open and become accessible to any nearby light-fingered folk."] = "De vez en cuando, los ataúdes y mausoleos se abren y se vuelven accesibles para cualquier persona cercana con dedos ligeros.",
        ["If any of these ancient curios do somehow find their way into your possession I'd be happy to pay for them; I've got quite a reputable fence."] = "Si alguna de estas curiosidades antiguas de alguna manera llega a tus manos, estaré feliz de pagar por ellas; Tengo una valla bastante respetable.",
        ["I've got some goods for you."] = "Tengo algunos productos para ti.",
        ["Sssh, ssh! Keep it down. Let me see what you've got there..."] = "¡Sssh, ssh! Mantenlo bajo. Déjame ver qué tienes ahí...",
        ["You have nothing to give to Peckish."] = "No tienes nada que darle a Peckish.",
        ["You hand over [number] [valuable/valuables] and [number] riches for [number before potential multiplication] Spooky tokens."] = "Entregas riquezas [número] [valuable/valuables] y [número] por tokens Spooky [number before potential multiplication].",
        ["The following has been added to your currency pouch: [number after potential multiplication] x Spooky tokens."] = "Se ha agregado lo siguiente a su bolsa de divisas: [number after potential multiplication] x tokens Spooky.",
        ["Woah there, friend. That's too rich for my bones. I can take some of those, but you'll have to spend some spooky tokens before I take the rest."] = "Vaya, amigo. Eso es demasiado rico para mis huesos. Puedo tomar algunas de esas, pero tendrás que gastar algunas fichas espeluznantes antes de que tome el resto.",
        ["You have reached the Spooky token soft cap of 150,000. You need to spend some tokens in the Spooky Reward Shop before you can earn more."] = "Ha alcanzado el límite flexible del token Spooky de 150.000. Debes gastar algunas fichas en Spooky Reward Shop antes de poder ganar más.",
        ["The following has been added to your currency pouch: [number] x Spooky tokens."] = "Se ha agregado lo siguiente a su bolsa de divisas: [número] x tokens Spooky.",
        ["Can't be taking any more of those right now; you need to go spend some of your spooky tokens or I can't pay you."] = "No puedo tomar más de esos en este momento; Tienes que gastar algunas de tus espeluznantes fichas o no podré pagarte.",
        ["Farewell."] = "Adiós.",
        ["*sniffle* Bye bye."] = "*sollozo* Adiós.",
    },
    ["Peer the Seer"] = {
        ["Uuuh... What was that dark presence I felt?"] = "Uuuh... ¿Qué fue esa presencia oscura que sentí?",
        ["Ahem, sorry about that."] = "Ejem, lo siento.",
        ["What would you like to ask about?"] = "¿Sobre qué te gustaría preguntar?",
        ["Deposit service"] = "Servicio de deposito",
        ["Hello, Peer. Could you deposit some things for me, please?"] = "Hola, compañero. ¿Podrías depositar algunas cosas por mí, por favor?",
        ["I will oblige you, but it pains me that you are still an outerlander."] = "Te lo agradeceré, pero me duele que todavía seas un extranjero.",
        ["The Fremennik Trials"] = "Los juicios de Fremennik",
        ["I have no interest in talking to you just now outerlander."] = "No tengo ningún interés en hablar contigo ahora, outsider.",
        ["Do not pester me, outerlander! I will only deposit items into the banks of those who have earned Fremennik sea boots!"] = "¡No me molestes, extranjero! ¡Solo depositaré artículos en los bancos de aquellos que hayan ganado Fremennik sea boots!",
        ["Hey! Outerlander! That is my house! Who do you think you are to just barge into my home without asking?"] = "¡Oye! ¡Exterior! ¡Esa es mi casa! ¿Quién te crees que eres para irrumpir en mi casa sin preguntar?",
        ["Um... My name is Player."] = "Um... Mi nombre es Player.",
        ["It was a rhetorical question, outerlander. Now get lost. I do not appreciate intruders in my home."] = "Fue una pregunta retórica, outsider. Ahora piérdete. No aprecio los intrusos en mi casa.",
        ["Of course, [Fremennik name]. I am always happy to aid those who have earned the right to wear Fremennik sea boots."] = "Por supuesto, [Fremennik name]. Siempre estaré feliz de ayudar a aquellos que se han ganado el derecho a usar Fremennik sea boots.",
        ["Wallasalki bone armour"] = "Armadura de hueso Wallasalki",
        ["Hello there. I have some wallasalki bone fragments, and I understand you may be able to use them to make some armour for me...?"] = "Hola. Tengo algunos fragmentos de hueso de wallasalki y tengo entendido que es posible que puedas usarlos para hacerme una armadura...",
        ["As you wish, [Fremennik name]. What kind of armour were you thinking of exactly?"] = "Como quieras, [Fremennik name]. ¿En qué tipo de armadura estabas pensando exactamente?",
        ["Select an Option"] = "Selecciona una opción",
        ["A fine helm"] = "Un buen timón",
        ["I am afraid it will cost you 5,000 coins to make that for you... Is that okay?"] = "Me temo que te costará 5000 coins hacerlo para ti... ¿Te parece bien?",
        ["YES"] = "SI",
        ["My apologies [Fremennik name], but I will need you to bring me 1 piece of dark daggermouth hide, 1 skull piece and 5,000 coins before I can make this helm for you."] = "Mis disculpas [Fremennik name], pero necesitaré que me traigas 1 trozo de piel de boca de daga oscura, 1 trozo de calavera y 5000 coins antes de poder hacerte este yelmo.",
        ["Ah, a helm to make any seer proud! Did you want me to make you another while I am at it?"] = "¡Ah, un yelmo que enorgullecería a cualquier vidente! ¿Quieres que te haga otro mientras lo hago?",
        ["Sturdy bodyarmour"] = "Armadura resistente",
        ["I am afraid it will cost you 10,000 coins to make that for you... Is that okay?"] = "Me temo que te costará 10 000 coins hacerlo para ti... ¿Te parece bien?",
        ["I am sorry [Fremennik name], but I need 3 pieces of dark daggermouth hide, 1 ribcage piece and 10,000 coins to make you this armour..."] = "Lo siento [Fremennik name], pero necesito 3 piezas de piel de boca de daga oscura, 1 pieza de caja torácica y 10,000 coins para hacerte esta armadura...",
        ["The seers of legend all wore just such armour! Did you want me to craft you another piece?"] = "¡Todos los videntes de la leyenda llevaban esa armadura! ¿Quieres que te haga otra pieza?",
        ["Powerful leg armour"] = "Potente armadura para las piernas",
        ["I am afraid it will cost you 7,500 coins to make that for you... Is that okay?"] = "Me temo que te costará 7.500 coins hacerlo para ti... ¿Te parece bien?",
        ["I am very sorry [Fremennik name], but I will require 2 pieces of dark daggermouth hide, 1 fibula piece and 7,500 coins to make this type of leg armour."] = "Lo siento mucho [Fremennik name], pero necesitaré 2 piezas de piel de boca de daga oscura, 1 pieza de peroné y 7500 coins para hacer este tipo de armadura para las piernas.",
        ["Ah, I used to wear just such a piece of armour to battle in my youth... Do you want me to make you another pair of legs while I am doing it anyway?"] = "Ah, solía usar esa pieza de armadura para luchar en mi juventud... ¿Quieres que te haga otro par de piernas mientras lo hago de todos modos?",
        ["Nothing"] = "nada",
        ["Actually, I don't want anything."] = "En realidad, no quiero nada.",
        ["you wish."] = "que desees.",
        ["Hello Peer."] = "Hola compañero.",
        ["Greetings to you, [brother/sister] [Fremennik name]! What brings you to see me again?"] = "¡Saludos a ti, [brother/sister] [Fremennik name]! ¿Qué te trae a verme de nuevo?",
        ["Choose an option:"] = "Elige una opción:",
        ["Can you tell my future?"] = "¿Puedes decir mi futuro?",
        ["I was wondering if you could give me a reading on my future...?"] = "Me preguntaba si podrías darme una lectura sobre mi futuro...",
        ["Ah, you would like a prediction? I do not see that that would be so difficult... wait a moment..."] = "Ah, ¿te gustaría una predicción? No veo que eso sea tan difícil... espera un momento...",
        ["*(One of the following predictions are given, and the selected word within [] is randomly picked:)*"] = "*(Se da una de las siguientes predicciones y la palabra seleccionada dentro de [] se elige aleatoriamente :)*",
        ["*(Prediction 1:)*"] = "*(Predicción 1 :)*",
        ["Here is your prediction: You will find luck today with the number [one/two/three/four/five/six/seven/eight/nine/ten]."] = "Aquí está tu predicción: Hoy encontrarás suerte con el número [one/two/three/four/five/six/seven/eight/nine/ten].",
        ["*(Prediction 2:)*"] = "*(Predicción 2 :)*",
        ["Here is your prediction: The colour [black/blue/brown/cyan/green/pink/purple/red/yellow] will bring you luck this day."] = "Aquí está tu predicción: El color [black/blue/brown/cyan/green/pink/purple/red/yellow] te traerá suerte este día.",
        ["*(Prediction 3:)*"] = "*(Predicción 3 :)*",
        ["Here is your prediction: The enemy called [fire giant/ghosts/giant/goblin/green dragon/hobgoblin/lesser demon/moss giant/ogre/zombie] is your lucky totem this day."] = "Aquí está tu predicción: El enemigo llamado [fire giant/ghosts/giant/goblin/green dragon/hobgoblin/lesser demon/moss giant/ogre/zombie] es tu tótem de la suerte este día.",
        ["*(Prediction 4:)*"] = "*(Predicción 4 :)*",
        ["Here is your prediction: The place called [Al Kharid/Ardougne/Burthorpe/Canifis/Catherby/Falador/Karamja/Varrock/The Wilderness/Yanille] will be worth your time to visit."] = "Aquí está tu predicción: Merecerá la pena visitar el lugar llamado [Al Kharid/Ardougne/Burthorpe/Canifis/Catherby/Falador/Karamja/Varrock/The Wilderness/Yanille].",
        ["*(Prediction 5:)*"] = "*(Predicción 5 :)*",
        ["Here is your prediction: The stars tell me that you should use a [battleaxe/crossbow/dagger/javelin/long sword/mace/scimitar/short sword/spear/warhammer] in combat today."] = "Aquí está tu predicción: Las estrellas me dicen que hoy deberías usar un [battleaxe/crossbow/dagger/javelin/long sword/mace/scimitar/short sword/spear/warhammer] en combate.",
        ["*(Prediction 6:)*"] = "*(Predicción 6 :)*",
        ["Here is your prediction: You would be wise to train the skill [Agility/Cooking/Crafting/Fishing/Fletching/Herblore/Mining/Runecrafting/Smithing/Thieving] today."] = "Aquí está tu predicción: sería prudente entrenar la habilidad [Agility/Cooking/Crafting/Fishing/Fletching/Herblore/Mining/Runecrafting/Smithing/Thieving] hoy.",
        ["Nothing really."] = "Nada realmente.",
        ["Nothing really, I just stopped by to say hello."] = "Nada realmente, solo pasé a saludar.",
        ["Well, hello to you too!"] = "Bueno, ¡hola a ti también!",
    },
    ["Peggy"] = {
        ["Hello there!"] = "¡Hola!",
        ["Select an option"] = "Seleccione una opción",
        ["How are you?"] = "¿Cómo estás?",
        ["This is my favourite time of the year! Of course, I can't join in as much as I want anymore. You should have seen me back in the day. I would dance long into the night."] = "¡Esta es mi época favorita del año! Por supuesto, ya no puedo unirme tanto como quiero. Deberías haberme visto en el pasado. Bailaría hasta bien entrada la noche.",
        ["Yetis can dance?"] = "¿Los Yetis saben bailar?",
        ["Oh yes, the dance of the yeti is a beautiful thing to behold."] = "Oh, sí, la danza del yeti es algo hermoso de contemplar.",
        ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
        ["Can you tell me about Yeti Town?"] = "¿Puedes hablarme sobre Yeti Town?",
        ["Yeti Town is one of the oldest yeti towns. The history of the yeti is quite broken, but before then as we were quite nomadic, having to travel a lot to find a safe place to live."] = "Yeti Town es una de las ciudades yeti más antiguas. La historia del yeti está bastante rota, pero antes éramos bastante nómadas y teníamos que viajar mucho para encontrar un lugar seguro donde vivir.",
        ["However, here in Yeti Town we are the most free we have ever been. To the point we can now have a festival to celebrate the wonders of yeti life!"] = "Sin embargo, aquí en Yeti Town somos más libres que nunca. ¡Hasta el punto de que ahora podemos tener un festival para celebrar las maravillas de la vida del yeti!",
        ["Was this town built by yetis?"] = "¿Esta ciudad fue construida por Yetis?",
        ["I think you've caught us out! No, I believe this town was once inhabited by littlefoots like you!"] = "¡Creo que nos has pillado! ¡No, creo que esta ciudad alguna vez estuvo habitada por pies pequeños como tú!",
        ["What happened to the hum- I mean littlefoots that lived here before?"] = "¿Qué pasó con los hum- quiero decir, los pies pequeños que vivieron aquí antes?",
        ["That knowledge has been swept away in the snow, I'm afraid. Maybe they abandoned it, maybe a spell was cast over them all, maybe we ate them!"] = "Me temo que ese conocimiento ha sido arrastrado por la nieve. Tal vez lo abandonaron, tal vez un hechizo fue lanzado sobre todos ellos, ¡tal vez nos los comimos!",
        ["You ate them?"] = "¿Te los comiste?",
        ["Don't be silly! We're actually quite civilised."] = "¡No seas tonto! En realidad somos bastante civilizados.",
        ["Farewell."] = "Adiós.",
        ["You have a good time now!"] = "¡Que lo pases bien ahora!",
    },
    ["Peksa"] = {
        ["Are you interested in buying or selling a helmet?"] = "¿Estás interesado en comprar o vender un casco?",
        ["Choose an option:"] = "Elige una opción:",
        ["I could be, yes."] = "Podría serlo, sí.",
        ["No, I'll pass on that."] = "No, lo pasaré por alto.",
        ["Well, come back if you change your mind."] = "Bueno, vuelve si cambias de opinión.",
    },
    ["Pelican"] = {
        ["You feed the pelican."] = "Le das de comer al pelícano.",
        ["It looks hungry and wants some raw fish."] = "Parece hambriento y quiere pescado crudo.",
        ["You've already fed this pelican."] = "Ya has alimentado a este pelícano.",
        ["You are rewarded for feeding the pelican - You receive [number] Fishing XP."] = "Serás recompensado por alimentar al pelícano: recibirás [número] Fishing XP.",
    },
    ["Penda"] = {
        ["Hello there!"] = "¡Hola!",
        ["Good day!"] = "¡Buenos días!",
        ["Lovely day, isn't it?"] = "Precioso día, ¿no?",
        ["Oh, hello."] = "Oh, hola.",
        ["Good to see you!"] = "¡Qué bueno verte!",
        ["[You do not have enough room in your backpack to pickpocket the key Penda is carrying.]"] = "[No tienes suficiente espacio en tu backpack para robar la llave que lleva Penda.]",
        ["[You liberate a key from Penda's pocket.]"] = "[Liberas una llave del bolsillo de Penda.]",
        ["[You already have Penda's key.]"] = "[Ya tienes la clave de Penda.]",
    },
    ["Penguin keeper"] = {
        ["*When speaking to Penguin keeper in the Ardougne Zoo.*"] = "*Al hablar con Penguin keeper en el zoológico Ardougne.*",
        ["Hello there. How are the penguins doing today?"] = "Hola. ¿Cómo están los pingüinos hoy?",
        ["They are doing fine, thanks."] = "Están bien, gracias.",
        ["*If the player has 30 Summoning, and doesn't have an existing penguin egg in their inventory or bank:*"] = "*Si el player tiene 30 Summoning y no tiene ningún huevo de pingüino en su inventario o banco:*",
        ["Actually, you might be able to help me with something - if you are interested."] = "En realidad, es posible que puedas ayudarme con algo, si estás interesado.",
        ["What do you mean?"] = "¿Qué quieres decir?",
        ["*If the player has zero or three penguins unlocked in the pet interface:*"] = "*Si el player tiene cero o tres pingüinos desbloqueados en la interfaz de mascotas:*",
        ["Well, you see, the penguins have been laying so many eggs recently that we can't afford to raise them all ourselves."] = "Bueno, verás, los pingüinos han estado poniendo tantos huevos recientemente que no podemos darnos el lujo de criarlos todos nosotros mismos.",
        ["You seem to know a bit about raising animals - would you like to raise a penguin for us?"] = "Parece que sabes un poco sobre la crianza de animales. ¿Te gustaría criar un pingüino para nosotros?",
        ["*If the player has one penguin unlocked in the pet interface:*"] = "*Si el player tiene un pingüino desbloqueado en la interfaz de mascotas:*",
        ["Well, the penguins have continued laying eggs, we simply don't have room for them all."] = "Bueno, los pingüinos han seguido poniendo huevos, simplemente no tenemos espacio para todos.",
        ["You seem to know your way around a penguin - would you like to raise another for us?"] = "Parece que conoces bien los pingüinos. ¿Te gustaría criar otro para nosotros?",
        ["*If the player has two penguins unlocked in the pet interface:*"] = "*Si el player tiene dos pingüinos desbloqueados en la interfaz de mascotas:*",
        ["Well, we are now taking care of an incomprehensible amount of penguins!"] = "Bueno, ¡ahora nos estamos ocupando de una cantidad incomprensible de pingüinos!",
        ["It would be great if you could take care of just one more - would you like to raise a final penguin for us?"] = "Sería fantástico si pudieras encargarte de uno más. ¿Te gustaría criar un último pingüino para nosotros?",
        ["Select an option"] = "Seleccione una opción",
        ["Yes, of course."] = "Sí, por supuesto.",
        ["Wonderful!"] = "¡Maravilloso!",
        ["*(If the player's inventory is full)*"] = "*(Si el inventario de el player está lleno)*",
        ["Come back and see me when you have free space in your inventory. I'll be waiting."] = "Vuelve a verme cuando tengas espacio libre en tu inventario. Voy a estar esperando.",
        ["Here you go - this egg will hatch into a baby penguin."] = "Aquí tienes: este huevo se convertirá en un pingüino bebé.",
        ["They aren't particularly fussy about anything, so it won't be any trouble to raise."] = "No son particularmente quisquillosos con nada, por lo que no será ningún problema recaudar dinero.",
        ["Okay, thank you very much."] = "Vale, muchas gracias.",
        ["No thanks."] = "No, gracias.",
        ["Fair enough. The offer still stands if you change your mind."] = "Bastante bien. La oferta sigue vigente si cambias de opinión.",
    },
    ["Penwie"] = {
        ["Are you hunting animals, then?"] = "¿Entonces estás cazando animales?",
        ["I'm exploring the region for the good of the gnome people."] = "Estoy explorando la región por el bien del pueblo gnomo.",
        ["You're not tracking down huge beasts to kill - you look equipped for it."] = "No estás buscando bestias enormes para matarlas: pareces equipado para ello.",
        ["Well, if I find anything interesting I'll try and bring it back to the King. That might include animals, I suppose. I'd rather not kill it, though - most animals are more useful alive."] = "Bueno, si encuentro algo interesante intentaré llevárselo al Rey. Supongo que eso podría incluir animales. Pero prefiero no matarlo: la mayoría de los animales son más útiles vivos.",
        ["How would you get it home, then?"] = "¿Cómo lo llevarías a casa entonces?",
        ["Never underestimate the ingenuity of a gnome, friend."] = "Nunca subestimes el ingenio de un gnomo, amigo.",
        ["Have you found anything else interesting around here?"] = "¿Has encontrado algo más interesante por aquí?",
        ["I've heard strange rumours about something the locals call the Broodoo. I haven't quite worked out what they are but they seem to be some sort of undead whose ghastly fate depends on the way they were killed. I think they may be sacrifice victims - but I'm not sure why they are sacrificed. Either way the locals seem to be very scared of them."] = "He oído rumores extraños sobre algo que los lugareños llaman Broodoo. No he descubierto muy bien qué son, pero parecen ser una especie de no-muertos cuyo destino espantoso depende de la forma en que fueron asesinados. Creo que pueden ser víctimas de sacrificios, pero no estoy seguro de por qué se los sacrifica. De cualquier manera, los lugareños parecen tenerles mucho miedo.",
        ["That's interesting. Thanks."] = "Eso es interesante. Gracias.",
        ["At last a taste of home!"] = "¡Por fin una muestra de casa!",
    },
    ["Peppermint boy"] = {
        ["Earn the fully recolourable Peppermint outfit by getting onto Santa's nice list and visiting him at his lodge in the Christmas Village."] = "Gana el traje de Menta, totalmente recolorable, ingresando a la linda lista de Papá Noel y visitándolo en su albergue en Christmas Village.",
    },
    ["Peppermint girl"] = {
        ["Earn the fully recolourable Peppermint outfit by getting onto Santa's nice list and visiting him at his lodge in the Christmas Village."] = "Gana el traje de Menta, totalmente recolorable, ingresando a la linda lista de Papá Noel y visitándolo en su albergue en Christmas Village.",
    },
    ["Perrdur"] = {
        ["Ooh, lovely view, dear."] = "Oh, hermosa vista, querida.",
        ["Yes dear."] = "Sí, cariño.",
        ["I hope the food's better here than it was last time."] = "Espero que la comida aquí sea mejor que la última vez.",
        ["I'm sure it will be, dear."] = "Estoy seguro de que así será, querida.",
        ["Sorry to disturb you, but what are you two doing here?"] = "Lamento molestarlos, pero ¿qué están haciendo ustedes dos aquí?",
        ["We are celebrating the anniversary of our marriage, aren't we dear?"] = "Estamos celebrando el aniversario de nuestro matrimonio, ¿no es así, querido?",
        ["And we are having a very enjoyable time, aren't we dear?"] = "Y estamos pasando un rato muy agradable, ¿no crees querida?",
        ["Clearly. I'll let you two lovebirds carry on, then."] = "Claramente. Entonces dejaré que ustedes dos, tortolitos, sigan adelante.",
    },
    ["Pestilent Torva Trovekeeper"] = {
        ["I have a free Pestilent Gem shard for you here. But you don't have space for it!"] = "Aquí tengo un fragmento de gema pestilente gratis para ti. ¡Pero no tienes espacio para ello!",
        ["Hey there! Here's a free Pestilent Gem shard!"] = "¡Hola! ¡Aquí tienes un fragmento de gema pestilente gratis!",
        ["Can I interest you in something from the Pestilent Torva Trove?"] = "¿Puedo interesarte en algo del Pestilent Torva Trove?",
        ["[You can get more Pestilent Gem shards from the Crystal Capsules Treasure Hunter Promotion.]"] = "[Puedes obtener más fragmentos de gemas pestilentes de la promoción Crystal Capsules Treasure Hunter.]",
    },
    ["Pet shop owner (Taverley)"] = {
        ["Choose an option:"] = "Elige una opción:",
        ["Can I see your shop, please?"] = "¿Puedo ver su tienda, por favor?",
        ["Can I see your shop please?"] = "¿Puedo ver su tienda, por favor?",
        ["How much is that puppy in the window?"] = "¿Cuánto cuesta ese cachorro en la ventana?",
        ["I'm sorry, but I can't sell them to you, I'm afraid. You don't strike me as having an affinity with animals."] = "Lo siento, pero me temo que no puedo vendértelos. No me parece que tengas afinidad con los animales.",
        ["The one with the waggly tail?"] = "¿El que tiene la cola meneando?",
        ["Pick a puppy"] = "elige un cachorro",
        ["Labrador"] = "labrador",
        ["No, the labrador."] = "No, el labrador.",
        ["500 gold."] = "500 de oro.",
        ["Isn't that a little steep?"] = "¿No es un poco caro?",
        ["Well, if we gave them away for free then people would just buy them and dump them without a care."] = "Bueno, si los regaláramos, la gente simplemente los compraría y los tiraría sin preocuparse.",
        ["Dogs are big responsibility and should be cared for."] = "Los perros son una gran responsabilidad y deben ser cuidados.",
        ["If a person is unwilling to invest 500 coins, then they don't deserve to have the puppy in the first place."] = "Si una persona no está dispuesta a invertir 500 coins, entonces, en primer lugar, no merece tener el cachorro.",
        ["So, do you still want one?"] = "Entonces, ¿todavía quieres uno?",
        ["Select an option"] = "Selecciona una opción",
        ["Okay, I'll take the labrador."] = "Está bien, me quedo con el labrador.",
        ["Okay, I'll take the Labrador."] = "Está bien, me quedo con el Labrador.",
        ["There you go! I hope you two get on."] = "¡Ahí lo tienes! Espero que ustedes dos se lleven bien.",
        ["No thanks."] = "No, gracias.",
        ["Bulldog"] = "bulldog",
        ["Dalmatian"] = "dálmata",
        ["Greyhound"] = "Galgo",
        ["Terrier"] = "terrier",
        ["Sheepdog"] = "perro pastor",
        ["You asked me that when you last picked up a dog, and I can't sell you another."] = "Me preguntaste eso la última vez que recogiste un perro y no puedo venderte otro.",
        ["So, what sorts of pets are available?"] = "Entonces, ¿qué tipo de mascotas hay disponibles?",
        ["Well, here we sell dogs, but we also have supplies for any other creatures you might want to raise."] = "Bueno, aquí vendemos perros, pero también tenemos suministros para cualquier otra criatura que quieras criar.",
        ["Such as?"] = "¿Por ejemplo?",
        ["Well, we sell nuts. Those can be used to feed squirrels. If you want to capture a squirrel, you'll need to use the nuts on the trap you set, as the little scamps won't be fooled by anything else."] = "Bueno, vendemos nueces. Se pueden utilizar para alimentar a las ardillas. Si quieres capturar una ardilla, necesitarás usar las nueces de la trampa que colocaste, ya que los pequeños bribones no se dejarán engañar por nada más.",
        ["I'll bear that in mind!"] = "¡Lo tendré en cuenta!",
        ["There are also a number of birds that live in the woodlands of the world. If you can find their eggs then you can use the incubator over there to hatch it."] = "También hay varias aves que viven en los bosques del mundo. Si puedes encontrar sus huevos, puedes usar la incubadora que está allí para incubarlos.",
        ["So long as you are the first thing they see out of the shell, they will follow you anywhere."] = "Mientras seas lo primero que vean fuera del caparazón, te seguirán a cualquier parte.",
        ["After that, you just need to feed the chick ground fishing bait until it's old enough to eat it solid."] = "Después de eso, solo necesitas alimentar al polluelo con cebo de pesca terrestre hasta que tenga la edad suficiente para comerlo sólido.",
        ["I'll make sure to keep an eye on them if I go anywhere dangerous."] = "Me aseguraré de vigilarlos si voy a algún lugar peligroso.",
        ["There are also a number of fabulous and exotic lizards found in Karamja. Some can be caught easily in a box trap, while others will need to be raised from an egg."] = "También hay una serie de lagartos fabulosos y exóticos que se encuentran en Karamja. Algunos pueden quedar atrapados fácilmente en una trampa de caja, mientras que otros deberán criarse a partir de un huevo.",
        ["Will the incubator work for them, too?"] = "¿La incubadora también funcionará para ellos?",
        ["Of course! I'll keep an eye on all the eggs you put in there, so they will never end up hard-boiled."] = "¡Por supuesto! Estaré atento a todos los huevos que pongas allí, para que nunca acaben duros.",
        ["Thank goodness!"] = "¡Gracias a Dios!",
        ["The geckos of Karamja are quite easy to trap, like raccoons. Both will investigate a trap happily without any special bait."] = "Los geckos de Karamja son bastante fáciles de atrapar, como los mapaches. Ambos investigarán alegremente una trampa sin ningún cebo especial.",
        ["Monkeys are a different story, however!"] = "¡Sin embargo, los monos son una historia diferente!",
        ["What do you mean?"] = "¿Qué quieres decir?",
        ["Well, they are clever little things and can easily get out of a box trap, unless they are stuck. The easiest way to do that is to put a banana in the workings."] = "Bueno, son pequeñas cosas inteligentes y pueden salir fácilmente de una caja trampa, a menos que estén atrapadas. La forma más sencilla de hacerlo es poner un plátano en funcionamiento.",
        ["They will hang on tight, and never let go, even when the trap closes!"] = "¡Se aferrarán fuerte y nunca los soltarán, incluso cuando la trampa se cierre!",
        ["Thanks a lot, you've been very helpful!"] = "¡Muchas gracias, has sido de gran ayuda!",
        ["It's always a pleasure to help a fellow animal-lover. Come back and visit soon."] = "Siempre es un placer ayudar a un compañero amante de los animales. Vuelve y visítanos pronto.",
        ["Are you interested in buying spirit shards?"] = "¿Estás interesado en comprar fragmentos de espíritu?",
        ["I certainly am. Lots of them, too!"] = "Ciertamente lo soy. ¡Muchos de ellos también!",
        ["Thanks, I'll bear that in mind."] = "Gracias, lo tendré en cuenta.",
        ["How many will you sell? (25 coins each, you have [amount])"] = "¿Cuántos venderás? (25 coins cada uno, tienes [amount])",
        ["You sell [number] shards for [amount] coins."] = "Vendes fragmentos [número] para [amount] coins.",
        ["Have you got any strays in?"] = "¿Tienes algún perro callejero?",
        ["Let me just check my records…"] = "Déjame revisar mis registros...",
        ["You're in luck! I found Mackers wandering around outside! He's been asking after you."] = "¡Estás de suerte! ¡Encontré a Mackers deambulando afuera! Ha estado preguntando por ti.",
        ["Still looking for cake, is he?"] = "Sigue buscando pastel, ¿verdad?",
        ["Of course."] = "Por supuesto.",
        ["[Mackers wanders over to you.]"] = "[Mackers se acerca a ti.]",
        ["You're in luck! I do have a stray...shiney, wiggly thing in. It was hard to catch!"] = "¡Estás de suerte! Tengo una cosa perdida... brillante y ondulante. ¡Fue difícil de atrapar!",
        ["Tell me about it! Would you let me give it a home?"] = "¡Cuéntamelo! ¿Me dejarías darle un hogar?",
        ["Certainly! Take good care of it."] = "¡Por supuesto! Cuídalo bien.",
        ["[The shopkeeper hands you a tinsel snake.]"] = "[El comerciante te entrega una serpiente de oropel.]",
        ["It's yours now. Don't lose it again please, I don't want to have to catch it again!"] = "Ahora es tuyo. ¡No lo vuelvas a perder por favor, no quiero tener que volver a atraparlo!",
        ["You're in luck! A cute little fluffy-wuffy doggie did come in earlier!"] = "¡Estás de suerte! ¡Un perrito lindo y esponjoso llegó antes!",
        ["Yes, yes, it has that effect on everyone."] = "Sí, sí, tiene ese efecto en todos.",
        ["It's such a cutie!"] = "¡Es tan lindo!",
        ["Just give me the dog, would you?"] = "Sólo dame el perro, ¿quieres?",
        ["Fine… Take good care of it."] = "Bien… Cuídalo bien.",
        ["[The shopkeeper hands you a corgi.]"] = "[El comerciante te entrega un corgi.]",
        ["You're in luck! A particularly angry creature did come in here earlier. I'd really appreciate it if you took it away!"] = "¡Estás de suerte! Una criatura particularmente enojada entró aquí antes. ¡Te agradecería mucho que te lo llevaras!",
        ["[The shopkeeper hands you the San'tar Spawnling.]"] = "[El comerciante te entrega el San'tar Spawnling.]",
    },
