        ["Bulldog!"] = "¡Bulldog!",
        ["[The shopkeeper hands you a bulldog!]"] = "[¡El comerciante te entrega un bulldog!]",
        ["Sorry, I can't talk! I have to walk the dog and get the shop ready for the grand opening!"] = "¡Lo siento, no puedo hablar! ¡Tengo que pasear al perro y preparar la tienda para la gran inauguración!",
