    ["Plague cow"] = {
        ["*The player will say one of the following when petting the cow:*"] = "*el player dirá una de las siguientes cosas cuando acaricie a la vaca:*",
        ["Awww, look at the poor sick cow. We'd never make a burger out of you."] = "Awww, mira la pobre vaca enferma. Nunca haríamos una hamburguesa contigo.",
        ["Don't worry cow, I'm sure somebody will find a cure for this plague soon."] = "No te preocupes, estoy seguro de que alguien encontrará una cura para esta plaga pronto.",
        ["The cow makes a pathetic attempt to moo."] = "La vaca hace un patético intento de mugir.",
    },
    ["Plank maker"] = {
        ["54px You need to complete the Construction tutorial before you can use this."] = "54px Debes completar el tutorial de Construction antes de poder utilizarlo.",
        ["Speak to Alfred Stonemason, northwest of Rimmington, to learn more."] = "Hable con Alfred Stonemason, al noroeste de Rimmington, para obtener más información.",
        ["OK"] = "bien",
        ["Choose a plank to make."] = "Elige una tabla para hacer.",
        ["Plank Cost each: 100 x coins"] = "Tablón Coste cada uno: 100 x coins",
        ["Oak plank Cost each: 250 x coins"] = "Tablón de roble Coste cada uno: 250 x coins",
        ["Willow plank Cost each: 250 x coins"] = "Tablón de sauce Coste cada uno: 250 x coins",
        ["Teak plank Cost each: 500 x coins"] = "Tablón de teca Coste cada unidad: 500 x coins",
        ["Maple plank Cost each: 250 x coins"] = "Tablón de arce Coste cada uno: 250 x coins",
        ["Acadia plank Cost each: 500 x coins"] = "Plancha Acadia Costo cada uno: 500 x coins",
        ["Mahogany plank Cost each: 1,500 x coins"] = "Tablón de caoba Coste cada uno: 1.500 x coins",
        ["More"] = "Más",
        ["Yew plank Cost each: 2,000 x coins"] = "Tablón de tejo Coste cada uno: 2000 x coins",
        ["Magic plank Cost each: 3,500 x coins"] = "Plancha Magic Coste cada una: 3.500 x coins",
        ["Elder plank Cost each: 5,000 x coins"] = "Tablón de anciano Coste cada uno: 5,000 x coins",
        ["You cannot afford to make that many planks."] = "No puedes darte el lujo de hacer tantos planks.",
        ["Hello. Do you want me to make some planks for you?"] = "Hola. ¿Quieres que te haga un poco de planks?",
        ["Choose an option:"] = "Elige una opción:",
        ["Planks, please."] = "Planks, por favor.",
        ["What kind of planks do you want?"] = "¿Qué tipo de planks quieres?",
        ["What kind of planks can you make?"] = "¿Qué tipo de planks puedes hacer?",
        ["I can make planks from wood, oak, teak and mahogany. I don't make planks from other woods as they're no good for making furniture."] = "Puedo hacer planks con madera, roble, teca y caoba. No hago planks con otras maderas porque no sirven para hacer furniture.",
        ["Wood and oak are all over the place, but teak and mahogany can only be found in a few places like Karamja and Etceteria."] = "La madera y el roble están por todas partes, pero la teca y la caoba solo se pueden encontrar en unos pocos lugares como Karamja y Etceteria.",
        ["Nothing, thanks."] = "Nada, gracias.",
        ["Well, come back when you want some. You can't get good quality planks anywhere but here!"] = "Bueno, vuelve cuando quieras. ¡No puedes conseguir planks de buena calidad en ningún otro lugar que no sea aquí!",
    },
    ["Poi Dancer"] = {
        ["*Randomly said by the Poi Dancers as they perform:*"] = "*Dicho al azar por los bailarines Poi mientras actúan:*",
        ["It's on!"] = "¡Ya está!",
        ["Lets do this}}{{sic"] = "Hagamos esto}}{{sic",
        ["Make room"] = "Haz espacio",
        ["Round and round"] = "Vueltas y vueltas",
        ["Stand back!"] = "¡Apártate!",
        ["Whoa"] = "Vaya",
    },
    ["Poison Salesman"] = {
        ["I'm afraid I'm all sold out of poison at the moment. People know a bargain when they see it!"] = "Me temo que ya no tengo más veneno en este momento. ¡La gente reconoce una ganga cuando la ve!",
        ["I hear you're pretty smart to have solved the Sinclair Murder!"] = "¡He oído que eres muy inteligente al haber resuelto el asesinato de Sinclair!",
        ["Hello."] = "Hola.",
        ["Howdy! Thanks for buying all that low alcohol beer from me! Now I have the funds to whip up a new batch of patented multipurpose poison!"] = "¡Hola! ¡Gracias por comprarme toda esa cerveza baja en alcohol! ¡Ahora tengo los fondos para preparar un nuevo lote de veneno multiusos patentado!",
        ["Maybe I can take your name and add it to my mailing list for potential purchasers of Peter Potter's patented multipurpose poison?"] = "¿Quizás pueda tomar su nombre y agregarlo a mi lista de correo para posibles compradores del veneno multiuso patentado de Peter Potter?",
        ["Thanks, but no thanks."] = "Gracias, pero no gracias.",
        ["Select an Option"] = "Selecciona una opción",
        ["Talk about the Murder Mystery Quest"] = "Habla sobre la misión Murder Mystery Quest",
        ["Talk about the Fremennik Trials"] = "Habla sobre los juicios de Fremennik",
    },
    ["Poletax"] = {
        ["Are you here to practice your herblore?"] = "¿Estás aquí para practicar tu herbolaria?",
        ["I need herblore supplies."] = "Necesito suministros de herblore.",
        ["What herblore recommendations do you have for me?"] = "¿Qué recomendaciones de herblore tienes para mí?",
    },
    ["Polletix"] = {
        ["Hello."] = "Hola.",
        ["Greetings, adventurer."] = "Saludos, aventurero.",
        ["Select an Option"] = "Seleccione una opción",
        ["Who are you?"] = "¿Quién eres?",
        ["I am Polletix, Guthixian druid of the Crux, and leader of these druids."] = "Soy Polletix, druida guthixiano de Crux y líder de estos druidas.",
        ["What's going on here?"] = "¿Qué está pasando aquí?",
        ["I'm glad you asked!"] = "¡Me alegra que lo hayas preguntado!",
        ["A little while ago, while tending the Tree of Balance, we received word that this part of the Kharidian Desert had started healing."] = "Hace un rato, mientras cuidábamos el Árbol del Equilibrio, recibimos la noticia de que esta parte del Kharidian Desert había comenzado a sanar.",
        ["Needless to say we were ecstatic, and travelled over straight away."] = "No hace falta decir que estábamos extasiados y viajamos de inmediato.",
        ["What are you doing now?"] = "¿Qué estás haciendo ahora?",
        ["So what are you doing now?"] = "Entonces, ¿qué estás haciendo ahora?",
        ["Primarily, we're looking after the area. Life flourishes in the harshest places...but sometimes it needs a little hand."] = "Principalmente, nos ocupamos del área. La vida florece en los lugares más duros... pero a veces necesita un poco de mano.",
        ["I've sent a few druids out to try and investigate whether this healing effect has affected Gielinor elsewhere, but we just don't have the hands to maintain this area while investigating other lands."] = "Envié algunos druidas para intentar investigar si este efecto curativo ha afectado a Gielinor en otros lugares, pero simplemente no tenemos las manos para mantener esta área mientras investigamos otras tierras.",
        ["Is there anything I can do to help?"] = "¿Hay algo que pueda hacer para ayudar?",
        ["I'm not sure you have the skills we need for this task."] = "No estoy seguro de que tengas las habilidades que necesitamos para esta tarea.",
        ["You need level 50 Farming to help Polletix."] = "Necesitas el nivel 50 Farming para ayudar a Polletix.",
        ["Now that you ask, we could use some extra help."] = "Ahora que lo preguntas, nos vendría bien un poco de ayuda adicional.",
        ["I hear you're a pretty experienced farmer."] = "He oído que eres un granjero con mucha experiencia.",
        ["What do you want me to do?"] = "¿Qué quieres que haga?",
        ["We need you to head out and farm herbs - as many as you can."] = "Necesitamos que salgas a cultivar hierbas, tantas como puedas.",
        ["Herbs?"] = "¿Hierbas?",
        ["Herbs!"] = "¡Hierbas!",
        ["HERBS!"] = "¡HIERBAS!",
        ["Why do you need me to farm herbs?"] = "¿Por qué me necesitas para cultivar hierbas?",
        ["Herbs are peculiar plants requiring specific soil conditions to grow correctly."] = "Las hierbas son plantas peculiares que requieren condiciones específicas del suelo para crecer correctamente.",
        ["If there's anything different with their environment, the plants will tell you."] = "Si hay algo diferente en su entorno, las plantas te lo dirán.",
        ["Got it, plant herbs and look out for anything odd. Is there any kind of reward?"] = "Entendido, planta hierbas y ten cuidado con cualquier cosa extraña. ¿Hay algún tipo de recompensa?",
        ["Guess I should've expected that."] = "Supongo que debería haber esperado eso.",
        ["Tell you what, as a reward for helping out I'll award you some Crux Eqal favour every time you harvest a herb patch. I'll give you extra favour if you planted multiple seeds at once."] = "Te diré una cosa, como recompensa por ayudar, te otorgaré un favor de Crux Eqal cada vez que coseches un huerto de hierbas. Te haré un favor adicional si plantaste varias semillas a la vez.",
        ["Magic druid coins? Great!"] = "Magic druida coins? ¡Excelente!",
        ["Well actually, they're no-"] = "Bueno, en realidad, no son-",
        ["What can I spend them on?"] = "¿En qué puedo gastarlos?",
        ["Well, Sydekix here would be happy to teach you some of our techniques in exchange for favour."] = "Bueno, Sydekix estará encantado de enseñarte algunas de nuestras técnicas a cambio de un favor.",
        ["I would?"] = "¿Lo haría?",
        ["Yes, you would."] = "Sí, lo harías.",
        ["Adventurer, it's essential we don't disrupt the natural balance of Gielinor. For that reason, I'll also request that you farm a specific herb each day. It'll help us check if different species of herb are being affected and I'll also give you some extra favour for the effort."] = "Aventurero, es esencial que no alteremos el equilibrio natural de Gielinor. Por esa razón, también te pediré que cultives una hierba específica cada día. Nos ayudará a comprobar si diferentes especies de hierbas se están viendo afectadas y también te haré un favor extra por el esfuerzo.",
        ["You don't really think that the global balance of Gielinor would be affected by me planting a few random herbs do you?"] = "Realmente no crees que el equilibrio global de Gielinor se vería afectado si yo plantara algunas hierbas al azar, ¿verdad?",
        ["Not on its own. But with all the other adventurers that are pouring in here lately looking to help, maybe. So please check with me for which herb to farm each day."] = "No por sí solo. Pero con todos los demás aventureros que están llegando aquí últimamente buscando ayudar, tal vez. Así que por favor consulte conmigo qué hierba cultivar cada día.",
        ["Right - harvest herbs, anything weird, magic coins, learn from Sydekix, daily herb request. Anything else?"] = "Correcto: cosecha hierbas, cualquier cosa rara, coins mágico, aprende de Sydekix, solicitud diaria de hierbas. ¿Algo más?",
        ["I think that's it! Thanks for your help, adventurer."] = "¡Creo que eso es todo! Gracias por tu ayuda, aventurero.",
        ["What caused the desert to heal?"] = "¿Qué causó que el desierto sanara?",
        ["Do you know what has caused the desert to start healing?"] = "¿Sabes qué ha provocado que el desierto comience a sanar?",
        ["We're not quite sure yet, or if the healing is even confined to this area."] = "No estamos muy seguros todavía, ni siquiera si la curación se limita a esta área.",
        ["The Edicts."] = "Los Edictos.",
        ["Could the Edicts being reestablished have caused this?"] = "¿Podrían haber causado esto los Edictos que se están restableciendo?",
        ["Guthix's Edicts are outside of my field of knowledge, but if they did cause this we'd expect to see similar events happening across Gielinor. The elders seem to think that the Wilderness would be the most likely location to show signs of healing, if this was the case."] = "Los Edictos de Guthix están fuera de mi campo de conocimiento, pero si causaron esto, esperaríamos ver eventos similares sucediendo en Gielinor. Los ancianos parecen pensar que Wilderness sería el lugar más probable para mostrar signos de curación, si este fuera el caso.",
        ["The Gods."] = "Los dioses.",
        ["Could the gods being banished have caused this?"] = "¿Podrían haber causado esto los dioses que fueron desterrados?",
        ["Hmm, it's a good question. If it were the case, we'd expect the same to have occurred when Guthix initially banished the other gods, but we have no writings to suggest Gielinor spontaneously began to flourish. However, we don't truly know what the gods were capable of. It's possible that they were affecting the true balance of Gielinor. Hmm... I wonder... It's impossible to know what the gods were truly up to behind closed doors. Could the desert healing be part of some master plan, rather than a side effect of their banishment?"] = "Hmm, es una buena pregunta. Si fuera el caso, esperaríamos que hubiera ocurrido lo mismo cuando Guthix inicialmente desterró a los otros dioses, pero no tenemos escritos que sugieran que Gielinor comenzó a florecer espontáneamente. Sin embargo, no sabemos realmente de qué eran capaces los dioses. Es posible que estuvieran afectando el verdadero equilibrio de Gielinor. Hmm... Me pregunto... Es imposible saber qué estaban realmente haciendo los dioses a puerta cerrada. ¿Podría la curación del desierto ser parte de algún plan maestro, en lugar de un efecto secundario de su destierro?",
        ["Do you think that's likely?"] = "¿Crees que eso es probable?",
        ["Impossible to know really, unless we find a different cause."] = "Imposible saberlo realmente, a menos que encontremos una causa diferente.",
        ["Het's Oasis."] = "Es Oasis.",
        ["Do you think Het's Oasis could be affecting the surrounding land?"] = "¿Crees que el Oasis de Het podría estar afectando el terreno circundante?",
        ["That's my best guess currently. However, if we find that the healing effect isn't localised then it probably rules this out."] = "Esa es mi mejor suposición actualmente. Sin embargo, si encontramos que el efecto curativo no está localizado entonces probablemente lo descarte.",
        ["Also, we're not certain if the waters of the oasis alone could heal this part of the desert."] = "Además, no estamos seguros de que las aguas del oasis por sí solas puedan curar esta parte del desierto.",
        ["What do you mean?"] = "¿Qué quieres decir?",
        ["Well, from all the writings we can find, the Kharidian desert is essentially dead. The River Elid is large and as clean as water gets, yet even on its shores, life struggles to grow."] = "Bueno, de todos los escritos que podemos encontrar, el Kharidian desert está esencialmente muerto. El río Elid es grande y tan limpio como el agua, pero incluso en sus orillas la vida lucha por crecer.",
        ["The Tree of Balance."] = "El árbol del equilibrio.",
        ["Do you think the Tree of Balance could be affecting the area?"] = "¿Crees que el Árbol del Equilibrio podría estar afectando el área?",
        ["I don't think so. I think it's more likely that this area and the tree stem from the same root cause."] = "No lo creo. Creo que es más probable que esta área y el árbol tengan la misma causa fundamental.",
        ["Some think the tree is the manifestation of Guthix's divine energy."] = "Algunos piensan que el árbol es la manifestación de la energía divina de Guthix.",
        ["It could be possible that the energy released when Guthix died is setting and affecting the world."] = "Es posible que la energía liberada cuando murió Guthix esté afectando al mundo.",
        ["Bye!"] = "¡Adiós!",
        ["Okay, bye!"] = "¡Está bien, adiós!",
        ["going on here?"] = "pasando aquí?",
        ["Greetings adventurer."] = "Saludos aventurero.",
        ["How's it going?"] = "¿Cómo te va?",
        ["How goes the desert?"] = "¿Cómo va el desierto?",
        ["Things are progressing nicely, adventurer."] = "Las cosas están progresando muy bien, aventurero.",
        ["We've still not found the source of the healing, but the area is flourishing nicely."] = "Todavía no hemos encontrado la fuente de la curación, pero el área está floreciendo muy bien.",
        ["Can I see the daily herb?"] = "¿Puedo ver la hierba diaria?",
        ["What herb would you like me to harvest today?"] = "¿Qué hierba te gustaría que coseche hoy?",
        ["To help maintain balance, today I'd like you to plant and harvest: [Herb seed name]."] = "Para ayudar a mantener el equilibrio, hoy me gustaría que plantes y coseches: [Herb seed name].",
        ["How do I get more Crux Eqal favour?"] = "¿Cómo obtengo más favores de Crux Eqal?",
        ["How do I get Crux Eqal favour? I've forgotten."] = "¿Cómo obtengo el favor de Crux Eqal? Lo he olvidado.",
        ["No problem. You'll be award some favour whenever you harvest a herb patch. You'll get extra for having multiple seeds planted in a patch."] = "No hay problema. Recibirás un favor cada vez que coseches un huerto de hierbas. Obtendrás un extra por plantar varias semillas en un huerto.",
        ["You'll also gain bonus favour if the herbs you harvest match my daily request."] = "También obtendrás un favor adicional si las hierbas que cosechas coinciden con mi pedido diario.",
        ["Okay, thanks!"] = "¡Bien, gracias!",
        ["Bye."] = "Adiós.",
    },
    ["Polly Paw"] = {
        ["Hello."] = "Hola.",
        ["Hello, pleased to meet you."] = "Hola, encantado de conocerte.",
        ["Can you tell me what you are wearing?"] = "¿Puedes decirme qué llevas puesto?",
        ["Certainly! I am wearing what is known as ganodermic armour. The staff on my back is a polypore staff. I bought the base of this armour from a rather peculiar man in the Polypore Dungeon, found between the Mage Training Area and Mort Myre Swamp. I delved right to the very depths of the dungeon and slayed many Ganodermic beasts, picking fungal flakes off them and applying them to my armour."] = "¡Por supuesto! Llevo lo que se conoce como armadura ganodérmica. El staff que tengo en la espalda es un staff de poliporo. Le compré la base de esta armadura a un hombre bastante peculiar en Polypore Dungeon, que se encuentra entre el área de entrenamiento de magos y Mort Myre Swamp. Profundicé hasta las profundidades de la mazmorra y maté a muchas bestias Ganodermic, quitándoles escamas de hongos y aplicándolas a mi armadura.",
        ["Sounds unhealthy..."] = "Suena poco saludable...",
        ["Haha true, but as a mage I find this equipment very good for my health. Very good for my wellbeing. My enemies' health...not so much."] = "Jaja, es cierto, pero como mago encuentro este equipo muy bueno para mi salud. Muy bueno para mi bienestar. La salud de mis enemigos... no tanto.",
        ["Can you direct me towards the Polypore Dungeon?"] = "¿Puedes indicarme hacia el Polypore Dungeon?",
        ["Certainly. I shall mark it on your map for you."] = "Por supuesto. Lo marcaré en tu mapa por ti.",
        ["Can I ask you about something else?"] = "¿Puedo preguntarte algo más?",
        ["*(Returns to previous options)*"] = "*(Vuelve a opciones anteriores)*",
        ["Goodbye"] = "Adiós",
        ["Can you tell me what the people on the stands behind you are wearing?"] = "¿Puedes decirme qué visten las personas que están detrás de ti en las gradas?",
        ["The man directly behind me is in armour worn by the famous Zarosian warrior, Torva. He would have picked that up in an icy dungeon that we call the God Wars Dungeon. The Godwars Dungeon is a chaotic remnant of the Third Age, filled with the ever-warring armies of the gods. The generals of these armies are said to be some of the best combatants RuneScape has to offer. The lady in the centre is wearing magical armour called spider silk made by crafters. The man on the right is wearing infinity robes. That armour is obtained while training at the famous Mage Training Arena."] = "El hombre que está justo detrás de mí lleva una armadura usada por el famoso guerrero zarosiano, Torva. Habría aprendido eso en una mazmorra helada que llamamos God Wars Dungeon. El Godwars Dungeon es un remanente caótico de la Tercera Edad, lleno de los ejércitos de los dioses en constante guerra. Se dice que los generales de estos ejércitos son algunos de los mejores combatientes que RuneScape tiene para ofrecer. La dama del centro lleva una armadura mágica llamada seda de araña hecha por artesanos. El hombre de la derecha lleva una túnica infinita. Esa armadura se obtiene mientras entrenas en el famoso Mage Training Arena.",
        ["Can you direct me towards the God Wars Dungeon?"] = "¿Puedes indicarme hacia el God Wars Dungeon?",
        ["Can you direct me towards the Mage Training Arena?"] = "¿Puedes indicarme hacia el Mage Training Arena?",
    },
    ["Pompous merchant"] = {
        ["Step aside, you low-born oaf!"] = "¡Hazte a un lado, idiota de baja cuna!",
        ["Hey! Who are you calling names?"] = "¡Oye! ¿A quién estás insultando?",
        ["I have no idea. Some 'hero' I would guess."] = "No tengo idea. Algún 'héroe', supongo.",
        ["Look you..."] = "Mira...",
        ["Hush. I have far too much money to listen to the idle prattle of menials. Begone!"] = "Silencio. Tengo demasiado dinero para escuchar la charla inútil de los sirvientes. ¡Vete!",
    },
    ["Pondskater"] = {
        ["You skilfully snatch the key from the jaws of the skater."] = "Arrebatas hábilmente la llave de las fauces del patinador.",
        ["Now useless, the key vanishes from your hands."] = "Ahora inútil, la llave desaparece de tus manos.",
        ["The act of simply retrieving the key is enough to deactivate the magical seals on the doors."] = "El simple hecho de recuperar la llave es suficiente para desactivar los sellos mágicos de las puertas.",
    },
    ["Pontak"] = {
        ["I cannot speak to you outerlander! Talk to Brundt, the Chieftain!"] = "¡No puedo hablar contigo, extranjero! ¡Habla con Brundt, el cacique!",
        ["They are too suspicious of you for you to get close enough to steal from them."] = "Sospechan demasiado de ti como para que te acerques lo suficiente como para robarles.",
        ["*When speaking to Pontak in Rellekka.*"] = "*Al hablar con Pontak en Rellekka.*",
        ["Hello."] = "Hola.",
        ["*Pontak may greet you with any of the following at random:*"] = "*Pontak puede saludarte con cualquiera de los siguientes al azar:*",
        ["*Greeting 1:*"] = "*Saludo 1:*",
        ["How are you, [Fremennik name]? I hope all fares well with you this day!"] = "¿Cómo estás, [Fremennik name]? ¡Espero que a todos les vaya bien este día!",
        ["I'm fine, thanks, how are you?"] = "Estoy bien, gracias, ¿cómo estás?",
        ["All is well with me also!"] = "¡Todo está bien para mí también!",
        ["*Greeting 2:*"] = "*Saludo 2:*",
        ["Hello again, [sister/brother] [Fremennik name]. What need you of me this day? You can always rely on my assistance!"] = "Hola de nuevo, [sister/brother] [Fremennik name]. ¿Qué necesitas de mí este día? ¡Siempre puedes confiar en mi ayuda!",
        ["*Greeting 3:*"] = "*Saludo 3:*",
        ["Hello. Did you want something, [Fremennik name]?"] = "Hola. ¿Querías algo, [Fremennik name]?",
        ["*Greeting 4:*"] = "*Saludo 4:*",
        ["[Fremennik name], it has been too long since last we met!"] = "[Fremennik name], ¡ha pasado demasiado tiempo desde la última vez que nos vimos!",
        ["*Greeting 5:*"] = "*Saludo 5:*",
        ["Welcome back, [sister/brother] [Fremennik name]. It is always a pleasure to see you here!"] = "Bienvenido de nuevo, [sister/brother] [Fremennik name]. ¡Siempre es un placer verte por aquí!",
        ["*Greeting 6:*"] = "*Saludo 6:*",
        ["Hello to you, too!"] = "¡Hola a ti también!",
        ["*Greeting 7:*"] = "*Saludo 7:*",
        ["Always good to see you, [sister/brother] [Fremennik name]."] = "Siempre es un placer verte, [sister/brother] [Fremennik name].",
        ["Select an option (all greetings continue with dialogue below)"] = "Seleccione una opción (todos los saludos continúan con el diálogo a continuación)",
        ["Can I ask you about V?"] = "¿Puedo preguntarte sobre V?",
        ["*Pontak may reply to you with any of the following at random:*"] = "*Pontak puede responderle con cualquiera de los siguientes mensajes al azar:*",
        ["*Reply 1:*"] = "*Respuesta 1:*",
        ["He died saving you, [Fremennik name]. Make sure you use his final gift wisely and live a life that we can all be proud of."] = "Él murió salvándote, [Fremennik name]. Asegúrate de utilizar sabiamente su regalo final y vivir una vida de la que todos podamos estar orgullosos.",
        ["*Reply 2:*"] = "*Respuesta 2:*",
        ["He was a great hero to our people. Why couldn't they have gone for one of the bad gods, like Zamorak or Saradomin?"] = "Fue un gran héroe para nuestro pueblo. ¿Por qué no pudieron haber elegido a uno de los dioses malos, como Zamorak o Saradomin?",
        ["*Reply 3:*"] = "*Respuesta 3:*",
        ["Those cowards. They didn't even have the decency to face him as a warrior."] = "Esos cobardes. Ni siquiera tuvieron la decencia de enfrentarlo como un guerrero.",
        ["*Reply 4:*"] = "*Respuesta 4:*",
        ["It's sad that he's gone, but he will live on as an inspiration to countless heroes across countless worlds."] = "Es triste que se haya ido, pero seguirá viviendo como una inspiración para innumerables héroes en innumerables mundos.",
        ["Goodbye."] = "Adiós.",
    },
    ["Pontimer"] = {
        ["Welcome to this grand cave of Guthix, traveller."] = "Bienvenido a esta gran cueva de Guthix, viajero.",
        ["So, what do I do here?"] = "Entonces, ¿qué hago aquí?",
        ["Ah, you should probably talk to the organ grinder not the monkey."] = "Ah, probablemente deberías hablar con el organillero, no con el mono.",
        ["What?"] = "¿Qué?",
        ["Talk to Fiara, she's in charge here."] = "Habla con Fiara, ella está a cargo aquí.",
        ["Which is she? None of you look female to me."] = "¿Quién es ella? Ninguno de ustedes me parece mujer.",
        ["No, no - Fiara is the Guardian of this place. Created by Guthix to keep a watchful eye over this holy site."] = "No, no. Fiara es el guardián de este lugar. Creado por Guthix para vigilar este lugar sagrado.",
        ["Guardian? You mean that weird looking giant earwig at the back of the cave?"] = "¿Guardián? ¿Te refieres a esa tijereta gigante de aspecto extraño que hay al fondo de la cueva?",
        ["Don't refer to a holy Guardian of Guthix like that. You can call her Lady Fiara."] = "No te refieras así a un santo Guardián de Guthix. Puedes llamarla Lady Fiara.",
        ["But she's not a lady, she's a giant earwig."] = "Pero ella no es una dama, es una tijereta gigante.",
        ["Don't argue, just go and talk to her. And be polite."] = "No discutas, solo ve y habla con ella. Y sea cortés.",
        ["Select an Option"] = "Selecciona una opción",
        ["So, what is this place?"] = "Entonces, ¿qué es este lugar?",
        ["This is a sacred site of Guthix."] = "Este es un sitio sagrado de Guthix.",
        ["Why is it sacred?"] = "¿Por qué es sagrado?",
        ["Guthix places guardians in places of holy power. There is one such guardian here."] = "Guthix coloca guardianes en lugares de poder sagrado. Hay uno de esos guardianes aquí.",
        ["But what is special about this place?"] = "¿Pero qué tiene de especial este lugar?",
        ["It exudes a dangerous magical power that we have been entrusted to protect."] = "Exuda un peligroso poder mágico que se nos ha confiado proteger.",
        ["Where did this power come from?"] = "¿De dónde vino este poder?",
        ["It comes from the centre of the big cave."] = "Viene del centro de la gran cueva.",
        ["What's special about the centre?"] = "¿Qué tiene de especial el centro?",
        ["It's very magical."] = "Es muy mágico.",
        ["Yes, I get that. Why is it magical?"] = "Sí, lo entiendo. ¿Por qué es mágico?",
        ["Something to do with the Fist of Guthix."] = "Algo que ver con el Puño de Guthix.",
        ["And what is that, exactly?"] = "¿Y qué es eso exactamente?",
        ["The truth is, none of us really know."] = "La verdad es que ninguno de nosotros lo sabe realmente.",
        ["This place is special to Guthix, because Fiara is here."] = "Este lugar es especial para Guthix, porque Fiara está aquí.",
        ["And we know it has something to do with the 'Fist of Guthix' because Fiara occasionally mentions it."] = "Y sabemos que tiene algo que ver con el 'Puño de Guthix' porque Fiara lo menciona ocasionalmente.",
        ["But other than that, we only have theories. Do you want to hear about them?"] = "Pero aparte de eso, sólo tenemos teorías. ¿Quieres oír hablar de ellos?",
        ["I suppose so..."] = "Supongo que sí...",
        ["Getorix's theory."] = "La teoría de Getorix.",
        ["Well, this is Getorix's silly theory. Listen to it, if you must."] = "Bueno, esta es la tonta teoría de Getorix. Escúchalo, si es necesario.",
        ["At the end of the God Wars, Guthix returned to Gielinor and was angered by the destruction caused by the other gods in their vanity and quest for power. So, maybe he punched the ground in anger, leaving an imprint of power on the ground that has lasted ever since."] = "Al final de las Guerras de Dios, Guthix regresó a Gielinor y estaba enojado por la destrucción causada por los otros dioses en su vanidad y búsqueda de poder. Entonces, tal vez golpeó el suelo con ira, dejando una huella de poder en el suelo que ha perdurado desde entonces.",
        ["Because he was angry at the time, the power would have been tainted with aggression, which is why he left Fiara as a guardian, to make sure the power did not escape unfettered."] = "Debido a que estaba enojado en ese momento, el poder se habría visto contaminado con agresión, razón por la cual dejó a Fiara como guardián, para asegurarse de que el poder no escapara sin restricciones.",
        ["Do you believe this theory?"] = "¿Crees en esta teoría?",
        ["No, I think it's rubbish; if it was true, that would mean Guthix's hand would be a very strange shape. The indentation in the centre of the cave doesn't look like a fist to me. Getorix has just let his imagination run away with him. My theory is better."] = "No, creo que es basura; si fuera cierto, eso significaría que la mano de Guthix tendría una forma muy extraña. La hendidura en el centro de la cueva no me parece un puño. Getorix acaba de dejar volar su imaginación. Mi teoría es mejor.",
        ["Do you want to hear another theory?"] = "¿Quieres escuchar otra teoría?",
        ["Pontimer's theory."] = "La teoría de Pontimer.",
        ["If you want the true story, then this is it."] = "Si quieres la historia real, entonces ésta es.",
        ["After the God Wars, Guthix found something dangerous here and used his power to protect it."] = "Después de las Guerras de Dios, Guthix encontró algo peligroso aquí y usó su poder para protegerlo.",
        ["What did he find?"] = "¿Qué encontró?",
        ["I don't know for certain, but it must be under that strange impression in the big cave. I think that mark is some sort of ward that Guthix has left to protect the site."] = "No lo sé con certeza, pero debe ser bajo esa extraña impresión en la gran cueva. Creo que esa marca es una especie de protección que Guthix dejó para proteger el sitio.",
        ["So where does the Fist of Guthix come into this, then?"] = "Entonces, ¿dónde entra en esto el Puño de Guthix?",
        ["Hmmm. I'm not really sure. I think that when Fiara refers to the Fist of Guthix she is talking metaphorically about an abstract concept of fist-ness rather than the clenched right hand of Guthix itself."] = "Mmmm. No estoy realmente seguro. Creo que cuando Fiara se refiere al Puño de Guthix, está hablando metafóricamente de un concepto abstracto de puño en lugar de la mano derecha apretada de Guthix.",
        ["That sounds a bit...made up to me."] = "Eso suena un poco... inventado para mí.",
        ["Why you impudent...bah. It's better than anything that Getorix and Alran can come up with, anyway."] = "Por qué eres descarado...bah. De todos modos, es mejor que cualquier cosa que se les ocurra a Getorix y Alran.",
        ["Alran's theory."] = "La teoría de Alran.",
        ["This is what Alran thinks, for what it's worth...which isn't very much, if you ask me."] = "Esto es lo que piensa Alran, por lo que vale... que no es mucho, si me preguntas.",
        ["Guthix has apparently left us a test. He deliberately created this site of power as a test of individual strength and balance."] = "Guthix aparentemente nos ha dejado una prueba. Creó deliberadamente este sitio de poder como una prueba de fuerza y ​​equilibrio individual.",
        ["Does Guthix do that sort of thing?"] = "¿Guthix hace ese tipo de cosas?",
        ["Well, no! I agree with you entirely. This theory has so many holes that it makes no sense at all!"] = "¡Pues no! Estoy totalmente de acuerdo contigo. ¡Esta teoría tiene tantos agujeros que no tiene ningún sentido!",
        ["I'd better get going."] = "Será mejor que me vaya.",
        ["Who's the weird looking giant earwig?"] = "¿Quién es la tijereta gigante de aspecto extraño?",
        ["Shhh! Give Fiara some respect! She can hear you, you know."] = "¡Shhh! ¡Dale un poco de respeto a Fiara! Ella puede oírte, ¿sabes?",
        ["Fiara? It has a name?"] = "¿Fiara? ¿Tiene un nombre?",
        ["Of course, Guthix chooses names for all his guardians."] = "Por supuesto, Guthix elige nombres para todos sus guardianes.",
        ["If...err...Fiara is a Guardian, what is she guarding?"] = "Si... err... Fiara es una Guardiana, ¿qué está protegiendo?",
        ["She guards this site. It is a holy site of Guthix."] = "Ella protege este sitio. Es un lugar sagrado de Guthix.",
        ["How long has Fiara been here?"] = "¿Cuánto tiempo lleva aquí Fiara?",
        ["Errr, ages. Since the end of the God Wars I think. She doesn't talk about that much."] = "Errr, edades. Desde el final de las Guerras de Dios, creo. Ella no habla mucho de eso.",
        ["So what are you doing here?"] = "Entonces, ¿qué estás haciendo aquí?",
    },
    ["Pork Pie (cat)"] = {
        ["Meow!"] = "¡Miau!",
        ["Meow."] = "Miau.",
        ["Meow..."] = "Miau...",
        ["Meow?"] = "¿Miau?",
        ["Meowwwwww."] = "Miauwwwwww.",
        ["Can't talk. Must get my daily steps in."] = "No puedo hablar. Debo realizar mis pasos diarios.",
        ["Out of the way, human! I have places to go and animals to see."] = "¡Fuera del camino, humano! Tengo lugares adonde ir y animales que ver.",
        ["Why are you called Pork Pie?"] = "¿Por qué te llaman Pork Pie?",
        ["Why are you called Player?"] = "¿Por qué te llamas Player?",
        ["I'm not sure, actually."] = "En realidad, no estoy seguro.",
        ["If you must know. My human, Hawk, considers them to be a delicacy."] = "Si debes saberlo. Mi humano, Hawk, los considera un manjar.",
        ["He got one from a travelling merchant, just one time, and now look at me. Named after a baked good!"] = "Consiguió uno de un travelling merchant, solo una vez, y ahora mírame. ¡El nombre de un producto horneado!",
    },
    ["Pork Pie"] = {
        ["Meow!"] = "¡Miau!",
        ["Meow."] = "Miau.",
        ["Meow..."] = "Miau...",
        ["Meow?"] = "¿Miau?",
        ["Meowwwwww."] = "Miauwwwwww.",
        ["Can't talk. Must get my daily steps in."] = "No puedo hablar. Debo realizar mis pasos diarios.",
        ["Out of the way, human! I have places to go and animals to see."] = "¡Fuera del camino, humano! Tengo lugares adonde ir y animales que ver.",
