    ["Port Sarim guard (roof)"] = {
        ["HALT! Who goes there?"] = "¡ALTO! ¿Quién va ahí?",
        ["Don't worry, I'm not going to cause trouble."] = "No te preocupes, no voy a causar problemas.",
        ["But you shouldn't be here - be off with you!"] = "Pero no deberías estar aquí, ¡vete!",
        ["I was going anyway."] = "Iba a ir de todos modos.",
        ["I am Player the Mighty!"] = "¡Soy Player el Poderoso!",
        ["Mighty? You look like another of those silly adventurers who thinks they're the bee's knees just because they've done a few lousy quests!"] = "¿Poderoso? ¡Pareces otro de esos tontos aventureros que se creen los mejores sólo porque han realizado unas cuantas misiones pésimas!",
        ["Well it sounds better than sitting on this rooftop all day looking at trees!"] = "¡Bueno, suena mejor que estar sentado en esta azotea todo el día mirando los árboles!",
        ["I'll have you know it's a very important job guarding this jail!"] = "¡Te haré saber que es un trabajo muy importante proteger esta cárcel!",
        ["If anyone comes sneaking in here to mess around with the prisoners, the lads downstairs will make mincemeat of them, and I'll be here to pick them off if they try to escape."] = "Si alguien entra aquí a escondidas para meterse con los prisioneros, los muchachos de abajo los harán picadillo y yo estaré aquí para eliminarlos si intentan escapar.",
        ["You mean people aren't meant to be able to shoot the prisoners in the cells?"] = "¿Quieres decir que la gente no debe poder disparar a los prisioneros en las celdas?",
        ["Yes, that's right."] = "Sí, es cierto.",
        ["Okay, it's been nice talking to you."] = "Está bien, ha sido un placer hablar contigo.",
        ["No-one, there's no-one here."] = "Nadie, no hay nadie aquí.",
        ["What? I can see you!"] = "¿Qué? ¡Puedo verte!",
        ["No, you're just imagining it. Perhaps you've been up here in the sun for too long?"] = "No, solo te lo estás imaginando. ¿Quizás llevas demasiado tiempo aquí expuesto al sol?",
        ["So who am I talking to?"] = "Entonces, ¿con quién estoy hablando?",
        ["Oh dear, you've started talking to yourself. That's a common sign that you're going mad!"] = "Dios mío, has empezado a hablar solo. ¡Esa es una señal común de que te estás volviendo loco!",
        ["But... but... you're standing right there..."] = "Pero... pero... estás parado ahí mismo...",
        ["Maybe you should leave him alone now."] = "Quizás deberías dejarlo en paz ahora.",
    },
    ["Port Sarim guard"] = {
        ["HALT! Who goes there?"] = "¡ALTO! ¿Quién va ahí?",
        ["Don't worry, I'm not going to cause trouble."] = "No te preocupes, no voy a causar problemas.",
