    ["What's up doc?"] = "¿Qué pasa doctor?",
    ["Yes.. you'll do..."] = "Sí... servirá...",
    ["*gulp*"] = "*traga*",
    ["The Plague Doctor hands you 2 stickers."] = "El Doctor de la Plaga te entrega 2 pegatinas.",
    ["Thanks..?"] = "¿Gracias...?",
    ["Tell me about your task list"] = "Cuéntame sobre tu lista de tareas",
    ["Tell me about your task list."] = "Cuéntame sobre tu lista de tareas.",
    ["Yes... there's plenty of tasks you can do for me..."] = "Sí... hay muchas tareas que puedes hacer por mí...",
    ["If you can finish the tasks on the card I'll make sure you're rewarded... appropriately."] = "Si puedes terminar las tareas de la tarjeta, me aseguraré de que recibas la recompensa... apropiada.",
    ["I do like being rewarded appropriately."] = "Me gusta que me recompensen adecuadamente.",
    ["Yes... I'll show you how to be just like me..."] = "Sí... Te mostraré cómo ser como yo...",
    ["Fill out the task list by completing tasks or using Plague Doctor Stamps! You will be able to unlock multiple Plague Doctor Outfit overrides as well as a brand new rest, teleport and walk animation!"] = "¡Completa la lista de tareas completando tareas o usando Plague Doctor Stamps! ¡Podrás desbloquear múltiples anulaciones de atuendos de Plague Doctor, así como una nueva animación de descanso, teletransporte y caminata!",
    ["I've lost my task list."] = "He perdido mi lista de tareas.",
    ["*(If task list is in bank:)*"] = "*(Si la lista de tareas está en el banco:)*",
    ["I do believe it's in your bank..."] = "Creo que está en tu banco...",
    ["How did you know that?"] = "¿Cómo supiste eso?",
    ["I know a lot about you... so young... so careless..."] = "Sé mucho sobre ti... tan joven... tan descuidado...",
    ["*(If task list is in inventory:)*"] = "*(Si la lista de tareas está en el inventario:)*",
    ["Apply this balm directly to your eyeballs... 12 times a day."] = "Aplica este bálsamo directamente en tus globos oculares... 12 veces al día.",
    ["Huh?"] = "¿Eh?",
    ["Yes... there's definitely something wrong with your eyes... the task list is in your inventory."] = "Sí... definitivamente hay algo mal en tus ojos... la lista de tareas está en tu inventario.",
    ["Huh? You're right."] = "¿Eh? Tienes razón.",
    ["*(If task list isn't owned:)*"] = "*(Si la lista de tareas no es de su propiedad:)*",
    ["Yes... fine... here is another one..."] = "Sí... bien... aquí hay otro...",
    ["What do I need to get for this prescription?"] = "¿Qué necesito obtener para esta receta?",
    ["Yes... Have a look at my list..."] = "Sí... Echa un vistazo a mi lista...",
    ["*(During the promotion:)*"] = "*(Durante la promoción:)*",
    ["*(Medicine ingredients interface is shown.)*"] = "*(Se muestra la interfaz de ingredientes del medicamento.)*",
    ["*(After the promotion:)*"] = "*(Después de la promoción :)*",
    ["Not now... not now..."] = "Ahora no... ahora no...",
    ["I've got some ingredients for the prescription."] = "Tengo algunos ingredientes para la receta.",
    ["*(If the task isn't completed:)*"] = "*(Si la tarea no se completa:)*",
    ["*(If no ingredients are in inventory:)*"] = "*(Si no hay ingredientes en el inventario:)*",
    ["You haven't got anything useful to give me..."] = "No tienes nada útil que darme...",
    ["Oh, okay."] = "Oh, está bien.",
    ["It's quite alright..."] = "Está bastante bien...",
    ["There is no cure for stupidity..."] = "No hay cura para la estupidez...",
    ["*(If ingredients are in inventory, the corresponding ones out of the following are shown:)*"] = "*(Si hay ingredientes en el inventario, se muestran los correspondientes de los siguientes:)*",
    ["I've brought you an Overload salve."] = "Te he traído un ungüento para sobrecarga.",
    ["Yes..."] = "Sí...",
    ["I've brought you a Divine herb patch III."] = "Les he traído un parche de hierbas divinas III.",
    ["Perfect..."] = "Perfecto...",
    ["I've brought you an empty bird's nest."] = "Te he traído un nido de pájaro vacío.",
    ["As expected..."] = "Como era de esperar...",
    ["I've brought you 200 Harmonic Dust."] = "Te he traído 200 polvo armónico.",
    ["The most vital ingredient..."] = "El ingrediente más vital...",
    ["I've brought you some Wallasalkibane ore"] = "Te he traído un poco de mineral de Wallasalkibane.",
    ["This will thicken it up..."] = "Esto lo espesará...",
    ["I've brought you a sack of potatoes"] = "Te he traído un saco de patatas.",
    ["*(If there are ingredients remaining:)*"] = "*(Si quedan ingredientes:)*",
    ["Just a little bit more..."] = "Sólo un poquito más...",
    ["*(After final ingredient:)*"] = "*(Después del ingrediente final:)*",
    ["It is finally complete..."] = "Finalmente está completo...",
    ["You have completed the task - 'Home Remedy"] = "Has completado la tarea - 'Remedio casero",
    ["*(If the task is completed:)*"] = "*(Si la tarea está completada:)*",
    ["The cure is complete... for now..."] = "La cura está completa... por ahora...",
    ["You'll be back..."] = "Volverás...",
    ["*The player will say one of the following when petting the cow:*"] = "*el player dirá una de las siguientes cosas cuando acaricie a la vaca:*",
    ["Awww, look at the poor sick cow. We'd never make a burger out of you."] = "Awww, mira la pobre vaca enferma. Nunca haríamos una hamburguesa contigo.",
    ["Don't worry cow, I'm sure somebody will find a cure for this plague soon."] = "No te preocupes, estoy seguro de que alguien encontrará una cura para esta plaga pronto.",
    ["The cow makes a pathetic attempt to moo."] = "La vaca hace un patético intento de mugir.",
    ["54px You need to complete the Construction tutorial before you can use this."] = "54px Debes completar el tutorial de Construction antes de poder utilizarlo.",
    ["Speak to Alfred Stonemason, northwest of Rimmington, to learn more."] = "Hable con Alfred Stonemason, al noroeste de Rimmington, para obtener más información.",
    ["Choose a plank to make."] = "Elige una tabla para hacer.",
    ["Plank Cost each: 100 x coins"] = "Tablón Coste cada uno: 100 x coins",
    ["Oak plank Cost each: 250 x coins"] = "Tablón de roble Coste cada uno: 250 x coins",
    ["Willow plank Cost each: 250 x coins"] = "Tablón de sauce Coste cada uno: 250 x coins",
    ["Teak plank Cost each: 500 x coins"] = "Tablón de teca Coste cada unidad: 500 x coins",
    ["Maple plank Cost each: 250 x coins"] = "Tablón de arce Coste cada uno: 250 x coins",
    ["Acadia plank Cost each: 500 x coins"] = "Plancha Acadia Costo cada uno: 500 x coins",
    ["Mahogany plank Cost each: 1,500 x coins"] = "Tablón de caoba Coste cada uno: 1.500 x coins",
    ["More"] = "Más",
    ["Yew plank Cost each: 2,000 x coins"] = "Tablón de tejo Coste cada uno: 2000 x coins",
    ["Magic plank Cost each: 3,500 x coins"] = "Plancha Magic Coste cada una: 3.500 x coins",
    ["Elder plank Cost each: 5,000 x coins"] = "Tablón de anciano Coste cada uno: 5,000 x coins",
    ["You cannot afford to make that many planks."] = "No puedes darte el lujo de hacer tantos planks.",
    ["Hello. Do you want me to make some planks for you?"] = "Hola. ¿Quieres que te haga un poco de planks?",
    ["Planks, please."] = "Planks, por favor.",
    ["What kind of planks do you want?"] = "¿Qué tipo de planks quieres?",
    ["What kind of planks can you make?"] = "¿Qué tipo de planks puedes hacer?",
    ["I can make planks from wood, oak, teak and mahogany. I don't make planks from other woods as they're no good for making furniture."] = "Puedo hacer planks con madera, roble, teca y caoba. No hago planks con otras maderas porque no sirven para hacer furniture.",
    ["Wood and oak are all over the place, but teak and mahogany can only be found in a few places like Karamja and Etceteria."] = "La madera y el roble están por todas partes, pero la teca y la caoba solo se pueden encontrar en unos pocos lugares como Karamja y Etceteria.",
    ["Nothing, thanks."] = "Nada, gracias.",
    ["Well, come back when you want some. You can't get good quality planks anywhere but here!"] = "Bueno, vuelve cuando quieras. ¡No puedes conseguir planks de buena calidad en ningún otro lugar que no sea aquí!",
    ["*Randomly said by the Poi Dancers as they perform:*"] = "*Dicho al azar por los bailarines Poi mientras actúan:*",
    ["It's on!"] = "¡Ya está!",
    ["Lets do this}}{{sic"] = "Hagamos esto}}{{sic",
    ["Make room"] = "Haz espacio",
    ["Round and round"] = "Vueltas y vueltas",
    ["Stand back!"] = "¡Apártate!",
    ["Whoa"] = "Vaya",
    ["I'm afraid I'm all sold out of poison at the moment. People know a bargain when they see it!"] = "Me temo que ya no tengo más veneno en este momento. ¡La gente reconoce una ganga cuando la ve!",
    ["I hear you're pretty smart to have solved the Sinclair Murder!"] = "¡He oído que eres muy inteligente al haber resuelto el asesinato de Sinclair!",
    ["Howdy! Thanks for buying all that low alcohol beer from me! Now I have the funds to whip up a new batch of patented multipurpose poison!"] = "¡Hola! ¡Gracias por comprarme toda esa cerveza baja en alcohol! ¡Ahora tengo los fondos para preparar un nuevo lote de veneno multiusos patentado!",
    ["Maybe I can take your name and add it to my mailing list for potential purchasers of Peter Potter's patented multipurpose poison?"] = "¿Quizás pueda tomar su nombre y agregarlo a mi lista de correo para posibles compradores del veneno multiuso patentado de Peter Potter?",
    ["Thanks, but no thanks."] = "Gracias, pero no gracias.",
    ["Talk about the Murder Mystery Quest"] = "Habla sobre la misión Murder Mystery Quest",
    ["Talk about the Fremennik Trials"] = "Habla sobre los juicios de Fremennik",
    ["Are you here to practice your herblore?"] = "¿Estás aquí para practicar tu herbolaria?",
    ["I need herblore supplies."] = "Necesito suministros de herblore.",
    ["What herblore recommendations do you have for me?"] = "¿Qué recomendaciones de herblore tienes para mí?",
    ["I am Polletix, Guthixian druid of the Crux, and leader of these druids."] = "Soy Polletix, druida guthixiano de Crux y líder de estos druidas.",
    ["I'm glad you asked!"] = "¡Me alegra que lo hayas preguntado!",
    ["A little while ago, while tending the Tree of Balance, we received word that this part of the Kharidian Desert had started healing."] = "Hace un rato, mientras cuidábamos el Árbol del Equilibrio, recibimos la noticia de que esta parte del Kharidian Desert había comenzado a sanar.",
    ["Needless to say we were ecstatic, and travelled over straight away."] = "No hace falta decir que estábamos extasiados y viajamos de inmediato.",
    ["What are you doing now?"] = "¿Qué estás haciendo ahora?",
    ["So what are you doing now?"] = "Entonces, ¿qué estás haciendo ahora?",
    ["Primarily, we're looking after the area. Life flourishes in the harshest places...but sometimes it needs a little hand."] = "Principalmente, nos ocupamos del área. La vida florece en los lugares más duros... pero a veces necesita un poco de mano.",
    ["I've sent a few druids out to try and investigate whether this healing effect has affected Gielinor elsewhere, but we just don't have the hands to maintain this area while investigating other lands."] = "Envié algunos druidas para intentar investigar si este efecto curativo ha afectado a Gielinor en otros lugares, pero simplemente no tenemos las manos para mantener esta área mientras investigamos otras tierras.",
    ["Is there anything I can do to help?"] = "¿Hay algo que pueda hacer para ayudar?",
    ["I'm not sure you have the skills we need for this task."] = "No estoy seguro de que tengas las habilidades que necesitamos para esta tarea.",
    ["You need level 50 Farming to help Polletix."] = "Necesitas el nivel 50 Farming para ayudar a Polletix.",
    ["Now that you ask, we could use some extra help."] = "Ahora que lo preguntas, nos vendría bien un poco de ayuda adicional.",
    ["I hear you're a pretty experienced farmer."] = "He oído que eres un granjero con mucha experiencia.",
    ["What do you want me to do?"] = "¿Qué quieres que haga?",
    ["We need you to head out and farm herbs - as many as you can."] = "Necesitamos que salgas a cultivar hierbas, tantas como puedas.",
    ["Herbs?"] = "¿Hierbas?",
    ["Herbs!"] = "¡Hierbas!",
    ["HERBS!"] = "¡HIERBAS!",
    ["Why do you need me to farm herbs?"] = "¿Por qué me necesitas para cultivar hierbas?",
    ["Herbs are peculiar plants requiring specific soil conditions to grow correctly."] = "Las hierbas son plantas peculiares que requieren condiciones específicas del suelo para crecer correctamente.",
    ["If there's anything different with their environment, the plants will tell you."] = "Si hay algo diferente en su entorno, las plantas te lo dirán.",
    ["Got it, plant herbs and look out for anything odd. Is there any kind of reward?"] = "Entendido, planta hierbas y ten cuidado con cualquier cosa extraña. ¿Hay algún tipo de recompensa?",
    ["Guess I should've expected that."] = "Supongo que debería haber esperado eso.",
    ["Tell you what, as a reward for helping out I'll award you some Crux Eqal favour every time you harvest a herb patch. I'll give you extra favour if you planted multiple seeds at once."] = "Te diré una cosa, como recompensa por ayudar, te otorgaré un favor de Crux Eqal cada vez que coseches un huerto de hierbas. Te haré un favor adicional si plantaste varias semillas a la vez.",
    ["Magic druid coins? Great!"] = "Magic druida coins? ¡Excelente!",
    ["Well actually, they're no-"] = "Bueno, en realidad, no son-",
    ["What can I spend them on?"] = "¿En qué puedo gastarlos?",
    ["Well, Sydekix here would be happy to teach you some of our techniques in exchange for favour."] = "Bueno, Sydekix estará encantado de enseñarte algunas de nuestras técnicas a cambio de un favor.",
    ["I would?"] = "¿Lo haría?",
    ["Yes, you would."] = "Sí, lo harías.",
    ["Adventurer, it's essential we don't disrupt the natural balance of Gielinor. For that reason, I'll also request that you farm a specific herb each day. It'll help us check if different species of herb are being affected and I'll also give you some extra favour for the effort."] = "Aventurero, es esencial que no alteremos el equilibrio natural de Gielinor. Por esa razón, también te pediré que cultives una hierba específica cada día. Nos ayudará a comprobar si diferentes especies de hierbas se están viendo afectadas y también te haré un favor extra por el esfuerzo.",
    ["You don't really think that the global balance of Gielinor would be affected by me planting a few random herbs do you?"] = "Realmente no crees que el equilibrio global de Gielinor se vería afectado si yo plantara algunas hierbas al azar, ¿verdad?",
    ["Not on its own. But with all the other adventurers that are pouring in here lately looking to help, maybe. So please check with me for which herb to farm each day."] = "No por sí solo. Pero con todos los demás aventureros que están llegando aquí últimamente buscando ayudar, tal vez. Así que por favor consulte conmigo qué hierba cultivar cada día.",
    ["Right - harvest herbs, anything weird, magic coins, learn from Sydekix, daily herb request. Anything else?"] = "Correcto: cosecha hierbas, cualquier cosa rara, coins mágico, aprende de Sydekix, solicitud diaria de hierbas. ¿Algo más?",
    ["I think that's it! Thanks for your help, adventurer."] = "¡Creo que eso es todo! Gracias por tu ayuda, aventurero.",
    ["What caused the desert to heal?"] = "¿Qué causó que el desierto sanara?",
    ["Do you know what has caused the desert to start healing?"] = "¿Sabes qué ha provocado que el desierto comience a sanar?",
    ["We're not quite sure yet, or if the healing is even confined to this area."] = "No estamos muy seguros todavía, ni siquiera si la curación se limita a esta área.",
    ["The Edicts."] = "Los Edictos.",
    ["Could the Edicts being reestablished have caused this?"] = "¿Podrían haber causado esto los Edictos que se están restableciendo?",
    ["Guthix's Edicts are outside of my field of knowledge, but if they did cause this we'd expect to see similar events happening across Gielinor. The elders seem to think that the Wilderness would be the most likely location to show signs of healing, if this was the case."] = "Los Edictos de Guthix están fuera de mi campo de conocimiento, pero si causaron esto, esperaríamos ver eventos similares sucediendo en Gielinor. Los ancianos parecen pensar que Wilderness sería el lugar más probable para mostrar signos de curación, si este fuera el caso.",
    ["The Gods."] = "Los dioses.",
    ["Could the gods being banished have caused this?"] = "¿Podrían haber causado esto los dioses que fueron desterrados?",
    ["Hmm, it's a good question. If it were the case, we'd expect the same to have occurred when Guthix initially banished the other gods, but we have no writings to suggest Gielinor spontaneously began to flourish. However, we don't truly know what the gods were capable of. It's possible that they were affecting the true balance of Gielinor. Hmm... I wonder... It's impossible to know what the gods were truly up to behind closed doors. Could the desert healing be part of some master plan, rather than a side effect of their banishment?"] = "Hmm, es una buena pregunta. Si fuera el caso, esperaríamos que hubiera ocurrido lo mismo cuando Guthix inicialmente desterró a los otros dioses, pero no tenemos escritos que sugieran que Gielinor comenzó a florecer espontáneamente. Sin embargo, no sabemos realmente de qué eran capaces los dioses. Es posible que estuvieran afectando el verdadero equilibrio de Gielinor. Hmm... Me pregunto... Es imposible saber qué estaban realmente haciendo los dioses a puerta cerrada. ¿Podría la curación del desierto ser parte de algún plan maestro, en lugar de un efecto secundario de su destierro?",
    ["Do you think that's likely?"] = "¿Crees que eso es probable?",
    ["Impossible to know really, unless we find a different cause."] = "Imposible saberlo realmente, a menos que encontremos una causa diferente.",
    ["Het's Oasis."] = "Es Oasis.",
    ["Do you think Het's Oasis could be affecting the surrounding land?"] = "¿Crees que el Oasis de Het podría estar afectando el terreno circundante?",
    ["That's my best guess currently. However, if we find that the healing effect isn't localised then it probably rules this out."] = "Esa es mi mejor suposición actualmente. Sin embargo, si encontramos que el efecto curativo no está localizado entonces probablemente lo descarte.",
    ["Also, we're not certain if the waters of the oasis alone could heal this part of the desert."] = "Además, no estamos seguros de que las aguas del oasis por sí solas puedan curar esta parte del desierto.",
    ["Well, from all the writings we can find, the Kharidian desert is essentially dead. The River Elid is large and as clean as water gets, yet even on its shores, life struggles to grow."] = "Bueno, de todos los escritos que podemos encontrar, el Kharidian desert está esencialmente muerto. El río Elid es grande y tan limpio como el agua, pero incluso en sus orillas la vida lucha por crecer.",
    ["The Tree of Balance."] = "El árbol del equilibrio.",
    ["Do you think the Tree of Balance could be affecting the area?"] = "¿Crees que el Árbol del Equilibrio podría estar afectando el área?",
    ["I don't think so. I think it's more likely that this area and the tree stem from the same root cause."] = "No lo creo. Creo que es más probable que esta área y el árbol tengan la misma causa fundamental.",
    ["Some think the tree is the manifestation of Guthix's divine energy."] = "Algunos piensan que el árbol es la manifestación de la energía divina de Guthix.",
    ["It could be possible that the energy released when Guthix died is setting and affecting the world."] = "Es posible que la energía liberada cuando murió Guthix esté afectando al mundo.",
    ["Okay, bye!"] = "¡Está bien, adiós!",
    ["going on here?"] = "pasando aquí?",
    ["Greetings adventurer."] = "Saludos aventurero.",
    ["How goes the desert?"] = "¿Cómo va el desierto?",
    ["Things are progressing nicely, adventurer."] = "Las cosas están progresando muy bien, aventurero.",
    ["We've still not found the source of the healing, but the area is flourishing nicely."] = "Todavía no hemos encontrado la fuente de la curación, pero el área está floreciendo muy bien.",
    ["Can I see the daily herb?"] = "¿Puedo ver la hierba diaria?",
    ["What herb would you like me to harvest today?"] = "¿Qué hierba te gustaría que coseche hoy?",
    ["To help maintain balance, today I'd like you to plant and harvest: [Herb seed name]."] = "Para ayudar a mantener el equilibrio, hoy me gustaría que plantes y coseches: [Herb seed name].",
    ["How do I get more Crux Eqal favour?"] = "¿Cómo obtengo más favores de Crux Eqal?",
    ["How do I get Crux Eqal favour? I've forgotten."] = "¿Cómo obtengo el favor de Crux Eqal? Lo he olvidado.",
    ["No problem. You'll be award some favour whenever you harvest a herb patch. You'll get extra for having multiple seeds planted in a patch."] = "No hay problema. Recibirás un favor cada vez que coseches un huerto de hierbas. Obtendrás un extra por plantar varias semillas en un huerto.",
    ["You'll also gain bonus favour if the herbs you harvest match my daily request."] = "También obtendrás un favor adicional si las hierbas que cosechas coinciden con mi pedido diario.",
    ["Okay, thanks!"] = "¡Bien, gracias!",
    ["Hello, pleased to meet you."] = "Hola, encantado de conocerte.",
    ["Can you tell me what you are wearing?"] = "¿Puedes decirme qué llevas puesto?",
    ["Certainly! I am wearing what is known as ganodermic armour. The staff on my back is a polypore staff. I bought the base of this armour from a rather peculiar man in the Polypore Dungeon, found between the Mage Training Area and Mort Myre Swamp. I delved right to the very depths of the dungeon and slayed many Ganodermic beasts, picking fungal flakes off them and applying them to my armour."] = "¡Por supuesto! Llevo lo que se conoce como armadura ganodérmica. El staff que tengo en la espalda es un staff de poliporo. Le compré la base de esta armadura a un hombre bastante peculiar en Polypore Dungeon, que se encuentra entre el área de entrenamiento de magos y Mort Myre Swamp. Profundicé hasta las profundidades de la mazmorra y maté a muchas bestias Ganodermic, quitándoles escamas de hongos y aplicándolas a mi armadura.",
    ["Sounds unhealthy..."] = "Suena poco saludable...",
    ["Haha true, but as a mage I find this equipment very good for my health. Very good for my wellbeing. My enemies' health...not so much."] = "Jaja, es cierto, pero como mago encuentro este equipo muy bueno para mi salud. Muy bueno para mi bienestar. La salud de mis enemigos... no tanto.",
    ["Can you direct me towards the Polypore Dungeon?"] = "¿Puedes indicarme hacia el Polypore Dungeon?",
    ["Certainly. I shall mark it on your map for you."] = "Por supuesto. Lo marcaré en tu mapa por ti.",
    ["Can I ask you about something else?"] = "¿Puedo preguntarte algo más?",
    ["*(Returns to previous options)*"] = "*(Vuelve a opciones anteriores)*",
    ["Goodbye"] = "Adiós",
    ["Can you tell me what the people on the stands behind you are wearing?"] = "¿Puedes decirme qué visten las personas que están detrás de ti en las gradas?",
    ["The man directly behind me is in armour worn by the famous Zarosian warrior, Torva. He would have picked that up in an icy dungeon that we call the God Wars Dungeon. The Godwars Dungeon is a chaotic remnant of the Third Age, filled with the ever-warring armies of the gods. The generals of these armies are said to be some of the best combatants RuneScape has to offer. The lady in the centre is wearing magical armour called spider silk made by crafters. The man on the right is wearing infinity robes. That armour is obtained while training at the famous Mage Training Arena."] = "El hombre que está justo detrás de mí lleva una armadura usada por el famoso guerrero zarosiano, Torva. Habría aprendido eso en una mazmorra helada que llamamos God Wars Dungeon. El Godwars Dungeon es un remanente caótico de la Tercera Edad, lleno de los ejércitos de los dioses en constante guerra. Se dice que los generales de estos ejércitos son algunos de los mejores combatientes que RuneScape tiene para ofrecer. La dama del centro lleva una armadura mágica llamada seda de araña hecha por artesanos. El hombre de la derecha lleva una túnica infinita. Esa armadura se obtiene mientras entrenas en el famoso Mage Training Arena.",
    ["Can you direct me towards the God Wars Dungeon?"] = "¿Puedes indicarme hacia el God Wars Dungeon?",
    ["Can you direct me towards the Mage Training Arena?"] = "¿Puedes indicarme hacia el Mage Training Arena?",
    ["Step aside, you low-born oaf!"] = "¡Hazte a un lado, idiota de baja cuna!",
    ["Hey! Who are you calling names?"] = "¡Oye! ¿A quién estás insultando?",
    ["I have no idea. Some 'hero' I would guess."] = "No tengo idea. Algún 'héroe', supongo.",
    ["Look you..."] = "Mira...",
    ["Hush. I have far too much money to listen to the idle prattle of menials. Begone!"] = "Silencio. Tengo demasiado dinero para escuchar la charla inútil de los sirvientes. ¡Vete!",
    ["You skilfully snatch the key from the jaws of the skater."] = "Arrebatas hábilmente la llave de las fauces del patinador.",
    ["Now useless, the key vanishes from your hands."] = "Ahora inútil, la llave desaparece de tus manos.",
    ["The act of simply retrieving the key is enough to deactivate the magical seals on the doors."] = "El simple hecho de recuperar la llave es suficiente para desactivar los sellos mágicos de las puertas.",
    ["I cannot speak to you outerlander! Talk to Brundt, the Chieftain!"] = "¡No puedo hablar contigo, extranjero! ¡Habla con Brundt, el cacique!",
    ["They are too suspicious of you for you to get close enough to steal from them."] = "Sospechan demasiado de ti como para que te acerques lo suficiente como para robarles.",
    ["*When speaking to Pontak in Rellekka.*"] = "*Al hablar con Pontak en Rellekka.*",
    ["*Pontak may greet you with any of the following at random:*"] = "*Pontak puede saludarte con cualquiera de los siguientes al azar:*",
    ["*Greeting 1:*"] = "*Saludo 1:*",
    ["How are you, [Fremennik name]? I hope all fares well with you this day!"] = "¿Cómo estás, [Fremennik name]? ¡Espero que a todos les vaya bien este día!",
    ["I'm fine, thanks, how are you?"] = "Estoy bien, gracias, ¿cómo estás?",
    ["All is well with me also!"] = "¡Todo está bien para mí también!",
    ["*Greeting 2:*"] = "*Saludo 2:*",
    ["Hello again, [sister/brother] [Fremennik name]. What need you of me this day? You can always rely on my assistance!"] = "Hola de nuevo, [sister/brother] [Fremennik name]. ¿Qué necesitas de mí este día? ¡Siempre puedes confiar en mi ayuda!",
    ["*Greeting 3:*"] = "*Saludo 3:*",
    ["Hello. Did you want something, [Fremennik name]?"] = "Hola. ¿Querías algo, [Fremennik name]?",
    ["*Greeting 4:*"] = "*Saludo 4:*",
    ["[Fremennik name], it has been too long since last we met!"] = "[Fremennik name], ¡ha pasado demasiado tiempo desde la última vez que nos vimos!",
    ["*Greeting 5:*"] = "*Saludo 5:*",
    ["Welcome back, [sister/brother] [Fremennik name]. It is always a pleasure to see you here!"] = "Bienvenido de nuevo, [sister/brother] [Fremennik name]. ¡Siempre es un placer verte por aquí!",
    ["*Greeting 6:*"] = "*Saludo 6:*",
    ["Hello to you, too!"] = "¡Hola a ti también!",
    ["*Greeting 7:*"] = "*Saludo 7:*",
    ["Always good to see you, [sister/brother] [Fremennik name]."] = "Siempre es un placer verte, [sister/brother] [Fremennik name].",
    ["Select an option (all greetings continue with dialogue below)"] = "Seleccione una opción (todos los saludos continúan con el diálogo a continuación)",
    ["*Pontak may reply to you with any of the following at random:*"] = "*Pontak puede responderle con cualquiera de los siguientes mensajes al azar:*",
    ["*Reply 1:*"] = "*Respuesta 1:*",
    ["He died saving you, [Fremennik name]. Make sure you use his final gift wisely and live a life that we can all be proud of."] = "Él murió salvándote, [Fremennik name]. Asegúrate de utilizar sabiamente su regalo final y vivir una vida de la que todos podamos estar orgullosos.",
    ["*Reply 2:*"] = "*Respuesta 2:*",
    ["He was a great hero to our people. Why couldn't they have gone for one of the bad gods, like Zamorak or Saradomin?"] = "Fue un gran héroe para nuestro pueblo. ¿Por qué no pudieron haber elegido a uno de los dioses malos, como Zamorak o Saradomin?",
    ["*Reply 3:*"] = "*Respuesta 3:*",
    ["*Reply 4:*"] = "*Respuesta 4:*",
    ["It's sad that he's gone, but he will live on as an inspiration to countless heroes across countless worlds."] = "Es triste que se haya ido, pero seguirá viviendo como una inspiración para innumerables héroes en innumerables mundos.",
    ["Welcome to this grand cave of Guthix, traveller."] = "Bienvenido a esta gran cueva de Guthix, viajero.",
    ["So, what do I do here?"] = "Entonces, ¿qué hago aquí?",
    ["Ah, you should probably talk to the organ grinder not the monkey."] = "Ah, probablemente deberías hablar con el organillero, no con el mono.",
    ["Talk to Fiara, she's in charge here."] = "Habla con Fiara, ella está a cargo aquí.",
    ["Which is she? None of you look female to me."] = "¿Quién es ella? Ninguno de ustedes me parece mujer.",
    ["No, no - Fiara is the Guardian of this place. Created by Guthix to keep a watchful eye over this holy site."] = "No, no. Fiara es el guardián de este lugar. Creado por Guthix para vigilar este lugar sagrado.",
    ["Guardian? You mean that weird looking giant earwig at the back of the cave?"] = "¿Guardián? ¿Te refieres a esa tijereta gigante de aspecto extraño que hay al fondo de la cueva?",
    ["Don't refer to a holy Guardian of Guthix like that. You can call her Lady Fiara."] = "No te refieras así a un santo Guardián de Guthix. Puedes llamarla Lady Fiara.",
    ["But she's not a lady, she's a giant earwig."] = "Pero ella no es una dama, es una tijereta gigante.",
    ["Don't argue, just go and talk to her. And be polite."] = "No discutas, solo ve y habla con ella. Y sea cortés.",
    ["So, what is this place?"] = "Entonces, ¿qué es este lugar?",
    ["This is a sacred site of Guthix."] = "Este es un sitio sagrado de Guthix.",
    ["Why is it sacred?"] = "¿Por qué es sagrado?",
    ["Guthix places guardians in places of holy power. There is one such guardian here."] = "Guthix coloca guardianes en lugares de poder sagrado. Hay uno de esos guardianes aquí.",
    ["But what is special about this place?"] = "¿Pero qué tiene de especial este lugar?",
    ["It exudes a dangerous magical power that we have been entrusted to protect."] = "Exuda un peligroso poder mágico que se nos ha confiado proteger.",
    ["Where did this power come from?"] = "¿De dónde vino este poder?",
    ["It comes from the centre of the big cave."] = "Viene del centro de la gran cueva.",
    ["What's special about the centre?"] = "¿Qué tiene de especial el centro?",
    ["It's very magical."] = "Es muy mágico.",
    ["Yes, I get that. Why is it magical?"] = "Sí, lo entiendo. ¿Por qué es mágico?",
    ["Something to do with the Fist of Guthix."] = "Algo que ver con el Puño de Guthix.",
    ["And what is that, exactly?"] = "¿Y qué es eso exactamente?",
    ["The truth is, none of us really know."] = "La verdad es que ninguno de nosotros lo sabe realmente.",
    ["This place is special to Guthix, because Fiara is here."] = "Este lugar es especial para Guthix, porque Fiara está aquí.",
    ["And we know it has something to do with the 'Fist of Guthix' because Fiara occasionally mentions it."] = "Y sabemos que tiene algo que ver con el 'Puño de Guthix' porque Fiara lo menciona ocasionalmente.",
    ["But other than that, we only have theories. Do you want to hear about them?"] = "Pero aparte de eso, sólo tenemos teorías. ¿Quieres oír hablar de ellos?",
    ["I suppose so..."] = "Supongo que sí...",
    ["Getorix's theory."] = "La teoría de Getorix.",
    ["Well, this is Getorix's silly theory. Listen to it, if you must."] = "Bueno, esta es la tonta teoría de Getorix. Escúchalo, si es necesario.",
    ["At the end of the God Wars, Guthix returned to Gielinor and was angered by the destruction caused by the other gods in their vanity and quest for power. So, maybe he punched the ground in anger, leaving an imprint of power on the ground that has lasted ever since."] = "Al final de las Guerras de Dios, Guthix regresó a Gielinor y estaba enojado por la destrucción causada por los otros dioses en su vanidad y búsqueda de poder. Entonces, tal vez golpeó el suelo con ira, dejando una huella de poder en el suelo que ha perdurado desde entonces.",
    ["Because he was angry at the time, the power would have been tainted with aggression, which is why he left Fiara as a guardian, to make sure the power did not escape unfettered."] = "Debido a que estaba enojado en ese momento, el poder se habría visto contaminado con agresión, razón por la cual dejó a Fiara como guardián, para asegurarse de que el poder no escapara sin restricciones.",
    ["Do you believe this theory?"] = "¿Crees en esta teoría?",
    ["No, I think it's rubbish; if it was true, that would mean Guthix's hand would be a very strange shape. The indentation in the centre of the cave doesn't look like a fist to me. Getorix has just let his imagination run away with him. My theory is better."] = "No, creo que es basura; si fuera cierto, eso significaría que la mano de Guthix tendría una forma muy extraña. La hendidura en el centro de la cueva no me parece un puño. Getorix acaba de dejar volar su imaginación. Mi teoría es mejor.",
    ["Do you want to hear another theory?"] = "¿Quieres escuchar otra teoría?",
    ["Pontimer's theory."] = "La teoría de Pontimer.",
    ["If you want the true story, then this is it."] = "Si quieres la historia real, entonces ésta es.",
    ["After the God Wars, Guthix found something dangerous here and used his power to protect it."] = "Después de las Guerras de Dios, Guthix encontró algo peligroso aquí y usó su poder para protegerlo.",
    ["What did he find?"] = "¿Qué encontró?",
    ["I don't know for certain, but it must be under that strange impression in the big cave. I think that mark is some sort of ward that Guthix has left to protect the site."] = "No lo sé con certeza, pero debe ser bajo esa extraña impresión en la gran cueva. Creo que esa marca es una especie de protección que Guthix dejó para proteger el sitio.",
    ["So where does the Fist of Guthix come into this, then?"] = "Entonces, ¿dónde entra en esto el Puño de Guthix?",
    ["Hmmm. I'm not really sure. I think that when Fiara refers to the Fist of Guthix she is talking metaphorically about an abstract concept of fist-ness rather than the clenched right hand of Guthix itself."] = "Mmmm. No estoy realmente seguro. Creo que cuando Fiara se refiere al Puño de Guthix, está hablando metafóricamente de un concepto abstracto de puño en lugar de la mano derecha apretada de Guthix.",
    ["That sounds a bit...made up to me."] = "Eso suena un poco... inventado para mí.",
    ["Why you impudent...bah. It's better than anything that Getorix and Alran can come up with, anyway."] = "Por qué eres descarado...bah. De todos modos, es mejor que cualquier cosa que se les ocurra a Getorix y Alran.",
    ["Alran's theory."] = "La teoría de Alran.",
    ["This is what Alran thinks, for what it's worth...which isn't very much, if you ask me."] = "Esto es lo que piensa Alran, por lo que vale... que no es mucho, si me preguntas.",
    ["Guthix has apparently left us a test. He deliberately created this site of power as a test of individual strength and balance."] = "Guthix aparentemente nos ha dejado una prueba. Creó deliberadamente este sitio de poder como una prueba de fuerza y ​​equilibrio individual.",
    ["Does Guthix do that sort of thing?"] = "¿Guthix hace ese tipo de cosas?",
    ["Well, no! I agree with you entirely. This theory has so many holes that it makes no sense at all!"] = "¡Pues no! Estoy totalmente de acuerdo contigo. ¡Esta teoría tiene tantos agujeros que no tiene ningún sentido!",
    ["I'd better get going."] = "Será mejor que me vaya.",
    ["Who's the weird looking giant earwig?"] = "¿Quién es la tijereta gigante de aspecto extraño?",
    ["Shhh! Give Fiara some respect! She can hear you, you know."] = "¡Shhh! ¡Dale un poco de respeto a Fiara! Ella puede oírte, ¿sabes?",
    ["Fiara? It has a name?"] = "¿Fiara? ¿Tiene un nombre?",
    ["Of course, Guthix chooses names for all his guardians."] = "Por supuesto, Guthix elige nombres para todos sus guardianes.",
    ["If...err...Fiara is a Guardian, what is she guarding?"] = "Si... err... Fiara es una Guardiana, ¿qué está protegiendo?",
    ["She guards this site. It is a holy site of Guthix."] = "Ella protege este sitio. Es un lugar sagrado de Guthix.",
    ["How long has Fiara been here?"] = "¿Cuánto tiempo lleva aquí Fiara?",
    ["Errr, ages. Since the end of the God Wars I think. She doesn't talk about that much."] = "Errr, edades. Desde el final de las Guerras de Dios, creo. Ella no habla mucho de eso.",
    ["So what are you doing here?"] = "Entonces, ¿qué estás haciendo aquí?",
    ["Meow!"] = "¡Miau!",
    ["Meow."] = "Miau.",
    ["Meow..."] = "Miau...",
    ["Meow?"] = "¿Miau?",
    ["Meowwwwww."] = "Miauwwwwww.",
    ["Can't talk. Must get my daily steps in."] = "No puedo hablar. Debo realizar mis pasos diarios.",
    ["Out of the way, human! I have places to go and animals to see."] = "¡Fuera del camino, humano! Tengo lugares adonde ir y animales que ver.",
    ["Why are you called Pork Pie?"] = "¿Por qué te llaman Pork Pie?",
    ["Why are you called Player?"] = "¿Por qué te llamas Player?",
    ["I'm not sure, actually."] = "En realidad, no estoy seguro.",
    ["If you must know. My human, Hawk, considers them to be a delicacy."] = "Si debes saberlo. Mi humano, Hawk, los considera un manjar.",
    ["He got one from a travelling merchant, just one time, and now look at me. Named after a baked good!"] = "Consiguió uno de un travelling merchant, solo una vez, y ahora mírame. ¡El nombre de un producto horneado!",
    ["HALT! Who goes there?"] = "¡ALTO! ¿Quién va ahí?",
    ["Don't worry, I'm not going to cause trouble."] = "No te preocupes, no voy a causar problemas.",
    ["But you shouldn't be here - be off with you!"] = "Pero no deberías estar aquí, ¡vete!",
    ["I was going anyway."] = "Iba a ir de todos modos.",
    ["I am Player the Mighty!"] = "¡Soy Player el Poderoso!",
    ["Mighty? You look like another of those silly adventurers who thinks they're the bee's knees just because they've done a few lousy quests!"] = "¿Poderoso? ¡Pareces otro de esos tontos aventureros que se creen los mejores sólo porque han realizado unas cuantas misiones pésimas!",
    ["Well it sounds better than sitting on this rooftop all day looking at trees!"] = "¡Bueno, suena mejor que estar sentado en esta azotea todo el día mirando los árboles!",
    ["I'll have you know it's a very important job guarding this jail!"] = "¡Te haré saber que es un trabajo muy importante proteger esta cárcel!",
    ["If anyone comes sneaking in here to mess around with the prisoners, the lads downstairs will make mincemeat of them, and I'll be here to pick them off if they try to escape."] = "Si alguien entra aquí a escondidas para meterse con los prisioneros, los muchachos de abajo los harán picadillo y yo estaré aquí para eliminarlos si intentan escapar.",
    ["You mean people aren't meant to be able to shoot the prisoners in the cells?"] = "¿Quieres decir que la gente no debe poder disparar a los prisioneros en las celdas?",
    ["Yes, that's right."] = "Sí, es cierto.",
    ["Okay, it's been nice talking to you."] = "Está bien, ha sido un placer hablar contigo.",
    ["No-one, there's no-one here."] = "Nadie, no hay nadie aquí.",
    ["What? I can see you!"] = "¿Qué? ¡Puedo verte!",
    ["No, you're just imagining it. Perhaps you've been up here in the sun for too long?"] = "No, solo te lo estás imaginando. ¿Quizás llevas demasiado tiempo aquí expuesto al sol?",
    ["So who am I talking to?"] = "Entonces, ¿con quién estoy hablando?",
    ["Oh dear, you've started talking to yourself. That's a common sign that you're going mad!"] = "Dios mío, has empezado a hablar solo. ¡Esa es una señal común de que te estás volviendo loco!",
    ["But... but... you're standing right there..."] = "Pero... pero... estás parado ahí mismo...",
    ["Maybe you should leave him alone now."] = "Quizás deberías dejarlo en paz ahora.",
    ["Maybe I should let him sleep."] = "Quizás debería dejarlo dormir.",
    ["Me? I'm a musician! Let me help you relax: sit down, rest your weary limbs and allow me to wash away the troubles of the day. After a long trek, what could be better than some music to give you the energy to continue? Did you know music has curative properties? Music stimulates the healing humours in your body, so they say."] = "¿Yo? ¡Soy músico! Déjame ayudarte a relajarte: siéntate, descansa tus miembros cansados ​​y permíteme eliminar los problemas del día. Después de un largo viaje, ¿qué mejor que un poco de música para darte energía para continuar? ¿Sabías que la música tiene propiedades curativas? La música estimula los humores curativos del cuerpo, según dicen.",
    ["Who says that, then?"] = "¿Quién dice eso entonces?",
    ["I was told by a travelling medical practitioner, selling oil extracted from snakes. It's a commonly known fact, so he said. After resting to some music, you will be able to run longer and your life points will increase noticeably. A panacea, if you will. Ah, the power of music."] = "Me lo contó un médico que viajaba y vendía aceite extraído de serpientes. Es un hecho comúnmente conocido, dijo. Después de descansar con un poco de música, podrás correr más tiempo y tus puntos de vida aumentarán notablemente. Una panacea, por así decirlo. Ah, el poder de la música.",
    ["So, just listening to some music will cure me of all my ills?"] = "Entonces, ¿solo escuchar un poco de música me curará de todos mis males?",
    ["Well, not quite. Poison, lack of faith and dismembered limbs are all a bit beyond even the most rousing of harmonies, but I guarantee you will feel refreshed, and better equipped to take on the challenges of the day."] = "Bueno, no del todo. El veneno, la falta de fe y los miembros desmembrados están un poco más allá incluso de las armonías más conmovedoras, pero te garantizo que te sentirás renovado y mejor equipado para afrontar los desafíos del día.",
    ["Does this cost me anything?"] = "¿Esto me cuesta algo?",
    ["Oh, no! My reward is the pleasure I bring to the masses. Just remember me and tell your friends, and that is payment enough. So sit down and enjoy!"] = "¡Oh, no! Mi recompensa es el placer que brindo a las masas. Sólo recuérdame y díselo a tus amigos, y eso es pago suficiente. ¡Así que siéntate y disfruta!",
    ["Can I ask you some questions about resting?"] = "¿Puedo hacerte algunas preguntas sobre el descanso?",
    ["How does resting work?"] = "¿Cómo funciona el descanso?",
    ["Have you ever been on a long journey, and simply wanted to have a rest? When you're running from city to city, it's so easy to run out of breath, don't you find?"] = "¿Alguna vez has estado en un viaje largo y simplemente quisiste descansar? Cuando corres de ciudad en ciudad, es muy fácil quedarte sin aliento, ¿no te parece?",
    ["Yes, I can never run as far as I'd like."] = "Sí, nunca puedo correr tan lejos como quisiera.",
    ["Well, you may rest anywhere, simply choose the Rest option on the run buttons. When you rest, you will sit on the floor. When you are nice and relaxed, you will recharge your run energy more quickly and your life points twice as fast as you would do normally. Of course, you can't do anything else while you're resting, other than talk."] = "Bueno, puedes descansar en cualquier lugar, simplemente elige la opción Descanso en los botones de ejecución. Cuando descanses, te sentarás en el suelo. Cuando estés agradable y relajado, recargarás tu energía de carrera más rápidamente y tus puntos de vida dos veces más rápido de lo que lo harías normalmente. Por supuesto, mientras descansas no puedes hacer nada más que hablar.",
    ["Why not?"] = "¿Por qué no?",
    ["Well, you wouldn't be resting, now would you? Also, you should know that resting by a musician, has a similar effect but the benefits are greater."] = "Bueno, no estarías descansando, ¿verdad? Además, debes saber que el descanso junto a un músico, tiene un efecto similar pero los beneficios son mayores.",
    ["What's special about resting by a musician?"] = "¿Qué tiene de especial el descanso de un músico?",
    ["The effects of resting are enhanced by music. Your run energy will recharge many times the normal rate, and your life points three times as fast. Simply sit down and rest as you would normally, nice and close to the musician. You'll turn to face the musician and hear the music. Like resting anywhere, if you do anything other than talk, you will stop resting."] = "Los efectos del descanso se potencian con la música. Tu energía de carrera se recargará muchas veces más rápido que lo normal y tus puntos de vida tres veces más rápido. Simplemente siéntate y descansa como lo harías normalmente, agradable y cerca del músico. Te volverás hacia el músico y escucharás la música. Como descansar en cualquier lugar, si haces algo más que hablar, dejarás de descansar.",
    ["Can you summarise the effects for me?"] = "¿Puedes resumirme los efectos?",
    ["Certainly. You can rest anywhere, simply choose the Rest option on the run buttons. Resting anywhere will replenish your run energy more quickly than normal, your life points will replenish twice as fast as well! Resting by a musician will replenish your run energy many times faster than normal, and your life points will also replenish three times as fast."] = "Por supuesto. Puedes descansar en cualquier lugar, simplemente elige la opción Descanso en los botones de ejecución. Descansar en cualquier lugar repondrá tu energía para correr más rápido de lo normal, ¡y tus puntos de vida también se repondrán el doble de rápido! Descansar junto a un músico repondrá tu energía de carrera muchas veces más rápido de lo normal, y tus puntos de vida también se repondrán tres veces más rápido.",
    ["That's all for now."] = "Eso es todo por ahora.",
    ["Can I ask you some questions about running?"] = "¿Puedo hacerte algunas preguntas sobre correr?",
    ["Running? Of course! Not that I do much running, I prefer to saunter. But you adventuring types always seem to be in a rush, zipping hither and thither."] = "¿Corriendo? ¡Por supuesto! No es que corro mucho, prefiero pasear. Pero ustedes, los aventureros, siempre parecen tener prisa, yendo de aquí para allá.",
    ["Why do I need to run anyway?"] = "¿Por qué necesito ejecutar de todos modos?",
    ["Running is the simplest way to get somewhere quickly. When you run you move twice as fast as you normally would. Also, you don't look like the cowardly type, but most creatures can't run very fast, so if you don't want to fight, you can always run away."] = "Correr es la forma más sencilla de llegar rápidamente a algún lugar. Cuando corres, te mueves el doble de rápido de lo que lo harías normalmente. Además, no pareces del tipo cobarde, pero la mayoría de las criaturas no pueden correr muy rápido, así que si no quieres pelear, siempre puedes huir.",
    ["Can I keep running forever?"] = "¿Puedo seguir corriendo para siempre?",
    ["No, eventually you'll get tired. When that happens you will stop running, and start walking. It takes a while to get your breath back, but once you've recovered a little, you can start running again. You recover quickly whilst resting, or more slowly whilst walking."] = "No, eventualmente te cansarás. Cuando eso suceda, dejarás de correr y empezarás a caminar. Te llevará un tiempo recuperar el aliento, pero una vez que te hayas recuperado un poco, podrás empezar a correr de nuevo. Te recuperas rápidamente mientras descansas o más lentamente mientras caminas.",
    ["Well, don't forget to have a rest every now and again."] = "Bueno, no olvides descansar de vez en cuando.",
    ["Pleased to meet you. My name is Relina Vyrel: Gielinor's foremost expert on interdimensional portals."] = "Encantado de conocerte. Mi nombre es Relina Vyrel: la principal experta de Gielinor en portales interdimensionales.",
    ["Portals?"] = "¿Portales?",
    ["Portals are a way to move between or within planes of existence, so a fully open portal would allow beings to move between the planes like moving through a doorway."] = "Los portales son una forma de moverse entre planos de existencia o dentro de ellos, por lo que un portal completamente abierto permitiría a los seres moverse entre los planos como si se movieran a través de una puerta.",
    ["I don't expect someone of your intellect would understand much more than that."] = "No espero que alguien de tu intelecto entienda mucho más que eso.",
    ["It does take a great deal of power to create them, however, and still more to maintain. I am hoping to learn more about controlling this power by studying this portal."] = "Sin embargo, se necesita una gran cantidad de poder para crearlos y aún más para mantenerlos. Espero aprender más sobre cómo controlar este poder estudiando este portal.",
    ["Foremost expert? What about Avalani?"] = "¿El principal experto? ¿Qué pasa con Avalani?",
    ["Hah!"] = "¡Ja!",
    ["Hah?"] = "¿Eh?",
    ["That rank tyro gets one lucky break and suddenly she's the big name in portal dynamics?"] = "¿Esa principiante tiene un golpe de suerte y de repente se convierte en el gran nombre en la dinámica del portal?",
    ["Some of us have actual published studies and journal papers to show for their long efforts in the field."] = "Algunos de nosotros tenemos estudios publicados y artículos de revistas reales que muestran nuestros largos esfuerzos en el campo.",
    ["Although I'm sure a celebrity like Avalani doesn't need anything so dull as peer reputation to consider."] = "Aunque estoy seguro de que una celebridad como Avalani no necesita considerar nada tan aburrido como la reputación de sus pares.",
    ["What is happening here?"] = "¿Qué está pasando aquí?",
    ["I never thought I'd get a chance to see one like this!"] = "¡Nunca pensé que tendría la oportunidad de ver uno como este!",
    ["Ahem. This portal is a true classic of its kind."] = "Ejem. Este portal es un verdadero clásico en su género.",
    ["If my theories are correct, this is the very type of portal that gods use to walk between worlds."] = "Si mis teorías son correctas, este es el tipo de portal que los dioses usan para caminar entre mundos.",
    ["Can you tell me more about portals?"] = "¿Puedes contarme más sobre los portales?",
    ["Portals are a way to move between or within planes off existence, so a fully open portal would allow beings to move between the planes like moving through a doorway."] = "Los portales son una forma de moverse entre planos de existencia o dentro de ellos, por lo que un portal completamente abierto permitiría a los seres moverse entre los planos como si se movieran a través de una puerta.",
    ["Why is the portal here?"] = "¿Por qué está el portal aquí?",
    ["Being a woman of science, I am not given to wild theories, unlike this uneducated rabble."] = "Siendo una mujer de ciencia, no soy dada a teorías descabelladas, a diferencia de esta chusma sin educación.",
    ["Portals are usually created by beings of great power, and my theories indicate that another being - a god, you might say - could have created this portal."] = "Los portales suelen ser creados por seres de gran poder, y mis teorías indican que otro ser (un dios, se podría decir) podría haber creado este portal.",
    ["However, my research also indicates that a portal could be created as an indirect side effect of a sudden unleashed power."] = "Sin embargo, mi investigación también indica que se podría crear un portal como efecto secundario indirecto de un poder desatado repentino.",
    ["If the druids' claim that Guthix has died is true, that could also have been a catalyst for the appearance of the portal."] = "Si la afirmación de los druidas de que Guthix ha muerto es cierta, eso también podría haber sido un catalizador para la aparición del portal.",
    ["I am afraid to say there is no way - at present - for me to know who or what created it. All I can do is study it, and the effects around it, and observe the results."] = "Me temo que no hay manera, en este momento, de saber quién o qué lo creó. Todo lo que puedo hacer es estudiarlo y los efectos que lo rodean y observar los resultados.",
    ["Who are all these people?"] = "¿Quiénes son todas estas personas?",
    ["Well, I hoped that some might be experts such as I, here to study the portal. It seems I was wrong."] = "Bueno, esperaba que algunos expertos como yo estuvieran aquí para estudiar el portal. Parece que me equivoqué.",
    ["They're uneducated layabouts, the lot of them - getting in my way and riling each other up with their wild theories."] = "Son vagos sin educación, todos ellos, que se interponen en mi camino y se irritan unos a otros con sus teorías descabelladas.",
    ["I just wish they'd leave me to my studies. This is the opportunity of a lifetime for me!"] = "Ojalá me dejaran con mis estudios. ¡Esta es la oportunidad de mi vida para mí!",
    ["I will leave you to your studies."] = "Te dejo con tus estudios.",
    ["Just don't get in the way!"] = "¡No te interpongas en el camino!",
    ["Hi, I'm Kags, the portmaster round here. I run a volunteer transportation service and I'm going places!"] = "Hola, soy Kags, el capitán de puerto por aquí. ¡Dirijo un servicio de transporte voluntario y voy a lugares!",
    ["Really, you don't charge?"] = "¿De verdad no cobras?",
    ["I just love the ocean! Where would you like to go?"] = "¡Me encanta el océano! ¿Adónde te gustaría ir?",
    ["Where would you like to go?"] = "¿Adónde te gustaría ir?",
    ["1. Transport to sunken pyramid."] = "1. Transporte a pirámide hundida.",
    ["2. Transport to Crondis's pyramid."] = "2. Transporte a la pirámide de Crondis.",
    ["3. Transport to Jaldraocht."] = "3. Transporte a Jaldraocht.",
    ["1. Transport to Nardah."] = "1. Transporte a Nardah.",
    ["2. Transport to Pollniveach."] = "2. Transporte hasta Pollniveach.",
    ["3. Transport to Dominion Tower."] = "3. Transporte a Dominion Tower.",
    ["*(Postie Pete will periodically appear at one of these locations and engage with the nearby NPC. Players can talk to him. After a few minutes, he will disappear.)*"] = "*(Postie Pete aparecerá periódicamente en una de estas ubicaciones y se relacionará con el NPC cercano. Los jugadores pueden hablar con él. Después de unos minutos, desaparecerá).*",
    ["Hey Pete, what you doing here?"] = "Hola Pete, ¿qué haces aquí?",
    ["Just chatting to my brother Pete. He keeps Parrots."] = "Estoy charlando con mi hermano Pete. Tiene loros.",
    ["Doesn't sound too tough. What's the pay like?"] = "No suena demasiado difícil. ¿Cómo es el sueldo?",
    ["Not very good I'm afraid. His bosses are pretty cheep."] = "Me temo que no muy bien. Sus jefes son bastante tacaños.",
    ["Groan. Don't give up the day job Pete."] = "Gemido. No renuncies a tu trabajo diario, Pete.",
    ["Just doing a quick survey on famous people and their favourite colour. It's a special feature for 'West Wyverns Women's Weekly'."] = "Estoy haciendo una encuesta rápida sobre personajes famosos y su color favorito. Es un artículo especial para 'West Wyverns Women's Weekly'.",
    ["Can I get a copy?"] = "¿Puedo obtener una copia?",
    ["Can you speak Wyvern?"] = "¿Puedes hablar Wyvern?",
    ["No. Can you?"] = "No. ¿Puedes?",
    ["Well obviously."] = "Bueno, obviamente.",
    ["Go on then."] = "Continúa entonces.",
    ["Here! Are you mad? No, 'fraid I can't do that. Could cause all sorts of trouble."] = "¡Aquí! ¿Estás loco? No, me temo que no puedo hacer eso. Podría causar todo tipo de problemas.",
    ["You're a bit mad really aren't you?"] = "Estás un poco enojado, ¿verdad?",
    ["So would you be if you could speak over 1000 languages. I bet it's bliss being ignorant of this world's trouble! I'm off!"] = "Tú también lo serías si pudieras hablar más de 1000 idiomas. ¡Apuesto a que es una bendición ignorar los problemas de este mundo! ¡Me voy!",
    ["Hey Postie Pete how's it going?"] = "Hola Postie Pete, ¿cómo te va?",
    ["I was just trying to get some wise words of wisdom from the Oracle, You know, she's been here a long time"] = "Solo estaba tratando de obtener algunas sabias palabras de sabiduría de Oracle. Sabes, ella ha estado aquí por mucho tiempo.",
    ["Yes, I thought as much, what did she have to say?"] = "Sí, eso mismo pensé, ¿qué tenía ella que decir?",
    ["First she said, \"I am the Oracle. And when I open my lips, let no dog bark\"!"] = "Primero dijo: \"Soy el Oracle. ¡Y cuando abro los labios, no dejes que ningún perro ladre\"!",
    ["I see. And then what?"] = "Ya veo. ¿Y luego qué?",
    ["I didn't know she was familiar with the works of Shakespeare. So I said 'Et tu, brute?"] = "No sabía que ella estaba familiarizada con las obras de Shakespeare. Entonces dije 'Et tu, bruto?",
    ["And then?"] = "¿Y luego?",
    ["Well then she started pointing to Ardougne and rambling on about betrayal!"] = "¡Bueno, entonces empezó a señalar a Ardougne y a divagar sobre la traición!",
    ["Hi Pete, how's things?"] = "Hola Pete, ¿cómo van las cosas?",
    ["Just chatting to my big brother Pete. Hee heee!!"] = "Estoy charlando con mi hermano mayor Pete. ¡¡Ji, ji!!",
    ["What's so funny?"] = "¿Qué es tan gracioso?",
    ["Just a joke that he told me. Care to hear it?"] = "Sólo un chiste que me contó. ¿Te importaría oírlo?",
    ["Yes, go on then."] = "Sí, continúa entonces.",
    ["2 Parrots sit on a perch. One says to the other 'Can you smell fish'? Hee heheee he ho ho."] = "2 loros sentados en una percha. Uno le dice al otro: \"¿Puedes oler el pescado?\" Je, je, je, je, ho, je.",
    ["And so what did the other one say?"] = "¿Y entonces qué dijo el otro?",
    ["Sigh. 2 Parrots sit on a perch. One says to the other 'Can you smell fish'? Hee heheee he ho ho."] = "Suspiro. 2 loros se sientan en una percha. Uno le dice al otro: \"¿Puedes oler el pescado?\" Je, je, je, je, ho, je.",
    ["I see. So... what did the other one say?"] = "Ya veo. Entonces... ¿qué dijo el otro?",
    ["You're serious aren't you. Listen again. 2 Parrots sit on a perch. One says to the other 'Can you smell fish'."] = "Hablas en serio, ¿no? Escuche de nuevo. 2 loros se sientan en una percha. Uno le dice al otro: \"¿Puedes oler el pescado?\".",
    ["Fish, right. So, what was the reply?"] = "Pescado, claro. Entonces, ¿cuál fue la respuesta?",
    ["ARGH!! 2 PARROTS. ON A PERCH. SMELLS FISHY."] = "¡¡ARGH!! 2 LOROS. EN UNA PERCHA. Huele a pescado.",
    ["No, still lost. Is one of them a penguin?"] = "No, todavía estoy perdido. ¿Es uno de ellos un pingüino?",
    ["You're doing it on purpose now aren't you? Please leave me alone!"] = "Lo estás haciendo a propósito, ¿no? ¡Por favor déjame en paz!",
    ["Hey Postie. Hows tricks? Who are you interviewing here?"] = "Hola, Postie. ¿Qué tal trucos? ¿A quién estás entrevistando aquí?",
    ["Everyone deserves a hic break you know. It gets pretty tiring lugging burp letters about all day."] = "Todo el mundo merece un descanso, ¿sabes? Se vuelve bastante agotador cargar con cartas de eructos todo el día.",
    ["I see. Can I join you?"] = "Ya veo. ¿Puedo unirme a ustedes?",
    ["Why, am I hic coming apart?"] = "¿Por qué tengo hipo?",
    ["You've been here a while, haven't you?"] = "Has estado aquí por un tiempo, ¿no?",
    ["Maybe I haves, maybe I haves. It all goes straight to my head you see."] = "Tal vez sí, tal vez sí. Todo se me sube a la cabeza, ¿sabes?",
    ["Yes... I can see that. Bye Pete!"] = "Sí... puedo verlo. ¡Adiós Pete!",
    ["Arrrr. Avast shipmate. Arrr. I Likes the cut of your gibb. Arrr. That it be."] = "Arrrr. Compañero de Avast. Arrr. Me gusta el corte de tu gibb. Arrr. Que así sea.",
    ["Arrr?"] = "¿Arrr?",
    ["I have a strange feeling of Deja Vu. I must go now."] = "Tengo una extraña sensación de Deja Vu. Debo irme ahora.",
    ["HEY PETE, WHAT ARE YOU DOING HERE?"] = "HOLA PETE, ¿QUÉ HACES AQUÍ?",
    ["Shhhh! It's a library you know!"] = "¡Shhhh! ¡Es una biblioteca, sabes!",
    ["Oh, sorry! So, what's new?"] = "¡Oh, lo siento! Entonces, ¿qué hay de nuevo?",
    ["Not much, just doing some research on Dwarvern Culture. Did you know that Keldagrim was originally constructed by a long lost clan who embraced the power of magic, and used it to aid with glorious buildings like the royal palace?"] = "No mucho, solo estoy investigando un poco sobre la cultura enana. ¿Sabías que Keldagrim fue construido originalmente por un clan perdido hace mucho tiempo que abrazó el poder de la magia y lo usó para ayudar con edificios gloriosos como el palacio real?",
    ["Really??"] = "¿¿En serio??",
    ["Yes. They even stayed down there for 1000 years or more, in a time they call 'The age of Kings'."] = "Sí. Incluso permanecieron allí abajo durante 1000 años o más, en una época que llaman \"La era de los Reyes\".",
    ["WOW!"] = "¡GUAU!",
    ["Shhhh! That's enough history for one day I think!"] = "¡Shhhh! ¡Creo que es suficiente historia por un día!",
    ["Pete, what are you doing out here in the deep wilderness?"] = "Pete, ¿qué estás haciendo aquí en lo profundo de wilderness?",
    ["Shhh!! Don't let the others see me here! I'm on a top secret mission for the Burth..., no, nothing. Never mind. Oooo, look, the chaos elemental!! Quick, run!!"] = "¡¡Shhh!! ¡No dejes que los demás me vean aquí! Estoy en una misión ultrasecreta para los Burth..., no, nada. No importa. ¡¡Oooo, mira, el elemental del caos!! ¡¡Rápido, corre!!",
    ["Argh!! Where?"] = "¡¡Arg!! ¿Dónde?",
    ["Postie Pete is talking to someone - don't you know it's rude to interrupt?"] = "Postie Pete está hablando con alguien. ¿No sabes que es de mala educación interrumpir?",
    ["Postie Pete is preparing to teleport somewhere else, distracting him could have some terrible side effects."] = "Postie Pete se está preparando para teletransportarse a otro lugar, distraerlo podría tener efectos secundarios terribles.",
    ["Q – What happens if you right-click and 'Use' your own belly?"] = "P – ¿Qué sucede si haces clic derecho y 'Usas' tu propia barriga?",
    ["A – Nothing intestine happens."] = "R – No pasa nada intestinal.",
    ["Player! So great to hear from you."] = "¡Player! Es genial saber de ti.",
    ["Any mail for me?"] = "¿Algún correo para mí?",
    ["*(If no mail is available:)*"] = "*(Si no hay correo disponible:)*",
    ["No sorry. I'll try and deliver another tomorrow."] = "No lo siento. Intentaré entregar otro mañana.",
    ["*(If mail is available:)*"] = "*(Si el correo está disponible:)*",
    ["What's with all the parcels?"] = "¿Qué pasa con todos los paquetes?",
    ["They're from all the people of Gielinor to all the adventurers to thank them for their hard work! I'll try to send you one each day for 30 days, and if you don't have enough space, just come and see me in Burthorpe once you do. If you want more, you'll just have to get out into the world and try doing something. I'm sure some mail will turn up."] = "¡De parte de toda la gente de Gielinor a todos los aventureros para agradecerles por su arduo trabajo! Intentaré enviarte uno cada día durante 30 días, y si no tienes suficiente espacio, ven a verme a Burthorpe una vez que lo tengas. Si quieres más, tendrás que salir al mundo e intentar hacer algo. Estoy seguro de que aparecerá algún correo.",
    ["What are the postage stamps for?"] = "¿Para qué sirven los sellos postales?",
    ["I'm always sending letters, so I'm interested in any spare postage stamps you may have. I'll even exchange them for an unclaimed parcel."] = "Siempre envío cartas, así que me interesan los sellos postales de repuesto que puedas tener. Incluso los cambiaré por un paquete no reclamado.",
    ["What's so special about the parcels you send me each day?"] = "¿Qué tienen de especial los paquetes que me envías cada día?",
    ["I have a couple of lost property packages in the post office, that you can take off my hands should you collect parcels from me frequently."] = "Tengo un par de paquetes de objetos perdidos en la oficina de correos, que puedes quitarme de las manos si recoges mis paquetes con frecuencia.",
    ["Wow, that sounds great!"] = "¡Vaya, eso suena genial!",
    ["Just check in each day and I'll send any mail your way."] = "Simplemente regístrese cada día y le enviaré cualquier correo.",
    ["What delivery options are there?"] = "¿Qué opciones de entrega existen?",
    ["I can send all parcels to you directly, or alternatively I can have them sent to your bank."] = "Puedo enviarte todos los paquetes directamente o, alternativamente, puedo enviarlos a tu banco.",
    ["Send parcels to me directly."] = "Envíame paquetes directamente.",
    ["I'll send parcels to you directly as my priority."] = "Te enviaré paquetes directamente como mi prioridad.",
    ["Send parcels to my bank."] = "Enviar paquetes a mi banco.",
    ["I'll send parcels to your bank as my priority."] = "Enviaré paquetes a su banco como mi prioridad.",
    ["I don't suppose you've heard any news of my body perchance?"] = "Supongo que no habrás oído ninguna noticia sobre mi cuerpo, ¿acaso?",
    ["Your body?"] = "¿Tu cuerpo?",
    ["Somebody was kind enough to find me one, but..."] = "Alguien tuvo la amabilidad de encontrarme uno, pero...",
    ["I was ambushed whilst delivering post in the wilderness, and I've not seen it since."] = "Me tendieron una emboscada mientras entregaba correo en wilderness y no lo he vuelto a ver desde entonces.",
    ["Maybe you should quit whils you're 'a head'!"] = "¡Tal vez deberías dejarlo mientras seas 'un líder'!",
    ["Ah yes, a parcel was sent to you but it didn't quite manage to get there. Here it is."] = "Ah, sí, te enviaron un paquete pero no logró llegar. Aquí lo tienes.",
    ["What's with the parcels and stamps?"] = "¿Qué pasa con los paquetes y sellos?",
    ["The parcels are from the people of Gielinor to all the adventurers to thank them for all their hard work! I'll try to send you one each day for 30 days, and if you don't have enough space, just come and see me in Burthorpe once you do. If you want more, you'll just have to get out into the world and try doing something. I'm sure some mail will turn up."] = "¡Los paquetes son de la gente de Gielinor para todos los aventureros para agradecerles por todo su arduo trabajo! Intentaré enviarte uno cada día durante 30 días, y si no tienes suficiente espacio, ven a verme a Burthorpe una vez que lo tengas. Si quieres más, tendrás que salir al mundo e intentar hacer algo. Estoy seguro de que aparecerá algún correo.",
    ["What's with your evil twin over there?"] = "¿Qué pasa con tu gemelo malvado de allí?",
    ["Oh, he's not evil, he's just a little slow."] = "Oh, no es malvado, solo es un poco lento.",
    ["I heard that!"] = "¡Escuché eso!",
    ["That is to say, he's my intern. I seem to spend most of my time on Gielinor delivering fanmail, so I'm training my brother to help out."] = "Es decir, es mi pasante. Parece que paso la mayor parte de mi tiempo en Gielinor entregando correo de fans, así que estoy entrenando a mi hermano para que me ayude.",
    ["So we'll get even more parcels?"] = "¿Entonces recibiremos aún más paquetes?",
    ["Yes, though truth be told he still has a lot to learn. He managed to somehow stick the fanmail to the parcels..."] = "Sí, aunque la verdad es que todavía tiene mucho que aprender. Se las arregló de alguna manera para pegar el correo de fans a los paquetes...",
    ["But surely those packages belong to other people?"] = "¿Pero seguramente esos paquetes pertenecen a otras personas?",
    ["My intern, Parcel, puts all the undeliverable mail in the lost property so I'm sure they wouldn't have gotten it anyway."] = "Mi pasante, Parcel, coloca todo el correo que no se puede entregar en la propiedad perdida, así que estoy seguro de que no lo habrían recibido de todos modos.",
    ["*(If no mail is available, and more are available later:)*"] = "*(Si no hay correo disponible y hay más disponibles más adelante:)*",
    ["*(Without space to receive the parcel:)*"] = "*(Sin espacio para recibir el paquete :)*",
    ["I do actually, but you don't seem to have space for it right now."] = "De hecho, sí, pero parece que no tienes espacio para ello en este momento.",
    ["You would have received a parcel from Postie Pete; however, you did not have enough space. Postie Pete will hold onto your parcel for now."] = "Habrías recibido un paquete de Postie Pete; sin embargo, no tenías suficiente espacio. Postie Pete retendrá su paquete por ahora.",
    ["*(With space to receive the parcel:)*"] = "*(Con espacio para recibir el paquete :)*",
    ["*(If all the daily parcels have been delivered:)*"] = "*(Si se han entregado todos los paquetes diarios:)*",
    ["No sorry, that was your last one."] = "No lo siento, ese fue el último.",
    ["The parcels are from the people of Gielinor to all the adventurers to thank them for all their hard work! I'll try to send you one each day for [30 or 26] days, and if you don't have enough space, just come and see me in Burthorpe once you do. If you want more, you'll just have to get out into the world and try doing something. I'm sure some mail will turn up."] = "¡Los paquetes son de la gente de Gielinor para todos los aventureros para agradecerles por todo su arduo trabajo! Intentaré enviarte uno cada día durante los días [30 or 26], y si no tienes suficiente espacio, ven a verme a Burthorpe una vez que lo tengas. Si quieres más, tendrás que salir al mundo e intentar hacer algo. Estoy seguro de que aparecerá algún correo.",
    ["I'm always sending letters, so I'm interested in any spare postage stamps you may have. I'll even exchange them for an unclaimed parcel. Here, have a look at this, it has more information for you."] = "Siempre envío cartas, así que me interesan los sellos postales de repuesto que puedas tener. Incluso los cambiaré por un paquete no reclamado. Mira esto, tiene más información para ti.",
    ["*(Parcels from the Hedge interface opens.)*"] = "*(Se abren los paquetes desde la interfaz Hedge.)*",
    ["That is to say, he's my intern still. My brother has been helping me out with the postal service. He managed to solve the fan mail issue last time, so I've taken on some of this new ideas."] = "Es decir, todavía es mi pasante. Mi hermano me ha estado ayudando con el servicio postal. Se las arregló para resolver el problema del correo de los fans la última vez, así que he adoptado algunas de estas nuevas ideas.",
    ["What sort of ideas?"] = "¿Qué tipo de ideas?",
    ["We've installed a delivery and collection system where you can exchange your stamps for items that were previously obtainable in those parcels of ours. I'll also attempt to deliver any lost property you've earned when I deliver your daily parcel."] = "Hemos instalado un sistema de entrega y recogida donde podrás cambiar tus sellos por artículos que anteriormente se podían obtener en esos paquetes nuestros. También intentaré entregar cualquier objeto perdido que haya ganado cuando entregue su paquete diario.",
    ["**SELECT AN OPTION**"] = "**SELECCIONA UNA OPCIÓN**",
    ["What are you two up to?"] = "¿Qué están haciendo ustedes dos?",
    ["Player! It's wonderful to see you. I could do with your help, actually. I'm right in the middle of a total disaster."] = "¡Player! Es maravilloso verte. De hecho, me vendría bien tu ayuda. Estoy justo en medio de un desastre total.",
    ["You seem happy for a skull in that position."] = "Pareces feliz por tener una calavera en esa posición.",
    ["THE TINSEL IS INSIDE THE TREE."] = "EL OROPEL ESTÁ DENTRO DEL ÁRBOL.",
    ["THE SNAPLESS CRACKER MAKES NO SOUND."] = "EL CRACKER SNAPLESS NO HACE SONIDO.",
    ["THE SNOWFLAKES HAVE POINTY EARS."] = "LOS COPOS DE NIEVE TIENEN OREJAS PUNTADAS.",
    ["The Head Elf is watching me and I don't want here to know there is a problem."] = "El Elfo Jefe me está mirando y no quiero que sepa que hay un problema.",
    ["*Clack clack. Click clack clack. Clack clack. Click click click. Click.*"] = "*Clac, clac. Haz clic, clac, clac. Clac clac. Haga clic, haga clic, haga clic. Haga clic.*",
    ["*(Translates from Morse Code to \"IDIOT\")*"] = "*(Se traduce del código Morse a \"IDIOTA\")*",
    ["I... see. So what is the problem?"] = "Ya... veo. Entonces ¿cuál es el problema?",
    ["Pete turns his skull to hide his expression from the Head Elf."] = "Pete gira su cráneo para ocultar su expresión al jefe de los elfos.",
    ["Santa asked for my help with the wrapping this year, he has busy helping the Queen of Snow plan her party."] = "Santa me pidió ayuda con el envoltorio este año, está ocupado ayudando a Queen of Snow a planificar su fiesta.",
    ["I offered my brother's services, and he has diligently wrapped all of the presents we were provided."] = "Ofrecí los servicios de mi hermano y él envolvió diligentemente todos los regalos que nos dieron.",
    ["That sounds like a big help. Well done, Petes!"] = "Eso parece una gran ayuda. ¡Bien hecho, Petes!",
    ["Unfortunately, Pete appears to have had something of a lapse of judgement."] = "Desafortunadamente, Pete parece haber cometido un error de juicio.",
    ["I can just about understand why you wrapped them all in parcel paper, but why did you wrap all your normal parcels in wrapping paper?"] = "Puedo entender por qué los envolviste todos en papel de regalo, pero ¿por qué envolviste todos tus paquetes normales en papel de regalo?",
    ["Can't you just ask Santa for some more wrapping paper?"] = "¿No puedes simplemente pedirle a Santa más papel de regalo?",
    ["And sully the name of Pete? Incur the wrath of the Head Elf? I'd rather be a skullball."] = "¿Y mancillar el nombre de Pete? ¿Incurrir en la ira del Jefe Elfo? Prefiero ser una bola de calavera.",
    ["Besides, I'll only need to subtly ask twelve million three hundred and forty three more adventurers and passers by to hand over some wrapping paper before we have enough to re-wrap everything."] = "Además, sólo tendré que pedirle sutilmente a doce millones trescientos cuarenta y tres aventureros y transeúntes más que me entreguen algo de papel de regalo antes de que tengamos suficiente para volver a envolver todo.",
    ["Pete returns to his original position."] = "Pete vuelve a su posición original.",
    ["Anyway, glad I finally got that letter to you, Player!"] = "De todos modos, ¡me alegro de haberte enviado finalmente esa carta, Player!",
    ["Pete gives you a sly wink."] = "Pete te guiña un ojo con picardía.",
    ["Help? Everything is fine, Player. We're well ahead of schedule."] = "¿Ayuda? Todo está bien, Player. Estamos muy por delante de lo previsto.",
    ["Oh, Player... We are SO behind schedule."] = "Oh, Player... Estamos TAN retrasados.",
    ["Wrapping paper, we need more wrapping paper!"] = "Papel de regalo, ¡necesitamos más papel de regalo!",
    ["Where can I find wrapping paper?"] = "¿Dónde puedo encontrar papel de regalo?",
    ["The way Pete has given it out you can find it just about anywhere at any time..."] = "De la forma en que Pete lo ha distribuido, puedes encontrarlo prácticamente en cualquier lugar y en cualquier momento...",
    ["*Clack clack clack. Click click click. Clack click clack. Clack click clack. Click Clack click click.*"] = "*Clac clac clac. Haga clic, haga clic, haga clic. Clac, clic, clac. Clac, clic, clac. Haga clic, clac, haga clic, haga clic.*",
    ["*(Translates from Morse Code to \"SORRY\")*"] = "*(Se traduce del código Morse a \"LO SIENTO\")*",
    ["We can spare a few presents here and there. I'll give you one for every 200 Christmas wrapping paper you bring me."] = "Podemos regalar algunos regalos aquí y allá. Te daré uno por cada 200 papeles de regalo navideños que me traigas.",
    ["What is inside?"] = "¿Qué hay dentro?",
    ["This and that. Honestly, with how rushed we are I've been wrapping anything I can find. There are even some green hats in there, I think they sent us a shipment by mistake."] = "Esto y aquello. Honestamente, con lo apurados que estamos, he estado envolviendo todo lo que puedo encontrar. Incluso hay algunos sombreros verdes ahí, creo que nos enviaron un envío por error.",
    ["Lovely to see you as always, Player!"] = "¡Encantado de verte como siempre, Player!",
    ["Exchange wrapping paper."] = "Cambie el papel de regalo.",
    ["Show me the colour of your paper, Player."] = "Muéstrame el color de tu papel, Player.",
    ["You don't have any Christmas wrapping paper for me."] = "No tienes papel de regalo navideño para mí.",
    ["The event is over now, but you can still trade in any paper you have until 17th January!"] = "¡El evento ya terminó, pero aún puedes canjear cualquier papel que tengas hasta el 17 de enero!",
    ["**HAND IN WRAPPING PAPER?**"] = "**¿ENTERAR PAPEL DE ENVOLTURA?**",
    ["It's wonderful to see you Player."] = "Es maravilloso verte Player.",
    ["Pete checks that the Head Elf is distracted by his dulcet tones."] = "Pete comprueba que el elfo principal está distraído por sus dulces tonos .",
    ["I could do with your help, actually. I'm right in the middle of another total disaster."] = "En realidad, me vendría bien tu ayuda. Estoy justo en medio de otro desastre total.",
    ["My brother and I were again helping Santa with wrapping this year, to avoid the mistakes of last year, we ordered some awfully garish paper to make sure we knew what boxes are presents and what are parcels."] = "Mi hermano y yo volvimos a ayudar a Papá Noel a envolver este año. Para evitar los errores del año pasado, pedimos un papel terriblemente llamativo para asegurarnos de saber qué cajas son regalos y cuáles son paquetes.",
    ["However, we foolishly decided to store the paper in a singular wicker container. In our workshop where we've also been tinkering with festive dyes."] = "Sin embargo, decidimos tontamente guardar el papel en un recipiente de mimbre singular. En nuestro taller donde también hemos estado jugando con el festivo dyes.",
    ["But, our construction skills are not fantastic, due to the lack of appendages. our workstation collapsed! Spilling dye all over the paper!"] = "Pero nuestras habilidades de construcción no son fantásticas debido a la falta de apéndices. ¡nuestra estación de trabajo colapsó! ¡Derramando dye por todo el papel!",
    ["Which admittedly did improve the appearance of the paper, but the consistency was ruined, making it unusable."] = "Lo cual ciertamente mejoró la apariencia del papel, pero la consistencia se arruinó, haciéndolo inutilizable.",
    ["Well, there's no use crying over split dye."] = "Bueno, no sirve de nada llorar por la separación de dye.",
    ["Too soon Player."] = "Demasiado pronto Player.",
    ["Sorry, how can I help?"] = "Lo siento, ¿en qué puedo ayudar?",
    ["Get out there and find any replacement paper for us. We lost a few shipments of paper in an unrelated paper glider competition. So, there's plenty around and you should be able to find some with most of your day to day activities."] = "Sal y busca papel de reemplazo para nosotros. Perdimos algunos envíos de papel en una competencia de planeadores de papel no relacionada. Por lo tanto, hay muchos disponibles y debería poder encontrar algunos en la mayoría de sus actividades diarias.",
    ["We have some spare presents. I can reward you with one of these for every 200 paper you bring me."] = "Nos sobran algunos regalos. Puedo recompensarte con uno de estos por cada 200 papeles que me traigas.",
    ["As some extra thanks. I'll have a bonus present you can come and claim off me once every day as well."] = "Como agradecimiento adicional. Tendré un regalo extra que puedes venir y reclamarme una vez al día también.",
    ["I wouldn't be surprised if some bottles of Aurora dye ended up in these presents as we were tidying up too."] = "No me sorprendería que algunas botellas de Aurora dye terminaran en estos regalos mientras estábamos ordenando también.",
    ["If we, by which I mean you, play this right. We should be able to recover this colourful but disastrous situation. While maintaining our reputation as premier parcel posters."] = "Si nosotros, me refiero a usted, hacemos esto bien. Deberíamos poder recuperar esta colorida pero desastrosa situación. Manteniendo nuestra reputación como los principales carteles de paquetes .",
    ["What's in the presents?"] = "¿Qué hay en los regalos?",
    ["I can't give you any presents until you have at least 200 wrapping paper for me."] = "No puedo darte ningún regalo hasta que tengas al menos 200 papeles de regalo para mí.",
    ["You exchange [number] wrapping paper and receive: [number] x [number] x [number] x |color=#EBE0BC}}"] = "Intercambias papel de regalo [número] y recibes: [número] x [número] x [número] x |color=#EBE0BC}}",
    ["Claim daily present."] = "Reclama presente diario.",
    ["You've already claimed today's present."] = "Ya has reclamado el regalo de hoy.",
    ["You've already claimed today's presents."] = "Ya has reclamado los regalos de hoy.",
    ["You don't have enough backpack space for your present."] = "No tienes suficiente espacio backpack para tu regalo.",
    ["Postie Pete gives you 1 x White Christmas Present."] = "Postie Pete te ofrece 1 regalo de Navidad blanco.",
    ["Postie Pete gives you 1 x Blue Christmas Present."] = "Postie Pete te ofrece 1 regalo de Navidad azul.",
    ["Merry Christmas, Player!"] = "¡Feliz Navidad, Player!",
    ["Postie Pete gives you 3 x White Christmas Present."] = "Postie Pete te ofrece 3 regalos de Navidad blancos.",
    ["Be sure to come back tomorrow!"] = "¡Asegúrate de volver mañana!",
    ["This goes to show. You shouldn't put all your gaudy festive paper in one basket."] = "Esto lo demuestra. No deberías poner todos tus papeles festivos llamativos en una sola canasta.",
    ["*Fwoop Fwoop toot. Fwoop fwoop fwoop. Fwoop fwoop fwoop. Fwoop toot toot. Fwoop fwoop fwoop. Fwoop toot. Toot."] = "*Fwoop Fwoop toot. Fwoop, fwoop, fwoop. Fwoop, fwoop, fwoop. Fwoop, tait, tait. Fwoop, fwoop, fwoop. Fwoop pitido. Sonar.",
    ["Please leave."] = "Por favor, vete.",
    ["The event is over now, but you can still trade in any paper you have until the end of 29th January!"] = "¡El evento ya terminó, pero aún puedes canjear cualquier papel que tengas hasta finales del 29 de enero!",
    ["I'm afraid I'm no longer giving out daily presents as the event is now over."] = "Me temo que ya no daré regalos diarios porque el evento ya terminó.",
    ["Great timing, Player, I could really use a hand again!"] = "Excelente momento, Player, ¡me vendría bien una mano otra vez!",
    ["Of course Pete, what did you do this time?"] = "Por supuesto Pete, ¿qué hiciste esta vez?",
    ["What did I do?! Why do you assume -"] = "¡¿Qué hice?! ¿Por qué supones -",
    ["Never mind, no time for that! I've taken on a big job from downstairs, Pete is busy with his own responsibilities, the rest of our family don't really have their head in the the game anymore..."] = "¡No importa, no hay tiempo para eso! He asumido un gran trabajo desde abajo, Pete está ocupado con sus propias responsabilidades, el resto de nuestra familia ya no tiene la cabeza metida en el juego...",
    ["...and I've only gone and lost all of the delivery instructions again!"] = "... ¡y solo volví a perder todas las instrucciones de entrega!",
    ["Oh dear, what happened?"] = "Dios mío, ¿qué pasó?",
    ["Ill wind's back. Took everything. Again. I should really invest in paperweights."] = "El mal viento ha vuelto. Tomó todo. De nuevo. Realmente debería invertir en pisapapeles.",
    ["If I don't complete this order it's my neck on the line!"] = "¡Si no completo este pedido, me juego el cuello!",
    ["I'm sure I can help; what do you need me to do?"] = "Estoy seguro de que puedo ayudar; ¿Qué necesitas que haga?",
    ["That would be brilliant - if you find any last wills in your travels please bring them back to us!"] = "Eso sería genial. Si encuentras alguna última voluntad en tus viajes, ¡tráenosla!",
    ["You lost last wills? Who is this order for, Pete?"] = "¿Perdiste tus últimas voluntades? ¿Para quién es esta orden, Pete?",
    ["Don't worry about it! For every 100 last wills you bring me, I should have something to reward you."] = "¡No te preocupes por eso! Por cada 100 últimas voluntades que me traigas, debería tener algo para recompensarte.",
    ["We already have a surplus of unclaimed belongings, so perhaps I could give you those. I'll even throw in one for free every day as a way of showing my appreciation."] = "Ya tenemos un excedente de pertenencias no reclamadas, así que quizás podría dártelas. Incluso regalaré uno todos los días como forma de mostrar mi agradecimiento.",
    ["Lost parcels turn up from everyone... even Death. No idea what he ordered, but I'm not opening it."] = "Aparecen paquetes perdidos de todos... incluso de la Muerte. No tengo idea de lo que pidió, pero no lo abriré.",
    ["What's in the parcels?"] = "¿Qué hay en los paquetes?",
    ["Exchange last wills."] = "Intercambiar últimas voluntades.",
    ["Claim daily parcel."] = "Reclamar paquete diario.",
    ["Good luck finding those last wills, be sure to come back with any you collect."] = "Buena suerte para encontrar esos últimos testamentos. Asegúrate de volver con los que recopiles.",
    ["Will do. See you later Pete."] = "Lo haré. Hasta luego Pete.",
    ["The event is over now, but you can still trade in any last wills. You have until the end of the 16th November!"] = "El evento ya terminó, pero aún puedes intercambiar tus últimas voluntades. ¡Tienes hasta finales del 16 de noviembre!",
    ["Hand in last wills?"] = "¿Entregar últimas voluntades?",
    ["I can't give you any parcels until you have at least 100 last wills for me."] = "No puedo darte ningún paquete hasta que tengas al menos 100 últimos testamentos para mí.",
    ["You need at least 5 backpack spaces for me to give you your parcels."] = "Necesitas al menos 5 espacios backpack para que te entregue tus paquetes.",
    ["You exchange [number] last wills and receive: [number] x [number] x [number] x |colour=#EBE0BC|shadow=no}}"] = "Intercambias [número] últimos testamentos y recibes: [número] x [número] x [número] x |color=#EBE0BC|shadow=no}}",
    ["Open the belongings for loot, and a chance at special prizes!"] = "¡Abre las pertenencias para obtener botín y tener la oportunidad de ganar premios especiales!",
    ["INFO"] = "INFORMACIÓN",
    ["Contains 3 of the following rewards."] = "Contiene 3 de las siguientes recompensas.",
    ["BACK"] = "VOLVER",
    ["Cotnains a Huge lamp, Bonus XP star (huge), and one of these"] = "Cotnains una lámpara enorme, una estrella Bonus XP (enorme) y uno de estos",
    ["Contains 1 of the following rewards."] = "Contiene 1 de las siguientes recompensas.",
    ["I've already given you a reward today, I have nothing else for you."] = "Ya te di una recompensa hoy, no tengo nada más para ti.",
    ["You don't have enough backpack space for the reward I have for you."] = "No tienes suficiente espacio backpack para la recompensa que tengo para ti.",
    ["[Postie Pete gives you 1 x Small Forgotten Belongings.]"] = "[Postie Pete te regala 1 x Pequeñas pertenencias olvidadas.]",
    ["[Postie Pete gives you 1 x Medium Forgotten Belongings.]"] = "[Postie Pete te ofrece 1 x Pertenencias olvidadas medianas.]",
    ["[Postie Pete gives you 1 x Large Forgotten Belongings.]"] = "[Postie Pete te ofrece 1 x Pertenencias olvidadas grandes.]",
    ["I'm afraid I've got no more daily rewards to give you - I can still exchange any last wills you have, though."] = "Me temo que ya no tengo más recompensas diarias que darte. Sin embargo, todavía puedo intercambiar tus últimas voluntades.",
    ["Hi cat!"] = "¡Hola gato!",
    ["Miaooow!"] = "¡Miaooow!",
    ["What are you doing?"] = "¿Qué estás haciendo?",
    ["I think I'll go hunting soon, there's a warehouse with some rats in it nearby."] = "Creo que iré a cazar pronto, hay un almacén cerca con algunas ratas.",
    ["Happy hunting."] = "Feliz caza.",
    ["Hello Player."] = "Hola Player.",
    ["How are you feeling now?"] = "¿Cómo te sientes ahora?",
    ["Still a bit below purrrr. Thank you for fetching the medicine for me."] = "Todavía un poco por debajo del ronroneo. Gracias por traerme la medicina.",
    ["No problem, I hope you get better soon."] = "No hay problema, espero que te mejores pronto.",
    ["You don't have a sapling planted in that patch. Plant one and I might agree to look after it for you."] = "No tienes ni un retoño plantado en esa parcela. Plante uno y tal vez acepte cuidarlo por usted.",
    ["Alright, but it's not going to be cheap! I want [3/5] monkey nuts, a monkey bar and a ground-up Suqah tooth."] = "Muy bien, ¡pero no será barato! Quiero nueces de mono [3/5], una barra y un diente de Suqah molido.",
    ["Thanks, maybe another time."] = "Gracias, tal vez en otro momento.",
    ["That'll do nicely, [sir/madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [sir/madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
    ["The gardener is now looking after the patch for you."] = "El jardinero ahora se ocupará del parche por usted.",
    ["Yes, and don't ask again."] = "Sí, y no vuelvas a preguntar.",
    ["I don't know what you're talking about - I'm already looking after that patch for you."] = "No sé de qué estás hablando. Ya estoy cuidando ese parche por ti.",
    ["Oh sorry, I forgot."] = "Oh, lo siento, lo olvidé.",
    ["That patch is already fully grown. I don't know what you want me to do with it."] = "Ese parche ya está completamente desarrollado. No sé qué quieres que haga con él.",
    ["Would you look after my crops for me?"] = "¿Cuidarías mis cultivos por mí?",
    ["You don't have a sapling planted in that patch. Plant something and I might agree to look after it for you."] = "No tienes ni un retoño plantado en esa parcela. Planta algo y tal vez acepte cuidarlo por ti.",
    ["That patch is already fully grown! I don't know what you want me to do with it!"] = "¡Ese parche ya está completamente desarrollado! ¡No sé qué quieres que haga con él!",
    ["First, I want [3/5] monkey nuts, a monkey bar and a ground up suqah tooth."] = "Primero, quiero nueces de mono [3/5], una barra de mono y un diente de suqah molido.",
    ["Where can I get all that stuff?"] = "¿Dónde puedo conseguir todo eso?",
    ["You can get a Suqah tooth from a Suqah's mouth, of course. Then you grind it up with a pestle and mortar. As for the monkey bar and nuts, try looking somewhere where there are lots of monkeys!"] = "Puedes obtener un diente de Suqah de la boca de una Suqah, por supuesto. Luego lo mueles con un mortero. En cuanto a la barra de monos y las nueces, ¡intenta buscar en algún lugar donde haya muchos monos!",
    ["Alright, I'll pay."] = "Muy bien, pagaré.",
    ["I'm afraid I don't have enough of those at the moment."] = "Me temo que no tengo suficientes en este momento.",
    ["Well, I'm not wasting my time for free."] = "Bueno, no voy a perder el tiempo gratis.",
    ["What the heck do you want with THAT?"] = "¿Qué diablos quieres con ESO?",
    ["They're for eating, silly! What else can you do with a monkey bar?"] = "¡Son para comer, tonto! ¿Qué más puedes hacer con una barra de mono?",
    ["And the Suqah tooth?"] = "¿Y el diente de Suqah?",
    ["Lots of gnomes like a bit of ground-up Suqah tooth, just don't tell anyone about this, okay?"] = "A muchos gnomos les gusta un poco de diente de Suqah molido, pero no le cuentes a nadie sobre esto, ¿de acuerdo?",
    ["Forget I asked."] = "Olvida que pregunté.",
    ["Maybe some other time."] = "Quizás en otro momento.",
    ["Can you stop weeding my farming patches please."] = "¿Puedes dejar de desherbar mis parcelas de cultivo, por favor?",
    ["Sure, I'll stop weeding them now."] = "Claro, dejaré de eliminarlos ahora.",
    ["Can you keep my farming patches weeded please?"] = "¿Puedes mantener mis parcelas de cultivo desyerbadas, por favor?",
    ["That shouldn't be a problem, Martin said I should give you special attention for your help with the fairies! Be sure to clear your allotment though as I don't want to interupt their growth!"] = "Eso no debería ser un problema, ¡Martin dijo que debería darte especial atención por tu ayuda con las hadas! ¡Asegúrate de limpiar tu asignación ya que no quiero interrumpir su crecimiento!",
    ["Can you sell me something?"] = "¿Puedes venderme algo?",
    ["That depends on whether I have it to sell. What is it that you're looking for?"] = "Eso depende de si lo tengo para vender. ¿Qué es lo que estás buscando?",
    ["That's all, thanks."] = "Eso es todo, gracias.",
    ["Some plant cure."] = "Alguna cura vegetal.",
    ["Plant cure, eh? I might have some put aside for myself. Tell you what, I'll sell you some plant cure for 25 gp if you like."] = "Cura vegetal, ¿eh? Quizás tenga algo reservado para mí. Te diré una cosa, te venderé una cura vegetal por 25 po si quieres.",
    ["I don't have enough money for that, I'm afraid."] = "Me temo que no tengo suficiente dinero para eso.",
    ["Yes, that sounds like a fair price."] = "Sí, parece un precio justo.",
    ["No thanks, I can get that much cheaper elsewhere."] = "No, gracias, puedo conseguirlo mucho más barato en otro sitio.",
    ["A bucket of compost."] = "Un balde de abono.",
    ["A bucket of compost, eh? I might have one spare... tell you what, I'll sell it to you for 35 gp if you like."] = "Un balde de abono, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 35 po si quieres.",
    ["A rake."] = "Un rastrillo.",
    ["A rake, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un rastrillo, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["(See more items)"] = "(Ver más artículos)",
    ["A watering can"] = "una regadera",
    ["A watering can."] = "Una regadera.",
    ["A watering can, eh? I might have one spare... tell you what, I'll sell it to you for 25 gp if you like."] = "Una regadera, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 25 po si quieres.",
    ["A gardening trowel"] = "Una paleta de jardinería",
    ["A gardening trowel."] = "Una paleta de jardinería.",
    ["A gardening trowel, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Una paleta de jardín, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["A seed dibber"] = "Un zambullidor de semillas",
    ["A seed dibber."] = "Un arrancador de semillas.",
    ["A seed dibber, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un zambullidor de semillas, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["(See previous items)"] = "(Ver artículos anteriores)",
    ["Forget it."] = "Olvídalo.",
    ["Forget it, you don't have anything I need."] = "Olvídalo, no tienes nada que necesite.",
    ["That looks like something that you can make normal compost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of compost."] = "Parece algo con lo que se puede hacer abono normal. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de abono.",
    ["That looks like something that you can make supercompost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of supercompost."] = "Parece algo con lo que se puede hacer supercompost. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de supercompost.",
    ["Can I help you?"] = "¿Puedo ayudarle?",
    ["What can I do here?"] = "¿Qué puedo hacer aquí?",
    ["**Prawnbroker: **Every time you catch a golden fish egg, you get a prawn point. You can trade prawn points for prawn perks right here! You can also get prawn points from prawn balls. You'll get a prawn perk once you collect 1, 20, 100 and 200 prawn balls in total. After handing in a prawn point, I'll give you a choice of prawn perks. These range from baitless fishing to floating shark pets. Some perks are locked behind others. You'll have to purchase all of the perks in one tier before you can access the perks in the next tier."] = "**Prawnbroker: **Cada vez que atrapas un huevo de pez dorado, obtienes un punto de gamba. ¡Puedes canjear puntos de gambas por ventajas de gambas aquí mismo! También puedes conseguir puntos de gamba con las bolas de gamba. Obtendrás un beneficio de gambas una vez que recolectes 1, 20, 100 y 200 bolas de gambas en total. Después de entregar un punto de gambas, te daré la opción de elegir entre los beneficios de las gambas. Estos van desde la pesca sin cebo hasta las mascotas flotantes de tiburones. Algunas ventajas están bloqueadas detrás de otras. Tendrás que comprar todos los beneficios de un nivel antes de poder acceder a los beneficios del siguiente nivel.",
    ["*In case of ironman:* If you have any prawn crackers you can't use, pull them with me and I'll reward you with the appropriate price."] = "*En caso de ironman:* Si tienes galletas de gambas que no puedas usar, llévalas conmigo y te recompensaré con el precio correspondiente.",
    ["I would like to select my perks."] = "Me gustaría seleccionar mis ventajas.",
    ["I would like to change some settings."] = "Me gustaría cambiar algunas configuraciones.",
    ["What do you want to change?"] = "¿Qué quieres cambiar?",
    ["Settings"] = "Configuración",
    ["Fishing Animation"] = "Animación Fishing",
    ["I want to turn off my prestige barehanded fishing."] = "Quiero desactivar mi prestigio de pesca con las manos desnudas.",
    ["Fish caught using your bare hands will look like their normal selves."] = "Los peces capturados con las manos desnudas tendrán un aspecto normal.",
    ["I want to catch silver fish while barehanded fishing."] = "Quiero pescar peces plateados mientras pesco con las manos desnudas.",
    ["Fish caught using your bare hands will have a silver sheen."] = "El pescado capturado con las manos desnudas tendrá un brillo plateado.",
    ["I want to catch gold fish while barehanded fishing."] = "Quiero pescar peces dorados mientras pesco con las manos desnudas.",
    ["You now have a Midas touch while catching fish barehanded."] = "Ahora tienes un toque de Midas mientras pescas con las manos desnudas.",
    ["Cancel."] = "Cancelar.",
    ["Back"] = "Atrás",
    ["I would like to claim my bonus Prawn Balls please!"] = "¡Me gustaría reclamar mis bolas de gambas extra, por favor!",
    ["*If the player is not yet eligible to claim bonus prawn balls:*"] = "*Si el player aún no es elegible para reclamar bolas de gambas adicionales:*",
    ["Come back to me when you have mastered fishing. Then I will honour your achievement with 50 prawn balls."] = "Vuelve conmigo cuando domines la pesca. Entonces honraré tu logro con 50 bolas de gambas.",
    ["*If the player is level 99 Fishing:*"] = "*Si el player es el nivel 99 Fishing:*",
    ["You're something of a celebrity in prawn circles. To recognise your mastery of the sea, I offer you 50 prawn balls."] = "Eres una especie de celebridad en los círculos de gambas. Para reconocer tu dominio del mar, te ofrezco 50 bolas de gambas.",
    ["You have <number> prawn points to spend."] = "Tienes <number> puntos de gambas para gastar.",
    ["*If the player is eligible for at least a tier-1 prawn perk:*"] = "*Si el player es elegible para al menos un beneficio de gambas de nivel 1:*",
    ["Select a tier-1 prawn perk"] = "Seleccione un beneficio de gambas de nivel 1",
    ["Gain prawn balls more frequently."] = "Gana bolitas de gambas con más frecuencia.",
    ["You can now gain prawn balls at a greater rate."] = "Ahora puedes ganar bolas de gambas a un ritmo mayor.",
    ["Rod-fish without using fishing bait."] = "Pescar con caña sin utilizar cebo de pesca.",
    ["You no longer need bait while rod fishing."] = "Ya no necesitas cebo mientras pescas con caña.",
    ["Gain a landmark of your choice for your aquarium."] = "Obtenga un punto de referencia de su elección para su acuario.",
    ["*If the player does not yet own all landmarks:*"] = "*Si el player aún no posee todos los puntos de referencia:*",
    ["*(Select an option interface opens)*"] = "*(Selecciona una opción para abrir la interfaz)*",
    ["You are now able to place the [Landmark name] decoration in your aquarium!"] = "¡Ya puedes colocar la decoración [Landmark name] en tu acuario!",
    ["You already have all the landmarks. Have some prawn balls instead."] = "Ya tienes todos los puntos de referencia. En su lugar, come unas bolitas de gambas.",
    ["Gain 10 prawn pennies."] = "Gana 10 centavos de gambas.",
    ["You are handed 10 prawn pennies."] = "Te entregan 10 centavos de gambas.",
    ["*Upon unlocking the ability to access the next tier of Prawn Perks:*"] = "*Al desbloquear la capacidad de acceder al siguiente nivel de Prawn Perks:*",
    ["You are handed a golden mystery egg. You now have access to the next tier of perks."] = "Te entregan un huevo misterioso dorado. Ahora tienes acceso al siguiente nivel de ventajas.",
    ["*If the player is eligible for a tier-3 prawn perk:*"] = "*Si el player es elegible para un beneficio de gambas de nivel 3:*",
    ["Select a tier-3 prawn perk"] = "Seleccione un beneficio de gambas de nivel 3",
    ["You now gain prawn balls at an even greater rate!"] = "¡Ahora ganas bolas de gambas a un ritmo aún mayor!",
    ["Fly-fish without using feathers."] = "Pesca con mosca sin utilizar plumas.",
    ["You can now fly fish without feathers. You can use the prawnbroker to swap between using stripy and normal feathers."] = "Ahora puedes pescar con mosca sin plumas. Puedes utilizar el corredor de gambas para alternar entre el uso de plumas rayadas y normales.",
    ["Prawn pennies and prawn pounds last twice as long."] = "Los centavos de gambas y las libras de gambas duran el doble.",
    ["Prawn pennies and pounds now last twice as long."] = "Los centavos y las libras de gambas ahora duran el doble.",
    ["Gain three diving suit cosmetic overrides."] = "Obtén tres anulaciones cosméticas del traje de buceo.",
    ["You can now use diving suits as a cosmetic override. They can be accessed from the Customisation interface. Or so I hear."] = "Ahora puedes usar trajes de buceo como anulación cosmética. Se puede acceder a ellos desde la interfaz de Personalización. O eso he oído.",
    ["*If the player is eligible for a tier-5 prawn perk:*"] = "*Si el player es elegible para un beneficio de gambas de nivel 5:*",
    ["Select a tier-5 prawn perk"] = "Seleccione un beneficio de gambas de nivel 5",
    ["You will now gain prawn balls more frequently!"] = "¡Ahora ganarás bolas de gambas con más frecuencia!",
    ["Barbarian-fish without using bait or feathers."] = "Pez bárbaro sin utilizar cebo ni plumas.",
    ["You no longer need feathers or bait while barbarian fishing!"] = "¡Ya no necesitas plumas ni cebo para pescar bárbaros!",
    ["Gain a great white shark pet and a great white shark for your aquarium."] = "Consigue un gran tiburón blanco como mascota y un gran tiburón blanco para tu acuario.",
    ["You have unlocked the great white shark for your aquarium and as a pet! Access your pet from the Customisations interface."] = "¡Has desbloqueado el gran tiburón blanco para tu acuario y como mascota! Accede a tu mascota desde la interfaz de Personalizaciones.",
    ["Catch great white shark from shark fishing spots."] = "Capture un gran tiburón blanco en los lugares de pesca de tiburones.",
    ["You have unlocked the ability to catch great white sharks from shark fishing spots!"] = "¡Has desbloqueado la capacidad de capturar grandes tiburones blancos en lugares de pesca de tiburones!",
    ["*First time after purchasing all perks:*"] = "*Primera vez después de comprar todos los beneficios:*",
    ["Congratulations! You have collected all the perks! You can now use raw great white shark to make sushi when combined with kelp or seaweed!"] = "¡Felicitaciones! ¡Has conseguido todos los beneficios! ¡Ahora puedes usar gran tiburón blanco crudo para hacer sushi combinado con algas marinas!",
    ["*Subsequent times after purchasing all perks:*"] = "*Tiempos posteriores después de comprar todos los beneficios:*",
    ["You have already unlocked all available perks!"] = "¡Ya has desbloqueado todos los beneficios disponibles!",
    ["You do not have any prawn points to spend."] = "No tienes puntos de gambas para gastar.",
    ["[This isn't your prawnbroker. Visit your own aquarium to unlock Prawn Perks.]"] = "[Este no es tu corredor de gambas. Visita tu propio acuario para desbloquear Prawn Perks.]",
    ["Oh hello there my"] = "Oh, hola, mi",
    ["bubbly little beetroot!"] = "¡pequeña remolacha burbujeante!",
    ["delicious dairy-free doughnut!"] = "¡Deliciosa dona sin lácteos!",
    ["fermented fennel sandwich!"] = "¡sándwich de hinojo fermentado!",
    ["marvelously marinaded little chicken!"] = "¡Pollito maravillosamente marinado!",
    ["most tender slab of rex meat!"] = "¡El trozo de carne de rex más tierno!",
    ["scrumptious sun-blushed tomato!"] = "¡Un delicioso tomate sonrojado por el sol!",
    ["spicy little chilli flake!"] = "¡Pequeños copos de chile picantes!",
    ["succulent salted sausage!"] = "¡Suculenta salchicha salada!",
    ["sweet little artichoke!"] = "dulce alcachofa!",
    ["tasty little turnip!"] = "¡nabo sabroso!",
    ["Welcome to our little plot of land on this weird little island. My granddaughter has roped these old bones into helping expand the Potterington brand to all the corners of the agricultural world. So here I am, sunning my shrivelled legs on this tropical paradise filled with bloody great death lizards. Could be worse. I used to live in Draynor. That's a right miserable place I can tell you. So, you ready to help expand our farming enterprise?"] = "Bienvenido a nuestro pequeño terreno en esta pequeña y extraña isla. Mi nieta ha unido estos viejos huesos para ayudar a expandir la marca Potterington a todos los rincones del mundo agrícola. Así que aquí estoy, tomando el sol con mis piernas arrugadas en este paraíso tropical lleno de malditos lagartos mortales. Podría ser peor. Solía ​​vivir en Draynor. Ese es un lugar realmente miserable, te lo puedo decir. Entonces, ¿estás listo para ayudar a expandir nuestra empresa agrícola?",
    ["Oh me dear? Why there's not much to know really. I'm Great Great Granny Potterington, Petunia's great grandmother."] = "¿Oh, querido? Por qué no hay mucho que saber realmente. Soy Bisabuela Granny Potterington, la bisabuela de Petunia.",
    ["Come out of retirement to help my great granddaughter manage this new farming enterprise."] = "Salí de mi jubilación para ayudar a mi bisnieta a administrar esta nueva empresa agrícola.",
    ["Wait? You're granny's great grandmother?"] = "¿Esperar? ¿Eres la bisabuela de la abuela?",
    ["Oh yes dear. I was a grandmother when Granny was just a wee young thing."] = "Oh, sí, querido. Yo era abuela cuando la abuela era muy pequeña.",
    ["Oh dearie me dearie, you never ask a lady her age. It's terribly rude."] = "Oh, cariño, nunca le preguntas a una dama su edad. Es terriblemente grosero.",
    ["But I'll tell you, I'm older than my teeth and younger than I feel. He he he."] = "Pero te diré que soy más viejo que mis dientes y más joven de lo que me siento. Je je je.",
    ["I've been living the last few years in Draynor. Nice little village full of thoroughly miserable people."] = "He estado viviendo los últimos años en Draynor. Bonito y pequeño pueblo lleno de gente completamente miserable.",
    ["So when my great granddaughter offered me the opportunity to visit this tropical paradise, why I had to accept."] = "Entonces, cuando mi bisnieta me ofreció la oportunidad de visitar este paraíso tropical, tuve que aceptar.",
    ["Like my great granddaughter I have handled a few marrows and potatoes. So I know what I'm doing here on this island."] = "Al igual que mi bisnieta, he manipulado algunos calabacines y patatas. Entonces sé lo que estoy haciendo aquí en esta isla.",
    ["This farm is a unique environment, it's not suitable for your standard livestock."] = "Esta granja es un entorno único, no es adecuado para su ganado estándar.",
    ["Instead this is the perfect place to raise those giant lizards that you see wandering round the island."] = "En cambio, este es el lugar perfecto para criar esos lagartos gigantes que ves deambulando por la isla.",
    ["I know they might look scary, but get some good grub in them and you'll find them quite manageable dearie."] = "Sé que pueden dar miedo, pero si les das una buena comida, los encontrarás bastante manejables, querida.",
    ["You'll need to purchase the deeds from the farmer's market and then build the pens yourself using the resources from the island."] = "Tendrás que comprar las escrituras en el mercado de agricultores y luego construir los corrales tú mismo utilizando los recursos de la isla.",
    ["After that you'll be good to go."] = "Después de eso, estarás listo para comenzar.",
    ["How do I get animals?"] = "¿Cómo consigo animales?",
    ["Well some animals you can get from me. I've got me a few frogs and salamanders tucked away for a modest fee."] = "Bueno, algunos animales los puedes conseguir de mí. Tengo algunas ranas y salamandras guardadas por un módico precio.",
    ["For your jadinkos you'll need to get some hunting going."] = "Para tus jadinkos necesitarás empezar a cazar.",
    ["As for the biggest beasts, you'll either need to get on with murdering some giant lizards, or you can sometimes pick some up whilst hunting them."] = "En cuanto a las bestias más grandes, tendrás que seguir asesinando algunos lagartos gigantes o, a veces, podrás recoger algunos mientras los cazas.",
    ["Of course, you can also trade any of them with your fellow farmers. The Grand Exchange won't let us trade animals on it, but you can trade with each other directly."] = "Por supuesto, también puedes intercambiar cualquiera de ellos con tus compañeros agricultores. El Grand Exchange no nos permitirá intercambiar animales en él, pero podéis comerciar entre vosotros directamente.",
    ["How do I raise animals?"] = "¿Cómo crío animales?",
    ["To raise an animal, you first need to make sure you've checked it over."] = "Para criar un animal, primero debes asegurarte de haberlo revisado.",
    ["An unchecked animal could have all manner of diseases, ticks, parasites or curses attached to it and you don't want that."] = "Un animal no controlado podría tener todo tipo de enfermedades, garrapatas, parásitos o maldiciones y tú no quieres eso.",
    ["Then you just need to use the animal on an appropriately sized paddock. Small animals go in the small pen, large in the large, etc."] = "Entonces solo necesitas usar el animal en un prado del tamaño adecuado. Los animales pequeños van en el corral pequeño, los grandes en el grande, etc.",
    ["You can't raise different animals in the same paddock either as they tend to fight."] = "Tampoco puedes criar diferentes animales en el mismo prado, ya que tienden a pelear.",
    ["You'll also need to feed your animals. This is just a simple case of making sure you've put the right sort of food in the feeding trough for the animal in that paddock."] = "También necesitarás alimentar a tus animales. Este es solo un caso simple de asegurarse de haber puesto el tipo correcto de comida en el comedero para el animal en ese prado.",
    ["Remember that not all animals will eat all types of food, so make sure you're not trying to feed dragons strawberries or they'll starve."] = "Recuerda que no todos los animales comen todo tipo de alimentos, así que asegúrate de no intentar alimentar a los dragones con fresas o morirán de hambre.",
    ["A starving animal will lose happiness and health, increasing the chance of it becoming sick and reducing the weight, speed and attractiveness potential of that animal."] = "Un animal hambriento perderá felicidad y salud, lo que aumentará las posibilidades de que enferme y reducirá el peso, la velocidad y el potencial de atractivo de ese animal.",
    ["If your animal gets diseases you will need to examine it. Look over its symptoms and administer the appropriate treatment to cure it."] = "Si tu animal contrae enfermedades, tendrás que examinarlo. Revisa sus síntomas y administra el tratamiento adecuado para curarlo.",
    ["A diseased animal has lower stats than healthier animals, so it's always worth keeping them healthy."] = "Un animal enfermo tiene estadísticas más bajas que los animales más sanos, por lo que siempre vale la pena mantenerlos sanos.",
    ["Animals are fairly chilled out on the farm, so you don't need to keep a constant eye on them. Just pop back every once in a while to see how they're doing."] = "Los animales están bastante tranquilos en la granja, por lo que no es necesario que los vigiles constantemente. Simplemente regrese de vez en cuando para ver cómo les va.",
    ["How do I breed animals?"] = "¿Cómo crío animales?",
    ["Oh, that's easy. You just need to get two animals of the same species and put them in the breeding pen."] = "Oh, eso es fácil. Sólo necesitas conseguir dos animales de la misma especie y ponerlos en el corral de cría.",
    ["Make sure that they're of sufficient breeding age and that they have food, then just wait..."] = "Asegúrate de que tengan suficiente edad reproductiva y de que tengan comida, luego espera...",
    ["They'll get it together on their own time and eventually you should have a lovely baby animal waiting for you."] = "Lo arreglarán a su propio ritmo y, eventualmente, deberías tener un adorable animalito esperándote.",
    ["Despite claims by today's youth, elder animals are quite capable of breeding. So don't worry if your animals get a bit long in the tooth."] = "A pesar de las afirmaciones de los jóvenes de hoy, los animales mayores son bastante capaces de reproducirse. Así que no te preocupes si a tus animales les crecen un poco los dientes.",
    ["They'll still be quite capable of...doing the job."] = "Seguirán siendo bastante capaces de... hacer el trabajo.",
    ["Animals take time to breed and you'll need to keep them as healthy and happy as possible to get the fastest results."] = "Los animales tardan en reproducirse y tendrás que mantenerlos lo más sanos y felices posible para obtener los resultados más rápidos.",
    ["Also, remember that the breeding pen can only hold 4 animals at a time, so make sure you keep taking the kids out to get new ones in."] = "Además, recuerda que el corral de cría solo puede albergar a 4 animales a la vez, así que asegúrate de sacar a los niños para conseguir otros nuevos.",
    ["What are traits and perks?"] = "¿Qué son los rasgos y las ventajas?",
    ["Traits are little identifiers that indicate how that animal differs from others."] = "Los rasgos son pequeños identificadores que indican en qué se diferencia ese animal de los demás.",
    ["Some traits mean an animal is much happier than others and easy to keep amused."] = "Algunos rasgos significan que un animal es mucho más feliz que otros y es fácil entretenerlo.",
    ["Some traits mean that you can harvest them for more materials."] = "Algunos rasgos significan que puedes cosecharlos para obtener más materiales.",
    ["Some traits may do seemingly nothing at all. Whilst others will do strange things."] = "Algunos rasgos pueden aparentemente no hacer nada en absoluto. Mientras que otros harán cosas raras.",
    ["It's generally always a good thing to try and breed multiple traits into animals as the benefits are cumulative."] = "Generalmente, siempre es bueno intentar reproducir múltiples rasgos en animales, ya que los beneficios son acumulativos.",
    ["And what are perks?"] = "¿Y qué son las ventajas?",
    ["Ah, now for those you first need to buy a farm totem from the farmers' market and attach it to an animal pen."] = "Ah, ahora, para aquellos, primero deben comprar un tótem de granja en el mercado de agricultores y adjuntarlo a un corral para animales.",
    ["Then place an elder animal in that pen to activate that animal's perk. For instance, the perk for rabbits is an increase in all animal breeding chances."] = "Luego, coloca un animal mayor en ese corral para activar su beneficio. Por ejemplo, la ventaja para los conejos es un aumento en todas las posibilidades de reproducción de animales.",
    ["If you place a second elder animal of the same type in the other pen of that size - also with an attached farm totem - you'll make the perk more potent!"] = "Si colocas un segundo animal anciano del mismo tipo en el otro corral de ese tamaño, también con un tótem de granja adjunto, ¡harás que el beneficio sea más potente!",
    ["How can I earn beans?"] = "¿Cómo puedo ganar frijoles?",
    ["Pretty much the only way to earn more beans is to sell on some of the animals you've raised."] = "Prácticamente la única forma de ganar más frijoles es vender algunos de los animales que has criado.",
    ["You'll find buyers showing up on the farm on the beach here quite regularly."] = "Aquí encontrarás compradores que aparecen en la granja en la playa con bastante regularidad.",
    ["Sell 'em the animals they're after, and you'll soon see them beans flowing in."] = "Véndeles los animales que buscan y pronto verás cómo fluyen los frijoles.",
    ["Progress will be slow to start, but once we've built up some reputation and a customer base, you'll have more beans than you know what to do with!"] = "El progreso será lento al comenzar, pero una vez que hayamos construido cierta reputación y una base de clientes, ¡tendrás más frijoles de los que sabrás qué hacer!",
    ["How does selling work?"] = "¿Cómo funciona la venta?",
    ["Listen close, 'cos there's a lot of nuance to making a great sale."] = "Escuche atentamente, porque hay muchos matices para lograr una gran venta.",
    ["First up, a buyer will only have interest in a specific type of animal. Take Myfi, for instance - she'll only ever want to buy rabbits."] = "En primer lugar, un comprador solo tendrá interés en un tipo específico de animal. Tomemos como ejemplo a Myfi: ella sólo querrá comprar conejos.",
    ["Each day they show up, they'll only want up to a specific amount of that animal too. They ain't made of beans, so will be on a budget."] = "Cada día que aparezcan, también querrán una cantidad específica de ese animal. No están hechos de frijoles, por lo que tendrán un presupuesto limitado.",
    ["The best age at which to sell animals is adolescence. You can sell older animals at a slight discount - they may be past their prime, but still hold fair value."] = "La mejor edad para vender animales es la adolescencia. Puede vender animales más viejos con un ligero descuento; es posible que ya hayan pasado su mejor momento, pero aún tienen un valor razonable.",
    ["And while you can sell eggs and babies, you won't get very much for them. That's what people pay us for - to raise them."] = "Y aunque puedes vender huevos y bebés, no obtendrás mucho por ellos. Para eso nos paga la gente: para criarlos.",
    ["Any other useful tips?"] = "¿Algún otro consejo útil?",
    ["Buyers will also have a special request - both a specific breed and specific trait. Match either with any sale and you'll get more beans. Match both and you'll get a nice little bonus on top."] = "Los compradores también tendrán una solicitud especial: tanto una raza específica como un rasgo específico. Combina cualquiera de ellos con cualquier oferta y obtendrás más frijoles. Combina ambos y obtendrás un pequeño bono además.",
    ["That said, they'll overlook the specific breed if you're selling 'em a shiny animal!"] = "Dicho esto, ¡pasarán por alto la raza específica si les vendes un animal brillante!",
    ["For all sales, regardless of any special request, there are certain animal traits can affect bean offers."] = "Para todas las ventas, independientemente de cualquier solicitud especial, hay ciertos rasgos animales que pueden afectar las ofertas de frijoles.",
    ["Anything with the Surly, Nice But Dim or Limited Efficiency traits will sell for fewer beans."] = "Cualquier cosa con los rasgos Hosco, Agradable pero tenue o Eficiencia limitada se venderá por menos granos.",
    ["But anything with the Lucky, Fortunate or Unlucky For Some traits will sell for more beans."] = "Pero cualquier cosa con los rasgos Afortunado, Afortunado o Desafortunado para algunos se venderá por más frijoles.",
    ["It still might be worth selling animals with bad bean traits if it's to a special request. The boost from matching the special request should offset any negatives."] = "Todavía podría valer la pena vender animales con malas características de los frijoles si se trata de un pedido especial. El impulso de cumplir con la solicitud especial debería compensar cualquier aspecto negativo.",
    ["Finally, if you can get hold of one of those fancy farming outfits, you might be able to negotiate better bean prices on EVERY sale! Imagine that..."] = "Finalmente, si puedes conseguir uno de esos elegantes trajes agrícolas, ¡quizás puedas negociar mejores precios de frijoles en CADA venta! Imagínate que...",
    ["Show me the farmers' market?"] = "¿Muéstrame el mercado de agricultores?",
    ["Oh, those little delights are helping expand the Potterington brand, my dear. They'll be smearing Potterington on every field in Gielinor soon enough."] = "Oh, esas pequeñas delicias están ayudando a expandir la marca Potterington, querida. Pronto estarán manchando a Potterington en todos los campos de Gielinor.",
    ["I'm afraid that leaves me none the wiser."] = "Me temo que eso no me hace darme cuenta.",
    ["Brown gold, dearie! The purest artisanal fertiliser, from hand-selected, free-range baby dinosaurs, fed only the finest diet of fibre-rich pulses and grains."] = "¡Oro marrón, querida! El fertilizante artesanal más puro, procedente de crías de dinosaurio criadas en libertad, seleccionadas a mano, alimentado únicamente con la mejor dieta de legumbres y cereales ricos en fibra.",
    ["The mixture is then tested by our faecalchemical experts to ensure maximum crop yield and health."] = "Luego, nuestros expertos en química fecal prueban la mezcla para garantizar el máximo rendimiento y salud del cultivo.",
    ["You've been practicing that patter for a while, I think."] = "Creo que llevas un tiempo practicando ese patrón.",
    ["No need for practice when you are as ripe as this old carambola."] = "No necesitas practicar cuando estás tan maduro como esta vieja carambola.",
    ["Would you be willing to lend a hand with this new venture, my helpful little lima bean?"] = "¿Estarías dispuesto a echar una mano con esta nueva empresa, mi pequeña y útil frijol lima?",
    ["Of course, Granny!"] = "¡Por supuesto, abuela!",
    ["I've been pumping beans into this little offshoot, but can't wiggle all my roots at the same time. So far, no fertiliser has made it back to me."] = "He estado bombeando frijoles a esta pequeña rama, pero no puedo mover todas mis raíces al mismo tiempo. Hasta el momento no me ha llegado ningún fertilizante.",
    ["Galgalar and Ben should be sorting eggs south of here, but I suspect Ben has got himself into mischief. He was on the very south coast of the peninsula last time I checked."] = "Galgalar y Ben deberían estar clasificando huevos al sur de aquí, pero sospecho que Ben se ha metido en alguna travesura. La última vez que revisé estaba en la costa sur de la península.",
    ["There is plenty to do. You should start with Galgalar on the peninsula to the south."] = "Hay mucho que hacer. Deberías comenzar con Galgalar en la península al sur.",
    ["I'll see what I can do."] = "Veré qué puedo hacer.",
    ["Don't forget to bring Granny back some of their valuable new product!"] = "¡No olvides traerle a Granny algunos de sus nuevos y valiosos productos!",
    ["Congratulations! You have completed: 'A Hatching Pair' - After Extinction quest, ask Prehistoric Potterington at the Anachronia dinosaur farm about zygomites."] = "¡Felicitaciones! Has completado: 'Un par de eclosiones': después de la misión Extinción, pregúntale a Prehistoric Potterington en la granja de dinosaurios Anacronia sobre los zigomitas.",
    ["I'm sorry, dearie, I can't hear you over the sound of me not being up to my eyeballs in dino manure."] = "Lo siento, querida, no puedo oírte porque no estoy metido hasta los ojos en estiércol de dinosaurio.",
    ["I haven't heard from Ben in a while. Perhaps you could find and help him? He was on the very south coast of the peninsula last time I checked."] = "Hace tiempo que no sé nada de Ben. ¿Quizás podrías encontrarlo y ayudarlo? La última vez que revisé estaba en la costa sur de la península.",
    ["Unless my old eyes deceive me, Galgalar is not achieving much next to his incubator to the south. Give him a nudge, will you?"] = "A menos que mis viejos ojos me engañen, Galgalar no está logrando mucho al lado de su incubadora al sur. Dale un empujón, ¿quieres?",
    ["I haven't had a whiff of any fertiliser blends coming back from Bill. You can reach him with a touch of that curious tree next to Ben."] = "No he olido ninguna mezcla de fertilizantes procedente de Bill. Podrás alcanzarlo con un toque de ese curioso árbol al lado de Ben.",
    ["I'm sure Salusan has something for you to do. She's doing her best to manage Bill."] = "Estoy seguro de que Salusan tiene algo que hacer. Ella está haciendo todo lo posible para gestionar Bill.",
    ["Nothing has reached me yet, petal, unless you have something to show me?"] = "Aún no me ha llegado nada, pétalo, ¿a menos que tengas algo que mostrarme?",
    ["You show Prehistoric Potterington one of the imbued dinarrows you have made."] = "Le muestras a Prehistoric Potterington uno de los dinarrows imbuidos que has hecho.",
    ["What on Gielinor is that, dear?"] = "¿Qué es eso Gielinor, querida?",
    ["This is an imbued dinarrow. I've created it from various components from your fertiliser farm expansion. They are rocket-powered and imbued with the energy of Elder Gods!"] = "Este es un dinarrow imbuido. Lo he creado a partir de varios componentes de la expansión de su granja de fertilizantes. ¡Están propulsados ​​por cohetes y están imbuidos de la energía de los Dioses Mayores!",
    ["My little cherubs created that, with your help?"] = "¿Mis pequeños querubines crearon eso con tu ayuda?",
    ["Yes, they did."] = "Sí, lo hicieron.",
    ["Well, we've broken into our next market then: Potterington Brand Rocket-Powered Elder God Knitting Needles!"] = "Bueno, entonces hemos entrado en nuestro próximo mercado: ¡las agujas de tejer del Dios anciano impulsadas por cohetes de la marca Potterington!",
    ["Glad you are happy, Granny!"] = "¡Me alegro de que estés feliz, abuela!",
    ["Everything is working thanks to you, dear! I'm happy as a pig in muck!"] = "¡Todo funciona gracias a ti, querida! ¡Estoy feliz como un cerdo en el estiércol!",
    ["If you were any closer, my scrumptious little scrollbearer, you'd be in Granny's lap!"] = "Si estuvieras más cerca, mi pequeño y delicioso portador de pergaminos, ¡estarías en el regazo de la abuela!",
    ["Not that Granny'd mind some young blood to warm these old bones, of course, but it'd be a waste of a good teleport scroll."] = "No es que a la abuela le importe un poco de sangre joven para calentar estos huesos viejos, por supuesto, pero sería un desperdicio de un buen pergamino de teletransporte.",
    ["I think you should ask me about my little zygomites angels before you show me that, my sneaky little salmon."] = "Creo que deberías preguntarme sobre mis angelitos cigomitas antes de mostrarme eso, mi pequeño salmón astuto.",
    ["You show Prehistoric Potterington some of the experimental fertiliser blend."] = "Le muestra a Prehistoric Potterington algo de la mezcla de fertilizantes experimental.",
    ["Is that what it smells like, dearie?"] = "¿Es así como huele, querida?",
    ["Nothing else could smell like this."] = "Nada más podía oler así.",
    ["The smell of success, my little limpwurt. Thank you for all your help."] = "El olor del éxito, mi pequeño limpwurt. Gracias por toda tu ayuda.",
    ["No problem, Granny."] = "No hay problema, abuela.",
    ["As you leave, you cannot help but overhear Potterington mutter to herself."] = "Al salir, no puedes evitar escuchar a Potterington murmurar para sí misma.",
    ["Congratulations, you have completed: 'The Plop Thickens' - Use Potterington Blend #102 Fertiliser or dinosaur 'propellant' on Prehistoric Potterington."] = "Felicitaciones, ha completado: 'The Plop Thicks' - Use el fertilizante Potterington Blend #102 o el 'propulsor' de dinosaurio en Prehistoric Potterington.",
    ["An inspired mix from that young dinosaur rider. That could launch a kebbit to Kethsi."] = "Una mezcla inspirada de ese joven jinete dinosaurio. Eso podría lanzarle un kebbit a Kethsi.",
    ["I haven't had a whiff of any fertilizer blends coming back from Bill. You can reach him with a touch of that curious tree next to Ben."] = "No he olido ninguna mezcla de fertilizantes procedente de Bill. Podrás alcanzarlo con un toque de ese curioso árbol al lado de Ben.",
    ["Goodbye, Granny."] = "Adiós, abuela.",
    ["Goodbye, dearie."] = "Adiós, querida.",
    ["Why? Why my little boy eat dat?"] = "¿Por qué? ¿Por qué mi pequeño come eso?",
    ["I hope he get strong battle name. Maybe he eat cannonball, or axe, or dwarf helmet."] = "Espero que obtenga un nombre de batalla fuerte. Tal vez comió balas de cañón, hachas o cascos de enanos.",
    ["Why he have to eat sparkly crystal?"] = "¿Por qué tiene que comer sparkly crystal?",
    ["Haha! Spark'y crystal!"] = "¡Jaja! ¡Cristal chispeante!",
    ["You laugh now, but someday you be sad."] = "Ahora te ríes, pero algún día estarás triste.",
    ["You not need show me that again! Take pretty flower somewhere else!"] = "¡No necesitas mostrarme eso otra vez! ¡Llévate una bonita flor a otro lugar!",
    ["Where you want us to take you, boss?"] = "¿Adónde quieres que te llevemos, jefe?",
    ["Gaah! Everyone shut up!"] = "¡Gaah! ¡Cállate todo el mundo!",
    ["Yeah! We crush smelly chaos dwarves! Knock down chaos dwarf not-Keldagrim! That good fight!"] = "¡Sí! ¡Aplastamos a los malolientes enanos del caos! ¡Derriba al enano del caos no-Keldagrim! ¡Qué buena pelea!",
    ["So you're allies of Keldagrim now?"] = "¿Entonces ahora sois aliados de Keldagrim?",
    ["Hmm... We not at war for now, but me not sure we allies. Me not trust dwarves. King Veldaban, he warrior, me respect him, not like sneaky tradey dwarves."] = "Hmm... No estamos en guerra por ahora, pero no estoy seguro de que seamos aliados. No confío en los enanos. El rey Veldaban, el guerrero, lo respeto, no como los astutos enanos comerciantes.",
    ["*(If Veldaban is king:)*"] = "*(Si Veldaban es el rey:)*",
    ["He still in charge for now, but me not trust other dwarves. Me keep eye on border, not let sneaky tradey dwarves in with sneaky poison."] = "Él todavía está a cargo por ahora, pero no confío en otros enanos. Yo vigilo la frontera, no dejo entrar a enanos traficantes con veneno furtivo.",
    ["*(If Drunken Dwarf is king:)*"] = "*(Si Drunken Dwarf es el rey:)*",
    ["Me sad he dead."] = "Me entristece que haya muerto.",
    ["New king... me not like him. All he do is invite me to have drink. Me not fall for that! No one poison Pretty Flower that easy."] = "Nuevo rey... no me agrada. Lo único que hace es invitarme a tomar una copa. ¡No me enamoro de eso! Nadie envenena a Pretty Flower tan fácilmente.",
    ["*(If the Consortium is in power:)*"] = "*(Si el Consorcio está en el poder:)*",
    ["Now sneaky tradey dwarves back in charge, me not know if things go so well. Me keep eye on border, not let sneaky tradey dwarves in with sneaky poison."] = "Ahora los astutos enanos comerciales vuelven a estar a cargo, no sé si las cosas van tan bien. Yo vigilo la frontera, no dejo entrar a enanos traficantes con veneno furtivo.",
    ["What was it like working with the Black Guard?"] = "¿Cómo fue trabajar con Black Guard?",
    ["It not easy. Me have to explain carefully to trolls. 'You not kill these dwarves, they friends, but you kill those dwarves, they bad.' Very complicated, make brain hurt."] = "No es fácil. Tengo que explicárselo cuidadosamente a los trolls. \"No matas a estos enanos, son amigos, pero matas a esos enanos, son malos\". Muy complicado, hace daño cerebral.",
    ["But when we get used to it, it fun! Each army work to own strengths. Friendly dwarves run around, use something called 'tactics'. Trolls go up to bad dwarves and hit them!"] = "Pero cuando nos acostumbramos, ¡es divertido! Cada ejército trabaja para aprovechar sus propias fortalezas. Los enanos amigables corren de un lado a otro y usan algo llamado \"tácticas\". ¡Los trolls se acercan a los enanos malos y los golpean!",
    ["Me like lady dwarf colonel! She have tiny dwarf lungs but she shout like troll!"] = "¡Me gusta la dama coronel enana! ¡Tiene unos pulmones diminutos de enana pero grita como un troll!",
    ["Your son's called Sparkly Crystal?"] = "¿Tu hijo se llama Sparkly Crystal?",
    ["I'm setting up right now, could you come back later?"] = "Me estoy preparando ahora mismo, ¿podrías volver más tarde?",
    ["Greet god, young Herr/Fräulein!"] = "¡Saluda a Dios, joven Herr/Fräulein!",
    ["Greet god? What a strange way to greet someone."] = "¿Saludar a Dios? Qué manera más extraña de saludar a alguien.",
    ["It's a common Oktoberfest greeting, my friend. Don't worry, it's a welcoming one. What can I do for you?"] = "Es un saludo común del Oktoberfest, amigo mío. No te preocupes, es acogedor. ¿Qué puedo hacer por ti?",
    ["Pretzel Bert, and it's a pleasure to meet you! Who might you be?"] = "Pretzel Bert, ¡y es un placer conocerte! ¿Quién podrías ser?",
    ["Player name. Nice to meet you too."] = "Nombre de Player. Estoy encantado de conocerte también.",
    ["I've been employed by the Varrock Tourist Office to sell pretzels and spread word of Oktoberfest. Grundgüttiger, I couldn't think of a better job!"] = "La Oficina de Turismo de Varrock me ha contratado para vender pretzels y difundir el Oktoberfest. Grundgüttiger, ¡no se me ocurre un trabajo mejor!",
    ["What is Oktoberfest?"] = "¿Qué es el Oktoberfest?",
    ["Oktoberfest is a huge, traditional festival where a special beer called oktoberbrew is sold. We also organise multitude of events for anyone to take part in."] = "El Oktoberfest es un gran festival tradicional en el que se vende una cerveza especial llamada oktoberbrew. También organizamos multitud de eventos en los que cualquiera puede participar.",
    ["Best to check the forums if you want information on how to get involved."] = "Lo mejor es consultar los foros si quieres información sobre cómo participar.",
    ["More..."] = "Más...",
    ["How did Oktoberfest begin?"] = "¿Cómo empezó el Oktoberfest?",
    ["Oktoberfest has centuries of tradition behind it. Beer festivals have always been held at this time of year, so the beer can be drunk before the new brewing season starts."] = "El Oktoberfest tiene siglos de tradición a sus espaldas. Los festivales de la cerveza siempre se han celebrado en esta época del año, por lo que la cerveza se puede beber antes de que comience la nueva temporada de elaboración.",
    ["Oktoberfest is based on a festival that was originally held for the wedding of Queen Therese and King Ludwig, ancestral regents of my people."] = "El Oktoberfest se basa en un festival que originalmente se celebraba para la boda de la reina Teresa y el rey Luis, regentes ancestrales de mi pueblo.",
    ["Can I buy a pretzel?"] = "¿Puedo comprar un pretzel?",
    ["Naturally! They're 1gp each. How many would you like?"] = "¡Por supuesto! Cuestan 1 po cada uno. ¿Cuantos quisieras?",
    ["X pretzels! That'll be Xgp, please."] = "¡X pretzels! Ese será Xgp, por favor.",
    ["Okay!"] = "¡Está bien!",
    ["Oh, I don't seem to have enough space in my bag. I'll have to come back."] = "Oh, parece que no tengo suficiente espacio en mi bolso. Tendré que volver.",
    ["Come back soon, before they go cold!"] = "¡Vuelve pronto, antes de que se enfríen!",
    ["Careful! They are hot, and sehr, sehr tasty."] = "¡Cuidado! Son picantes y muy, muy sabrosos.",
    ["That's more than I thought. No, thank you."] = "Eso es más de lo que pensaba. No, gracias.",
    ["How many pretzels? They are very good, but I don't think you could eat that many!"] = "¿Cuántos pretzels? Están muy buenos, ¡pero no creo que puedas comer tantos!",
    ["Do you realise how silly you look?"] = "¿Te das cuenta de lo tonto que pareces?",
    ["Du geh! Watch that I don't pull your ears so long that you can hang pretzels from them!"] = "¡Du geh! ¡Cuidado con no tirarte de las orejas tanto que puedas colgar pretzels de ellas!",
    ["Welcome to the Bucking Baroo!"] = "¡Bienvenido al Bucking Baroo!",
    ["*(Only in 2017:)*"] = "*(Solo en 2017 :)*",
    ["This is the Bucking Baroo - pay 10 tokens, and then hold on for dear life!"] = "Este es el Bucking Baroo: ¡paga 10 fichas y luego espera por tu vida!",
    ["*(Only in 2018:)*"] = "*(Solo en 2018 :)*",
    ["This is the Bucking Baroo - climb on, and then hold on for dear life!"] = "Este es el Bucking Baroo: ¡súbete y luego agárrate para salvar tu vida!",
    ["Is it safe?"] = "¿Es seguro?",
    ["Really? You're going to question if this, out of all the things you've done on Gielinor, is safe?"] = "¿En serio? ¿Te preguntarás si esto, de todas las cosas que has hecho en Gielinor, es seguro?",
    ["...is it?"] = "...¿verdad?",
    ["Probably not."] = "Probablemente no.",
    ["Don't I recognise you?"] = "¿No te reconozco?",
    ["How astute! You've probably seen a fair amount of my fantastic art work here and there."] = "¡Qué astuto! Probablemente hayas visto una buena cantidad de mis fantásticas obras de arte aquí y allá.",
    ["Oh, now I remember. You do the funny comics!"] = "Oh, ahora lo recuerdo. ¡Tú haces los cómics divertidos!",
    ["I prefer 'unique masterpieces'."] = "Prefiero las 'obras maestras únicas'.",
    ["They're pretty funny!"] = "¡Son muy divertidos!",
    ["...thanks."] = "...gracias.",
    ["What slayer task are you currently on?"] = "¿En qué tarea de cazador estás actualmente?",
    ["It's lame. I want Nex."] = "Es aburrido. Quiero Nex.",
    ["But what ab..."] = "Pero ¿qué ab...?",
    ["Isn't that a li..."] = "¿No es un li...",
    ["But how do yo..."] = "¿Pero cómo...?",
    ["Ugh, forget I asked."] = "Uf, olvida que pregunté.",
    ["Bye"] = "Adiós",
    ["Have fun!"] = "¡Diviértete!",
    ["I have a special request for [breed]. Especially if it has the [Trait] trait!"] = "Tengo una solicitud especial para [breed]. ¡Especialmente si tiene el rasgo [Trait]!",
    ["I'm also after some Yaks, in fact I'll buy up to [number] more while I'm here."] = "También busco algunos yaks; de hecho, compraré hasta [número] más mientras esté aquí.",
    ["Sell [name] for [number] beans?"] = "¿Vender [name] por frijoles [número]?",
    ["Complete transaction anyway?"] = "¿Completar la transacción de todos modos?",
    ["Let me check what animals I have which match your request."] = "Déjame comprobar qué animales tengo que coincidan con tu solicitud.",
    ["I've bought all the animals I need for now, catch you later!"] = "He comprado todos los animales que necesito por ahora, ¡nos vemos más tarde!",
    ["Are you sure you want me to take all the Yaks you're holding? I won't take any of your favourites."] = "¿Estás seguro de que quieres que me quede con todos los yaks que tienes? No aceptaré ninguno de tus favoritos.",
    ["Sell all of your yaks?"] = "¿Vender todos tus yaks?",
    ["You've sold [number] animals for [number] total beans."] = "Has vendido animales [número] por un total de frijoles [número].",
    ["Greetings, non-believer. May the blessings of Icthlarin rest on your tired shoulders and may they set you at ease during interesting times."] = "Saludos, no creyente. Que las bendiciones de Icthlarin descansen sobre tus hombros cansados ​​y que te tranquilicen en momentos interesantes.",
    ["Can I pass through this gate?"] = "¿Puedo pasar por esta puerta?",
    ["Sorry, Sophanem is under quarantine. No one may leave or enter."] = "Lo sentimos, Sophanem está en cuarentena. Nadie podrá salir ni entrar.",
    ["Why is the city under quarantine?"] = "¿Por qué la ciudad está en cuarentena?",
    ["The gods have sent a plague of spots upon the city. We dare not risk it spreading further."] = "Los dioses han enviado una plaga de manchas sobre la ciudad. No nos atrevemos a arriesgarnos a que se propague más.",
    ["Okay, thank you."] = "Está bien, gracias.",
    ["Good day, Player. On behalf of the town, I would like to thank you for your help."] = "Buenos días, Player. En nombre del pueblo me gustaría agradecerles su ayuda.",
    ["It was nothing. I had some outside help."] = "No fue nada. Tuve ayuda externa.",
    ["I doubt it. Nobody from outside got past us. There's no need to be modest. Don't let us keep you. I'm sure you've got plenty of other important questing to get on with."] = "Lo dudo. Nadie de fuera nos pasó. No hay necesidad de ser modesto. No dejes que te retengamos. Estoy seguro de que tienes muchas otras misiones importantes con las que continuar.",
    ["Hey, hey, hey! What in the name of sweet suffering Icthlarin are you doing?"] = "¡Oye, oye, oye! ¿Qué estás haciendo en nombre del dulce sufrimiento Icthlarin?",
    ["I have this acne potion which I thought might help ease your itching."] = "Tengo esta poción para el acné que pensé que podría ayudarte a aliviar la picazón.",
    ["All that you'll achieve by pouring that potion on me is to ruin my lovely robes."] = "Todo lo que lograrás al verterme esa poción es arruinar mis hermosas túnicas.",
    ["Sorry, I was just trying to help."] = "Lo siento, solo estaba intentando ayudar.",
    ["This plague of spots is a divine burden placed upon us, which no amount of alchemy or potion-mixing will ease."] = "Esta plaga de manchas es una carga divina que se nos ha impuesto y que ninguna alquimia o mezcla de pociones podrá aliviar.",
    ["I wish there was more I could do for these people."] = "Ojalá pudiera hacer más por estas personas.",
    ["Praise Saradomin! The Mourners are gone, and we can live free of the fear of plague!"] = "¡Alabado sea Saradomin! ¡Los dolientes se han ido y podemos vivir libres del miedo a la plaga!",
    ["Let me tell you story of Dorgesh-tribe, sister!"] = "¡Déjame contarte la historia de la tribu Dorgesh, hermana!",
    ["Dorgesh-tribe weak and puny and stupid. They think their own lives more important than doing will of Big High War God. That why they run away. They not true goblins!"] = "La tribu Dorgesh era débil, insignificante y estúpida. Piensan que sus propias vidas son más importantes que hacer la voluntad del Gran Dios War. Por eso huyen. ¡No son verdaderos duendes!",
    ["Big High War God banish them because he strong and they weak. Now they come back, I think he will banish them again! Banish them to deepest pits of fire under earth where they suffer forever!"] = "Big High War Dios los destierre porque él es fuerte y ellos débiles. ¡Ahora vuelven, creo que los desterrará otra vez! ¡Destierralos a los pozos de fuego más profundos bajo la tierra donde sufrirán para siempre!",
    ["Remember! Goblins are mighty army! Big High War God himself train us in time of war!"] = "¡Recuerda! ¡Los duendes son un ejército poderoso! Big High War ¡Dios mismo nos entrene en tiempo de guerra!",
    ["Big High War God not choose us because we many, or because we strong. We nothing before he choose us! But he take us from Yu'biusk with mighty hand and make us strong!"] = "Big High War Dios no nos elige porque somos muchos, ni porque somos fuertes. ¡Nosotros nada antes de que él nos elija! ¡Pero él nos sacará de Yu'biusk con mano poderosa y nos hará fuertes!",
    ["Soon, sister! Big High War God send Chosen Commander!"] = "¡Pronto, hermana! Big High War ¡Dios envíe al Comandante Elegido!",
    ["Chosen Commander lead goblins into war as one army, and we conquer all armies of whole world! Then Big High War God himself return and sit on throne of bronze and rule over all!"] = "¡El comandante elegido lleva a los duendes a la guerra como un solo ejército y conquistaremos todos los ejércitos del mundo entero! ¡Entonces Big High War Dios mismo regresará y se sentará en un trono de bronce y gobernará sobre todo!",
    ["Let me tell you story about Hopespear, sister! He prophet of Big High War God! He very holy goblin!"] = "¡Déjame contarte una historia sobre Hopespear, hermana! ¡Él profeta de Big High War Dios! ¡Él, muy santo duende!",
    ["When Hopespear old, he walking near Goblin Village, and little goblin children came out of village and make fun of Big High War God. They say they not believe."] = "Cuando Hopespear era mayor, caminaba cerca de Goblin Village, y pequeños niños duendes salían de la aldea y se burlaban de Big High War God. Dicen que no creen.",
    ["Hopespear look at them, and curse them in name of Big High War God. Then lightning come out of sky and burn children up!"] = "Hopespear, míralos y maldícelos en nombre del Gran Dios War. ¡Entonces un rayo cae del cielo y quema a los niños!",
    ["May Big High War God give you faith."] = "Que Big High War Dios te dé fe.",
    ["Before you enter battle, clear mind of thought. Do not think about what you will do or what may happen."] = "Antes de entrar en batalla, aclara tus pensamientos. No pienses en lo que harás o en lo que puede pasar.",
    ["When battle start, Big High War God guide your arm and fill your heart with courage."] = "Cuando comience la batalla, Big High War Dios guía tu brazo y llena tu corazón de coraje.",
    ["Have faith in Big High War God. He rule all war, so whatever happen in war, it his will."] = "Ten fe en el Dios Grande y Alto War. Él gobierna todas las guerras, así que pase lo que pase en la guerra, será su voluntad.",
    ["Goblins great nation in time of great war, sister! Whole goblin tribes go to war, fight as one army. Goblins line up behind great commander in lines so long you not see both ends."] = "¡Los duendes son una gran nación en tiempos de gran guerra, hermana! Tribus enteras de duendes van a la guerra, luchan como un solo ejército. Los duendes se alinean detrás del gran comandante en filas tan largas que no se ven ambos extremos.",
    ["Then goblins meet other armies on field of battle! Sword clash on shield, arrows fly through air! There more goblins than enemy can count, and every goblin a great warrior!"] = "¡Entonces los duendes se encuentran con otros ejércitos en el campo de batalla! ¡Choque de espada contra escudo, flechas vuelan por el aire! ¡Hay más duendes de los que el enemigo puede contar, y cada duende es un gran guerrero!",
    ["Hello, please can I get past?"] = "Hola, ¿puedo pasar?",
    ["I'm sorry, but no humans may enter Prifddinas while those criminals are at large."] = "Lo siento, pero ningún ser humano puede ingresar a Prifddinas mientras esos criminales estén prófugos.",
    ["I'm no criminal."] = "No soy ningún criminal.",
    ["Rules are rules. No one enters until the brigands are gone."] = "Las reglas son reglas. Nadie entra hasta que los bandidos se hayan ido.",
    ["May I ask why you are guarding a field?"] = "¿Puedo preguntarte por qué estás vigilando un campo?",
    ["A field? Our great city of Prifddinas may be lost, but we are proud to guard the land it once occupied."] = "¿Un campo? Puede que nuestra gran ciudad de Prifddinas esté perdida, pero estamos orgullosos de proteger la tierra que una vez ocupó.",
    ["Hello. Can I get past, please?"] = "Hola. ¿Puedo pasar, por favor?",
    ["Wow, what is that you are wearing?"] = "Vaya, ¿qué es lo que llevas puesto?",
    ["Can you remind me what you are wearing?"] = "¿Puedes recordarme qué llevas puesto?",
    ["I'm wearing primal armour and equipment. You'll be able to smith it yourself in the upcoming 110 Mining and Smithing update."] = "Llevo armadura y equipo primarios. Podrás crearlo tú mismo en la próxima actualización 110 Mining y Smithing.",
    ["I'm wearing primal armour and equipment. You can smith it yourself in the 110 Mining and Smithing update!"] = "Llevo armadura y equipo primarios. ¡Puedes crearlo tú mismo en la actualización 110 Mining y Smithing!",
    ["To smith it, first you'll need to mine 10 new ores across the Daemonheim peninsula, which requires 100 Mining and an appropriate pickaxe."] = "Para forjarlo, primero necesitarás extraer 10 minerales nuevos en toda la península Daemonheim, lo que requiere 100 Mining y un pico adecuado.",
    ["Then with 100 Smithing, you'll be able to smelt the ore into primal bars, and smith primal armour and weapons. Want to know more?"] = "Luego, con 100 Smithing, podrás fundir el mineral en barras primarias y forjar armaduras y armas primarias. ¿Quieres saber más?",
    ["View calendar?"] = "¿Ver calendario?",
    ["Yes, I want more information."] = "Sí, quiero más información.",
    ["No, I'll wait."] = "No, esperaré.",
    ["Good day, [Sir/Madam]."] = "Buenos días, [Sir/Madam].",
    ["Good day, Your Royal Highness."] = "Buenos días, Su Alteza Real.",
    ["*If the player is male and engaged to Princess Astrid*"] = "*Si el player es hombre y está comprometido con Princess Astrid*",
    ["Good day, [Fremennik name]."] = "Buenos días, [Fremennik name].",
    ["Good day, Prince Brand."] = "Buenos días, Prince Brand.",
    ["*If the player is female and engaged to Princess Astrid*"] = "*Si el player es mujer y está comprometida con Princess Astrid*",
    ["Good day, Madam."] = "Buenos días, señora.",
    ["Thank you for helping father so much, [Fremennik name]."] = "Gracias por ayudar tanto a padre, [Fremennik name].",
    ["I hear you made peace between our kingdom and Etceteria once more. Well done, madam."] = "He oído que hiciste las paces entre nuestro reino y Etceteria una vez más. Bien hecho, señora.",
    ["*If the player is female and engaged to Prince Brand*"] = "*Si el player es mujer y está comprometida con Prince Brand*",
    ["I'm glad you could help father so much. He's so much happier now that he can go adventuring, and I think it was the last thing that would stop Queen Sigrid considering him for marriage. Speaking of marriage, are you any closer to finding someone to marry us? I can barely wait!"] = "Me alegra que hayas podido ayudar tanto a padre. Es mucho más feliz ahora que puede ir de aventuras y creo que fue lo último que impediría que Queen Sigrid lo considerara para casarse. Hablando de matrimonio, ¿estás más cerca de encontrar a alguien que se case con nosotros? ¡Apenas puedo esperar!",
    ["Soon, my dear."] = "Pronto, querida.",
    ["Really? That's great news!"] = "¿En serio? ¡Esa es una gran noticia!",
    ["No luck so far."] = "No hubo suerte hasta ahora.",
    ["That is such a shame."] = "Es una lástima.",
    ["*If the player was previously female and got engaged to Prince Brand but is now male*"] = "*Si el player era anteriormente mujer y se comprometió con Prince Brand pero ahora es hombre*",
    ["I like your new look!"] = "¡Me gusta tu nuevo look!",
    ["I hear you made peace between our kingdom and Etceteria once more. Well done, [Fremennik name]."] = "Escuché que hiciste las paces entre nuestro reino y Etceteria una vez más. Bien hecho, [Fremennik name].",
    ["You are part of the problem."] = "Eres parte del problema.",
    ["You are part of the solution."] = "Eres parte de la solución.",
    ["How are you feeling, Princess?"] = "¿Cómo te sientes, princesa?",
    ["*content barking*"] = "*ladridos de contenido*",
    ["*excited barking*"] = "*ladridos emocionados*",
    ["*hungry barking*"] = "*ladrido hambriento*",
    ["I'll have Rodney get you something to eat."] = "Le pediré a Rodney que te traiga algo de comer.",
    ["*playful barking*"] = "*ladridos juguetones*",
    ["*wistful barking*"] = "*ladrido melancólico*",
    ["Thinking about your days in Edgeville with the Duke?"] = "¿Estás pensando en tus días en Edgeville con el Duque?",
    ["*sad barking*"] = "*ladridos tristes*",
    ["Who's a good girl? You are!"] = "¿Quién es una buena chica? ¡Eres!",
    ["*happy barking*"] = "*ladrido feliz*",
    ["All is good!"] = "¡Todo está bien!",
    ["New friend is a good boy!"] = "¡El nuevo amigo es un buen chico!",
    ["Treat! Treat!"] = "¡Trato! ¡Tratar!",
    ["Rodney-dear play fetch!"] = "Rodney-¡Querido juego, busca!",
    ["Miss Dad."] = "Señorita Dad.",
    ["Was a good human."] = "Era una buena humana.",
    ["Me! Me!"] = "¡Yo! ¡A mí!",
    ["Good day, Darling"] = "Buenos días, cariño.",
    ["*Curtsy/Bow/Wave*"] = "*Reverencia/Reverencia/Saludo*",
    ["*Dance/Twirl/ Jig/ Headbang/ Goblin Bow/ Goblin Salute*"] = "*Baile/Giro/ Plantilla/ Headbang/ Arco de duende/ Saludo de duende*",
    ["Your dancing never ceases to impress me, darling!"] = "¡Tu baile nunca deja de impresionarme, cariño!",
    ["*Jump For Joy/ Raspberry/ Glass box/ Glass wall/ Climb Rope/ Salute/ Lean/*"] = "*Saltar de alegría/ Frambuesa/ Caja de cristal/ Pared de cristal/ Cuerda para trepar/ Saludo/ Lean/*",
    ["You are silly!"] = "¡Eres tonto!",
    ["*Angry/ Cry/ Panic*"] = "*Enojado/Llorar/Pánico*",
    ["What's wrong darling?"] = "¿Qué pasa cariño?",
    ["*Cheer*"] = "*Aplausos*",
    ["If you want to cheer someone on, darling, I suggest you find my brother."] = "Si quieres animar a alguien, cariño, te sugiero que busques a mi hermano.",
    ["*Applaud*"] = "*Aplaude*",
    ["If you want to applaud someone on, darling, I suggest you find my brother."] = "Si quieres aplaudir a alguien, cariño, te sugiero que busques a mi hermano.",
    ["*Beckon*"] = "*Hace señas*",
    ["I'm staying right here"] = "Me quedo aquí",
    ["*Laugh*"] = "*Risa*",
    ["What's so funny, darling?"] = "¿Qué es tan gracioso, cariño?",
    ["Hello, dear."] = "Hola, querida.",
    ["Hello. Have you found a priest for our marriage yet?"] = "Hola. ¿Ya has encontrado un sacerdote para nuestro matrimonio?",
    ["I'm afraid not, dear. I don't think there is one to be had on these islands for love nor money..."] = "Me temo que no, querida. No creo que haya uno en estas islas ni por amor ni por dinero...",
    ["Do not fear, though; I shall call for you as soon as one is found."] = "Pero no temas; Te llamaré tan pronto como encuentre uno.",
    ["*If the player was previously male and got engaged to Princess Astrid but is now female*"] = "*Si el player era anteriormente hombre y se comprometió con Princess Astrid pero ahora es mujer*",
    ["Has he g-g-gone?"] = "¿Se ha ido?",
    ["Has who gone? Do you mean the guard?"] = "¿Quién se ha ido? ¿Te refieres al guardia?",
    ["No! The c-c-cat! An evil t-t-tomcat, fur as black as the n-n-night."] = "¡No! ¡El c-c-gato! Un gato malvado, de pelaje tan negro como la noche.",
    ["Wait, do you mean Bob the Cat? He's harmless!"] = "Espera, ¿te refieres al gato Bob? ¡Es inofensivo!",
    ["No! I mean Evil Bob - his twin from another p-p-plane of existence!"] = "¡No! Me refiero a Evil Bob, ¡su gemelo de otro plano p-p de existencia!",
    ["Er, okay... No, there aren't any cats here."] = "Er, está bien... No, no hay gatos aquí.",
    ["Are you s-s-sure? He can appear out of nowhere at any time. He might be behind you right n-n-now! He'll take you to a m-m-magical prison full of balloon animals...but they're alive! And have k-k-keys inside them!"] = "¿Estás seguro? Puede aparecer de la nada en cualquier momento. ¡Podría estar detrás de ti ahora mismo! Te llevará a una prisión mágica llena de animales con globos... ¡pero están vivos! ¡Y tienen k-k-llaves dentro!",
    ["Right. I'm suddenly very glad there are some prison bars between us."] = "Correcto. De repente me alegro mucho de que haya algunos barrotes entre nosotros.",
    ["M-m-me too. I feel s-s-safer when I'm in here."] = "M-m-yo también. Me siento más seguro cuando estoy aquí.",
    ["You and me both."] = "Tú y yo los dos.",
    ["If you're gonna break out... Please l-l-lock the door again behind you. I feel safer h-h-here."] = "Si vas a escapar... Por favor, vuelve a cerrar la puerta detrás de ti. Me siento más seguro aquí.",
    ["Cat: Meow!"] = "Gato: Meow!",
    ["You don't have anything planted in that patch. Plant something and I might agree to look after it for you."] = "No tienes nada plantado en ese parche. Planta algo y tal vez acepte cuidarlo por ti.",
    ["I want [number] [items] for that."] = "Quiero [número] [items] para eso.",
    ["Pay [number] [items]?"] = "¿Pagar [número] [items]?",
    ["I think you should claim the XP from that patch before having it chopped down."] = "Creo que deberías reclamar los XP de ese parche antes de eliminarlo.",
    ["Pay 200 gp to have the tree chopped down?"] = "¿Pagar 200 po para que talen el árbol?",
    ["Yes, get rid of the tree."] = "Sí, deshazte del árbol.",
    ["I'll want 200 gp for chopping down that tree."] = "Querré 200 po por talar ese árbol.",
    ["You can not afford that."] = "No puedes permitirte eso.",
    ["The gardener obligingly removes your tree."] = "El jardinero amablemente retira su árbol.",
    ["Would you chop my tree down for me?"] = "¿Podrías talar mi árbol por mí?",
    ["You look like you could chop it down yourself. I can chop the tree down for you if you like, but I'll want 200 gp to make it worth my while."] = "Parece que podrías cortarlo tú mismo. Puedo talar el árbol si quieres, pero necesitaré 200 po para que valga la pena.",
    ["200 gp? I'll do it myself."] = "¿200 po? Lo haré yo mismo.",
    ["Okay, go ahead."] = "Está bien, adelante.",
    ["I don't have 200 gp I'm afraid."] = "Me temo que no tengo 200 po.",
    ["If you like, but I want [number] [item] for that."] = "Si quieres, pero quiero [número] [item] para eso.",
    ["Okay, it's a deal."] = "Está bien, es un trato.",
    ["That'll do nicely, [Sir/Madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [Sir/Madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
    ["No, that's too much."] = "No, eso es demasiado.",
    ["Hi, soldier."] = "Hola, soldado.",
    ["Why, hello there! Have you heard about Primalmoose?"] = "¡Hola! ¿Has oído hablar de Primalmoose?",
    ["What's a primal moose?"] = "¿Qué es un alce primitivo?",
    ["A barbarian! Word is he's been smashing through waves of Penance faster than anyone we've ever seen."] = "¡Un bárbaro! Se dice que ha estado superando oleadas de Penitencia más rápido que nadie que hayamos visto.",
    ["That's why we've decided to to challenge the veterans."] = "Por eso hemos decidido desafiar a los veteranos.",
    ["Well, I suppose that's a good idea."] = "Bueno, supongo que es una buena idea.",
    ["You should try them yourself. Put your skills to the test against the Penance King!"] = "Deberías probarlos tú mismo. ¡Pon a prueba tus habilidades contra el Penance King!",
    ["Shhh. Don't talk to me."] = "Shhh. No me hables.",
    ["What? Why?"] = "¿Qué? ¿Por qué?",
    ["If I'm seen slacking off by talking to you, I'll be in deep trouble!"] = "¡Si me ven holgazaneando al hablar contigo, estaré en un gran problema!",
    ["Oh... Sorry."] = "Oh... Lo siento.",
    ["Hi there."] = "Hola.",
    ["Don't suppose you've seen a battleaxe around here?"] = "¿No habrás visto un hacha de guerra por aquí?",
    ["A battleaxe? Nope, afraid not."] = "¿Un hacha de batalla? No, no tengo miedo.",
    ["The captain is going to kill me if he finds out I've lost my weapon."] = "El capitán me va a matar si descubre que he perdido mi arma.",
    ["Hello. So you're just a private?"] = "Hola. ¿Entonces eres sólo un soldado raso?",
    ["Show some respect! It's more than you'll achieve."] = "¡Muestre algo de respeto! Es más de lo que lograrás.",
    ["I beg to differ. I'm in perfect shape!"] = "No estoy de acuerdo. ¡Estoy en perfecta forma!",
    ["Prove it!"] = "¡Pruébalo!",
    ["How?"] = "¿Cómo?",
    ["Give me five star jumps!"] = "¡Dame saltos de cinco estrellas!",
    ["Five sit-ups!"] = "¡Cinco abdominales!",
    ["Run on the spot!"] = "¡Corre en el acto!",
    ["Okay. Maybe you have what it takes. Best you speak with the captain."] = "Está bien. Quizás tengas lo que se necesita. Será mejor que hables con el capitán.",
    ["[You'll need an empty bucket to collect the milk.]"] = "[Necesitarás un balde vacío para recoger la leche.]",
    ["You milk the cow."] = "Tu ordeñas la vaca.",
    ["[You need to have started the Cold War quest to attempt this.]"] = "[Debes haber iniciado la misión Cold War para intentar esto.]",
    ["Yes? Oh, another adventurer, are you? Well, just remember that I'm the supervisor here."] = "¿Sí? Oh, otro aventurero, ¿verdad? Bueno, sólo recuerda que soy el supervisor aquí.",
    ["If you have the skills, feel free to excavate for artefacts, but please try not to damage the area."] = "Si tienes las habilidades, siéntete libre de excavar en busca de artefactos, pero intenta no dañar el área.",
    ["Some of us have more important work, such as documenting the finds for the Archaeology Guild."] = "Algunos de nosotros tenemos trabajos más importantes, como documentar los hallazgos para el Gremio Archaeology.",
    ["Hey Professor. How are you doing?"] = "Hola profesor. ¿Cómo estás?",
    ["The salamander stares intently at you. You take it to mean 'I would be better if I was back in my human body'."] = "La salamandra te mira fijamente. Se entiende que significa \"Estaría mejor si volviera a mi cuerpo humano\".",
    ["Don't worry! We're hard at work figuring out how to swap you back again."] = "¡No te preocupes! Estamos trabajando arduamente para descubrir cómo volver a intercambiarte.",
    ["At least I hope someone is because I have no idea."] = "Al menos espero que alguien lo sea porque no tengo idea.",
    ["**Professor Henry:** Did you want to know about the old jail block? We always need adventurers to keep the cockroaches in check."] = "**Professor Henry:** ¿Querías saber sobre el antiguo pabellón de la cárcel? Siempre necesitamos aventureros para mantener a raya a las cucarachas.",
    ["Do I need to do your exam?"] = "¿Necesito hacer tu examen?",
    ["No, the exam isn't really for adventurers like you. Are you looking for the jail block?"] = "No, el examen no es realmente para aventureros como tú. ¿Estás buscando el bloque de la cárcel?",
    ["Sure, tell me about the jail."] = "Claro, cuéntame sobre la cárcel.",
    ["In the cells downstairs there's a secret passage into the old prison. I hear that fame and fortune awaits a suitably skilled adventurer."] = "En las celdas de abajo hay un pasaje secreto a la antigua prisión. He oído que la fama y la fortuna esperan a un aventurero con las habilidades adecuadas.",
    ["Thanks, I'll look into that."] = "Gracias, lo investigaré.",
    ["Hello, Professor."] = "Hola, profesor.",
    ["Ah, hello, Player. How goes the adventuring? I trust you are enjoying your adventures?"] = "Ah, hola, Player. ¿Cómo va la aventura? ¿Confío en que estés disfrutando de tus aventuras?",
    ["I am, thanks. I was wondering where the jail block might be."] = "Lo soy, gracias. Me preguntaba dónde podría estar el bloque de la cárcel.",
    ["Ah, yes. Search the cells downstairs and I'm sure you'll find it easily enough."] = "Ah, sí. Busca en las celdas de abajo y estoy seguro de que lo encontrarás con bastante facilidad.",
    ["Hello, Professor"] = "Hola, profesor.",
    ["Good to see you again."] = "Me alegro de verte de nuevo.",
    ["Hello what?"] = "¿Hola qué?",
    ["Uh...hello there?"] = "Eh... ¿hola?",
    ["Hello, 'Professor'. Manners cost nothing, you know. When you're in my classroom, I ask that you use the proper address for my station."] = "Hola, 'Profesor'. Los modales no cuestan nada, ¿sabes? Cuando estés en mi salón de clases, te pido que uses la dirección adecuada para mi estación.",
    ["Your station?"] = "¿Tu estación?",
    ["Yes. It means 'position', so to speak."] = "Sí. Significa \"posición\", por así decirlo.",
    ["Now, what can I do for you, exactly?"] = "Ahora, ¿qué puedo hacer por ti exactamente?",
    ["**Player:** What is this place?"] = "**Player:** ¿Qué es este lugar?",
    ["This is the Misthalin Training Centre of Excellence. It is where bold adventurers, such as yourself, can come to learn of the dangers of the wide world and gain some valuable experience at the same time."] = "Este es el Centro de Excelencia de Capacitación de Misthalin. Es donde los aventureros audaces, como usted, pueden aprender sobre los peligros del mundo y adquirir una valiosa experiencia al mismo tiempo.",
    ["Here you can take part in the Player Safety test: a set of valuable lessons to learn about staying safe."] = "Aquí puedes participar en la prueba de seguridad el player: un conjunto de lecciones valiosas para aprender a mantenerte seguro.",
    ["I can give you a test paper to take and, once completed, you can bring it back to me for marking. Would you like to take the test? It will not cost you anything."] = "Puedo darte un examen para que lo realices y, una vez completado, puedes entregármelo para corregirlo. ¿Quieres realizar la prueba? No te costará nada.",
    ["Right then, I...oh! You already have a test paper? Excellent! Well, good luck then."] = "En ese momento, yo... ¡oh! ¿Ya tienes un examen? ¡Excelente! Bueno, buena suerte entonces.",
    ["Uh, thanks."] = "Eh, gracias.",
    ["Right then. Here is the test paper. When you have completed all the questions, bring it back to me for marking."] = "Justo entonces. Aquí está el examen. Cuando hayas completado todas las preguntas, tráemelas para que las califique.",
    ["Not right now, thanks."] = "Ahora no, gracias.",
    ["Very well. Come back and see me again if you change your mind."] = "Muy bien. Vuelve a verme de nuevo si cambias de opinión.",
    ["Ah, hello again. How may I help you?"] = "Ah, hola de nuevo. ¿Cómo puedo ayudarte?",
    ["Ah, Player. How's the test going?"] = "Ah, Player. ¿Cómo va la prueba?",
    ["I think I've finished."] = "Creo que ya terminé.",
    ["Excellent! Let me mark the paper for you, then."] = "¡Excelente! Entonces déjame marcarte el papel.",
    ["Hmm. Uh-huh, yes, I see. Good! Yes, that's right."] = "Mmm. Ajá, sí, ya veo. ¡Bien! Sí, eso es correcto.",
    ["Excellent! Allow me to reward you for your work. I have these two old lamps that you may find useful."] = "¡Excelente! Permíteme recompensarte por tu trabajo. Tengo estas dos lámparas viejas que quizás te resulten útiles.",
    ["Also, there is an old jail block connected to the cells below the training centre, which have been overrun with vicious creatures. If you search around the jail cells downstairs, you should find it easily enough."] = "Además, hay un antiguo bloque de cárcel conectado a las celdas debajo del centro de entrenamiento, que han sido invadidas por criaturas feroces. Si buscas en las celdas de la cárcel de abajo, deberías encontrarlo con bastante facilidad.",
    ["Now, your rewards."] = "Ahora, tus recompensas.",
    ["Aha! Top marks! Well done on solving this clue!"] = "¡Ajá! ¡Las mejores notas! ¡Bien hecho por resolver esta pista!",
    ["I didn't realise gnomes were interested in magic."] = "No sabía que los gnomos estaban interesados ​​en la magia.",
    ["Gnomes are interested in everything, lad."] = "A los gnomos les interesa todo, muchacho.",
    ["We have a saying, 'Curiosity killed the cat'. But cats aren't clever enough to understand what they find. Gnomes are."] = "Tenemos un dicho: \"La curiosidad mató al gato\". Pero los gatos no son lo suficientemente inteligentes como para entender lo que encuentran. Los gnomos lo son.",
    ["Hey! Some of my best friends are cats!"] = "¡Oye! ¡Algunos de mis mejores amigos son gatos!",
    ["I think that says more about you than cats."] = "Creo que eso dice más de ti que los gatos.",
    ["What would you like to do?"] = "¿Qué te gustaría hacer?",
    ["I'm also looking for a new animal, I'm currently after A [animal]"] = "También estoy buscando un nuevo animal, actualmente estoy buscando A [animal]",
    ["If you complete this, I'll give you : Cosmic rune x 50. I'm sure you'll gain some reputation with the farming guild too!"] = "Si completas esto, te daré: Runa cósmica x 50. ¡Estoy seguro de que también ganarás algo de reputación en el gremio de agricultores!",
    ["You'll have to be quick though!, I'm only here for [number] hours and [number] minutes. To be exact."] = "¡Tendrás que ser rápido! Solo estoy aquí por [número] horas y [número] minutos. Para ser exactos.",
    ["[You've received : Cosmic rune x 50 And 2,750 farming reputation.]"] = "[Has recibido: Runa cósmica x 50 Y 2750 de reputación agrícola.]",
    ["A new request will be available in [time].."] = "Una nueva solicitud estará disponible en [time].",
    ["You've already completed this request, there will be a new daily request in [time].."] = "Ya has completado esta solicitud, habrá una nueva solicitud diaria en [time].",
    ["Hmm, I wonder... Oh. My order. Thank you - mind you don't get any food or drink on the books."] = "Hmm, me pregunto... Oh. Mi pedido. Gracias. Tenga en cuenta que no incluye comida ni bebida en los libros.",
    ["Fascinating, fascinating. It's remarkable what these young dwarves have managed to create. Oh, hello young man."] = "Fascinante, fascinante. Es sorprendente lo que estos jóvenes enanos han logrado crear. Hola joven.",
    ["Hello, what's a gnome like you doing in a place like this?"] = "Hola, ¿qué hace un gnomo como tú en un lugar como este?",
    ["Ah, well I have been sent by the King to talk with the dwarves here and find out more about their recent advances in technology."] = "Ah, bueno, el Rey me envió para hablar con los enanos aquí y descubrir más sobre sus recientes avances en tecnología.",
    ["Found anything interesting?"] = "¿Encontraste algo interesante?",
    ["The rideable carts are a very handy way to get to mining sites, and the Blast Furnace is a magnificent beast of a machine."] = "Los carros que se pueden montar son una forma muy práctica de llegar a los sitios mineros, y el Alto Horno es una máquina magnífica.",
    ["I'll have a look, thanks."] = "Echaré un vistazo, gracias.",
    ["Just what I need. Dwarven cuisine is a bit ... solid for my tastes."] = "Justo lo que necesito. La cocina enana es un poco... sólida para mi gusto.",
    ["Be careful in here, there's lots of dangerous equipment."] = "Ten cuidado aquí, hay muchos equipos peligrosos.",
    ["What does this machine do?"] = "¿Qué hace esta máquina?",
    ["Nothing at the moment...it's broken. It's meant to be a transmutation machine. It has also spent time as a time travel machine, a dramatic lighting generator, and a thing for generating monsters."] = "Nada por el momento... está roto. Está destinado a ser una máquina de transmutación. También ha pasado un tiempo como máquina de viajar en el tiempo, generador de iluminación espectacular y algo para generar monstruos.",
    ["Is this your house?"] = "¿Esta es tu casa?",
    ["No, I'm just one of the tenants. It belongs to the count who lives in the basement."] = "No, solo soy uno de los inquilinos. Pertenece al conde que vive en el sótano.",
    ["What does the portal machine do?"] = "¿Qué hace la máquina del portal?",
    ["Ah, an interesting question! It creates a rift in the very fabric of space, opening a portal to some hitherto undiscovered plane that exists parallel to our own."] = "¡Ah, una pregunta interesante! Crea una grieta en la estructura misma del espacio, abriendo un portal a algún plano hasta ahora no descubierto que existe paralelo al nuestro.",
    ["It's a teleportation machine."] = "Es una máquina de teletransportación.",
    ["Err, just before you go through there..."] = "Err, justo antes de pasar por allí...",
    ["What's the problem?"] = "¿Cuál es el problema?",
    ["That portal opens into a plane populated with some very shocking creatures. You should wear some kind of insulated armour before going there."] = "Ese portal se abre a un plano poblado por algunas criaturas muy impactantes. Deberías usar algún tipo de armadura aislante antes de ir allí.",
    ["*If the player has insulated boots in their inventory:*"] = "*Si el player tiene botas aislantes en su inventario:*",
    ["Oops, I'd better put my insulated boots on first."] = "Vaya, será mejor que me ponga las botas aislantes primero.",
    ["*If the player does not have insulated boots in their inventory:*"] = "*Si el player no tiene botas aislantes en su inventario:*",
    ["Where can I get insulated armour from?"] = "¿Dónde puedo conseguir armaduras aisladas?",
    ["Well there were some pretty tough people here last week. Said they were Slayer Masters. They were planning on making some protective boots. You should speak to one of them."] = "Bueno, hubo gente bastante dura aquí la semana pasada. Dijo que eran Slayer Masters. Estaban pensando en hacer unas botas protectoras. Deberías hablar con uno de ellos.",
    ["Thanks, I'll do that."] = "Gracias, lo haré.",
    ["No problem. See you later."] = "No hay problema. Hasta luego.",
    ["I don't want to run around after Slayer Masters, I'm going through."] = "No quiero correr detrás de Slayer Masters, voy a pasar.",
    ["Fair enough, just don't say I didn't warn you"] = "Es justo, pero no digas que no te lo advertí",
    ["Thanks, I think I'll stay here for a while then."] = "Gracias, creo que entonces me quedaré aquí por un tiempo.",
    ["Thanks for the warning, but I'm not scared of any monster."] = "Gracias por la advertencia, pero no le tengo miedo a ningún monstruo.",
    ["Ok. Just don't say I didn't warn you..."] = "Vale. Simplemente no digas que no te lo advertí...",
    ["Greetings, human!"] = "¡Saludos, humano!",
    ["Do you live here too?"] = "¿Vives aquí también?",
    ["Oh no, I come from the Gnome Stronghold. I've been sent here by King Narnode to learn about human magics."] = "Oh no, vengo del Gnome Stronghold. El rey Narnode me envió aquí para aprender sobre la magia humana.",
    ["The stronghold's in the north-west of the continent - a long way away. You should visit us there some time. The food's great, and the company's delightful."] = "La fortaleza está en el noroeste del continente, muy lejos. Deberías visitarnos allí alguna vez. La comida es estupenda y la compañía encantadora.",
    ["I'll try to make time for it. Sounds like a nice place."] = "Intentaré sacar tiempo para ello. Suena como un lindo lugar.",
    ["Well, it's full of gnomes. How much nicer could it be?"] = "Bueno, está lleno de gnomos. ¿Cuánto mejor podría ser?",
    ["You'll be here for the puzzle, then?"] = "¿Entonces estarás aquí para resolver el rompecabezas?",
    ["[Professor Onglewip has given you a puzzle box!]"] = "[¡Professor Onglewip te ha regalado una caja de rompecabezas!]",
    ["That is close, but it's just not right."] = "Eso está cerca, pero simplemente no está bien.",
    ["[Professor Onglewip has given you another clue scroll!]"] = "[¡Professor Onglewip te ha dado otro pergamino de pistas!]",
    ["Perfect; good luck!"] = "Perfecto; ¡buena suerte!",
    ["Ah, now that's a familiar smell. Thank you."] = "Ah, ese es un olor familiar. Gracias.",
    ["*popping noises*"] = "*ruidos de estallido*",
    ["I don't think the professor is home right now..."] = "No creo que el profesor esté en casa ahora mismo...",
    ["*When talking to Psamtik in the Merchant district in Menaphos.*"] = "*Al hablar con Psamtik en el distrito comercial de Menaphos.*",
    ["An outsider? Perhaps you bring new manuscripts from the greener lands?"] = "¿Un extraño? ¿Quizás traigas nuevos manuscritos de tierras más verdes?",
    ["**Pub musician** Me? I'm a musician! Let me help you relax: sit down, rest your weary limbs and allow me to wash away the troubles of the day. some music to give you the energy to continue? Did you know know music has curative properties? Music stimulates the healing humours in your body, so they say."] = "**Pub musician** ¿Yo? ¡Soy músico! Déjame ayudarte a relajarte: siéntate, descansa tus miembros cansados ​​y permíteme eliminar los problemas del día. ¿Alguna música que te dé energía para continuar? ¿Sabías que la música tiene propiedades curativas? La música estimula los humores curativos del cuerpo, según dicen.",
    ["**Player** Who says that, then?"] = "**Player** ¿Quién dice eso entonces?",
    ["**Pub musician** I was told by a travelling medical practitioner, selling oil extracted from snakes. It's a commonly known fact, so he After resting to some music, you will be able to run longer, and your life points will increase noticeably. A panacea, if you will. Ah, the power of music."] = "**Pub musician** Me lo dijo un médico que viajaba y vendía aceite extraído de serpientes. Es un hecho comúnmente conocido, por lo que después de descansar con algo de música, podrás correr más tiempo y tus puntos de vida aumentarán notablemente. Una panacea, por así decirlo. Ah, el poder de la música.",
    ["**Player** So, just listening to some music will cure me of all my ills?"] = "**Player** Entonces, ¿solo escuchar algo de música me curará de todos mis males?",
    ["**Pub musician** Well, not quite. Poison, lack of faith and dismembered limbs are all a bit beyond even the most rousing of harmonies, but I guarantee you will feel refreshed, and better equipped to take on the challenges of the day."] = "**Pub musician** Bueno, no del todo. El veneno, la falta de fe y los miembros desmembrados están un poco más allá incluso de las armonías más conmovedoras, pero te garantizo que te sentirás renovado y mejor equipado para afrontar los desafíos del día.",
    ["**Player** Does this cost me anything?"] = "**Player** ¿Esto me cuesta algo?",
    ["**Pub musician** Oh, no! My reward is the pleasure I bring to the masses. Just remember me and tell your friends, and that is payment enough. So sit down and enjoy!"] = "**Pub musician** ¡Oh, no! Mi recompensa es el placer que brindo a las masas. Sólo recuérdame y díselo a tus amigos, y eso es pago suficiente. ¡Así que siéntate y disfruta!",
    ["**Pub musician** Have you ever been on a long journey, and simply wanted to have a rest? When you're running from city to city, it's so easy to run out of breath, don't you find?"] = "**Pub musician** ¿Alguna vez has estado en un viaje largo y simplemente quisiste descansar? Cuando corres de ciudad en ciudad, es muy fácil quedarte sin aliento, ¿no te parece?",
    ["**Player** Yes, I can never run as far as I'd like."] = "**Player** Sí, nunca puedo correr tan lejos como quisiera.",
    ["**Pub musician** Well, you may rest anywhere, simply choose the Rest option on the run buttons.When you rest, you will sit on the floor. When you are nice and relaxed, you will recharge your run energy more quickly and your life points twice as fast as you would do normally.Of course, you can't do anything else while you're resting, other than talk."] = "**Pub musician** Bueno, puedes descansar en cualquier lugar, simplemente elige la opción Descanso en los botones de ejecución. Cuando descanses, te sentarás en el suelo. Cuando estés agradable y relajado, recargarás tu energía de carrera más rápidamente y tus puntos de vida dos veces más rápido de lo que lo harías normalmente. Por supuesto, no podrás hacer nada más mientras estás descansando, aparte de hablar.",
    ["**Player** Why not?"] = "**Player** ¿Por qué no?",
    ["**Pub musician** Well, you wouldn't be resting, now would you? Also, you should know that resting by a musician, has a similar effect but the benefits are greater."] = "**Pub musician** Bueno, no estarías descansando, ¿verdad? Además, debes saber que el descanso junto a un músico, tiene un efecto similar pero los beneficios son mayores.",
    ["**Pub musician** Also, you should know that resting by a musician, has a similar effect but the benefits are greater.Simply sit down and rest as you would normally, nice and close to the musician. and hear the music. anything other than talk, you will stop resting."] = "**Pub musician** Además, debes saber que descansar junto a un músico, tiene un efecto similar pero los beneficios son mayores. Simplemente siéntate y descansa como lo harías normalmente, agradable y cerca del músico. y escuchar la música. cualquier cosa que no sea hablar, dejarás de descansar.",
    ["**Pub musician** Simply sit down and rest as you would normally, nice and close to the musician. and hear the music. anything other than talk, you will stop resting.Simply sit down and rest as you would normally, nice and close to the musician. and hear the music. anything other than talk, you will stop resting.Resting by a musician will replenish your run energy many times faster than normal, and your life points will also replenish three times as fast."] = "**Pub musician** Simplemente siéntate y descansa como lo harías normalmente, agradable y cerca del músico. y escuchar la música. cualquier otra cosa que no sea hablar, dejarás de descansar. Simplemente siéntate y descansa como lo harías normalmente, agradable y cerca del músico. y escuchar la música. cualquier otra cosa que no sea hablar, dejarás de descansar. Descansar junto a un músico repondrá tu energía de carrera muchas veces más rápido de lo normal, y tus puntos de vida también se repondrán tres veces más rápido.",
    ["**Pub musician** Well,don't forget to have a rest every now and again."] = "**Pub musician** Bueno, no olvides descansar de vez en cuando.",
    ["**Pub musician** Running? Of course! Not that I do much running, I prefer to saunter. But you adventuring types always seem to be in a rush, zipping hither and thither."] = "**Pub musician** ¿Estás corriendo? ¡Por supuesto! No es que corro mucho, prefiero pasear. Pero ustedes, los aventureros, siempre parecen tener prisa, yendo de aquí para allá.",
    ["**Player**Why do I need to run anyway?"] = "**Player**¿Por qué necesito ejecutar de todos modos?",
    ["**Pub musician** Running is the simplest way to get somewhere quickly. When you run you move twice as fast as you normally would. Also, you don't look like the cowardly type, but most creatures can't run very fast, so if you don't want to fight, you can always run away."] = "**Pub musician** Correr es la forma más sencilla de llegar rápidamente a algún lugar. Cuando corres, te mueves el doble de rápido de lo que lo harías normalmente. Además, no pareces del tipo cobarde, pero la mayoría de las criaturas no pueden correr muy rápido, así que si no quieres pelear, siempre puedes huir.",
    ["**Player**Can I keep running forever?"] = "**Player**¿Puedo seguir corriendo para siempre?",
    ["**Pub musician**No, eventually you'll get tired. When that happens you will stop running, and start walking. It takes a while to get your breath back, but once you've recovered a little, you can start running again resting, or more slowly whilst walking."] = "**Pub musician**No, eventualmente te cansarás. Cuando eso suceda, dejarás de correr y empezarás a caminar. Tardarás un poco en recuperar el aliento, pero una vez que te hayas recuperado un poco podrás empezar a correr de nuevo descansando, o más despacio mientras caminas.",
    ["**Game notification** You may start running by clicking once on the Run button, which is the running man icon at the top-right of the minimap. Clicking the Run button a second time will switch you back to walking. It tells you how much run energy you currently have."] = "**Notificación del juego** Puedes comenzar a correr haciendo clic una vez en el botón Ejecutar, que es el ícono del hombre corriendo en la parte superior derecha del minimapa. Al hacer clic en el botón Ejecutar por segunda vez, volverá a caminar. Te indica cuánta energía de carrera tienes actualmente.",
    ["Er, hi, so...isn't there supposed to be a theme park around here somewhere?"] = "Er, hola, entonces... ¿no se supone que hay un parque temático por aquí en alguna parte?",
    ["Ha! That old chestnut. People still fall for that?"] = "¡Ja! Ese viejo castaño. ¿La gente todavía cae en eso?",
    ["Fall for what?"] = "¿Enamorarse de qué?",
    ["Oh, nothing. Why don't you, er, join us...for dinner?"] = "Oh, nada. ¿Por qué no te unes a nosotros... para cenar?",
    ["Ooh, what's on the menu?"] = "Oh, ¿qué hay en el menú?",
    ["Dibs on the sweet meats! You can't call dibs! We share, remember? Aww, but you KNOW I've got a sweet tooth."] = "¡Disfruta de las carnes dulces! ¡No puedes pedir dibs! Compartimos, ¿recuerdas? Ah, pero SABES que soy goloso.",
    ["And you KNOW I'm a pescatarian. I'm not eating that! It could have been anywhere."] = "Y SABES que soy pescatariano. ¡No voy a comer eso! Podría haber estado en cualquier lugar.",
    ["What? What aren't you eating?"] = "¿Qué? ¿Qué no estás comiendo?",
    ["We ARE stranded, remember. Beggars can't be choosers. Unless you want to start eating each other?"] = "Estamos varados, recuerda. Los mendigos no pueden elegir. ¿A menos que quieran empezar a comerse unos a otros?",
    ["Er, yeah, that would be uncivil."] = "Er, sí, eso sería descortés.",
    ["Right, see, even our meal agrees - cannonballs don't eat other cannonballs."] = "Bien, mira, incluso nuestra comida está de acuerdo: las balas de cañón no se comen a otras balas de cañón.",
    ["How many times? It's 'cannibals'!"] = "¿Cuántas veces? ¡Son 'caníbales'!",
    ["That's what I said. You KNOW I have a speech impediment, 'Keith'."] = "Eso es lo que dije. SABES que tengo un impedimento del habla, 'Keith'.",
    ["And I've told you my name is Puddinghead! Not cool, 'Jeff'."] = "¡Y ya les dije que mi nombre es Puddinghead! No está bien, 'Jeff'.",
    ["Urgh, would you boys stop arguing for just one minute?"] = "Urgh, ¿podrían dejar de discutir por un minuto?",
    ["Wait! Stop arguing for a sec. You're cannonballs, I mean, cannibals?"] = "¡Espera! Deja de discutir por un segundo. ¿Sois balas de cañón, quiero decir, caníbales?",
    ["And a pescatarian. I'm a person too, you know. Food is so rude these days. Am I right?"] = "Y un pescatariano. Yo también soy una persona, ¿sabes? La comida es muy grosera estos días. ¿Estoy en lo cierto?",
    ["You're a pescatarian cannibal? How does that work."] = "¿Eres un caníbal pescatariano? ¿Cómo funciona eso?",
    ["Mermaids."] = "Sirenas.",
    ["Oh, that's clever. No, wait, the other thing - that's gross! What about sea orphans. Do you eat those?"] = "Oh, eso es inteligente. No, espera, la otra cosa... ¡eso es asqueroso! ¿Qué pasa con los huérfanos del mar? ¿Comes esos?",
    ["Nah, I have a very strict diet regime. Sea orphans are half-person, half-fish - more like surf 'n' turf."] = "No, tengo una dieta muy estricta. Los huérfanos del mar son mitad personas, mitad peces, más como surf y tierra.",
    ["We're getting off-topic here! Right, so, who gets the legs?"] = "¡Nos estamos saliendo del tema! Bien, entonces, ¿quién se queda con las piernas?",
    ["None of you! Not unless you want to stay stranded! I'll take you back, but NO eating me or my crew."] = "¡Ninguno de ustedes! ¡No, a menos que quieras quedarte varado! Te llevaré de regreso, pero NO me comeré a mí ni a mi tripulación.",
    ["Aww."] = "Ay.",
    ["Spoilsport."] = "Aguafiestas.",
    ["Wait, not even travel snacks?"] = "Espera, ¿ni siquiera bocadillos de viaje?",
    ["Well, I suppose we could try to not eat you if it gets us off this island. We've been stranded here since The Harbinger sank our ship."] = "Bueno, supongo que podríamos intentar no comerte si eso nos saca de esta isla. Hemos estado varados aquí desde que The Harbinger hundió nuestro barco.",
    ["Yes, not eating me would help. Now, what about your friend over there. Is she coming too?"] = "Sí, no comerme ayudaría. Ahora, ¿qué pasa con tu amigo de allí? ¿Ella también viene?",
    ["Who, Jellyhead-head? Nah, she'll be fine. I think she likes it here. Besides, she hasn't said much since she put that thing on her head."] = "¿Quién, Jellyhead-head? No, ella estará bien. Creo que a ella le gusta estar aquí. Además, no ha dicho mucho desde que se puso esa cosa en la cabeza.",
    ["[pic=Rune dust (Runespan) 175 detail.png]"] = "[pic=Polvo de runas (Runespan) 175 detail.png]",
    ["You have already handed in rune dust today."] = "Ya entregaste polvo de runas hoy.",
    ["My secretary is sitting just over there, thank you."] = "Mi secretaria está sentada justo ahí, gracias.",
    ["Today is not a good day, can you come back tomorrow?"] = "Hoy no es un buen día, ¿puedes volver mañana?",
    ["I'm busy, please leave."] = "Estoy ocupado, por favor vete.",
    ["If you're looking for the market, it's downstairs."] = "Si buscas el mercado, está abajo.",
    ["I can't help you, go and see my secretary."] = "No puedo ayudarte, ve a ver a mi secretaria.",
    ["Talk to my secretary. I don't have time to deal with you."] = "Habla con mi secretaria. No tengo tiempo para tratar contigo.",
    ["My secretary will deal with any inquiries you have about the Purple Pewter."] = "Mi secretaria atenderá cualquier consulta que tengas sobre Purple Pewter.",
    ["Do you mind? You're blocking my view."] = "¿Te importa? Estás bloqueando mi vista.",
    ["But..."] = "Pero...",
    ["I said go!"] = "¡Dije que te fueras!",
    ["I told you to leave, human!"] = "¡Te dije que te fueras, humano!",
    ["You are an exceptional member of the Purple Pewter."] = "Eres un miembro excepcional de Purple Pewter.",
    ["Come in, Player, my secretary has been saying good things about you."] = "Pasa, Player, mi secretaria ha estado diciendo cosas buenas de ti.",
    ["Have you come to serve the Purple Pewter again, Player?"] = "¿Has venido a servir el Purple Pewter otra vez, Player?",
    ["You are proving yourself a loyal member of the Purple Pewter, Player!"] = "¡Estás demostrando que eres un miembro leal de Purple Pewter, Player!",
    ["Player! I've been hearing great things about you!"] = "¡Player! ¡He estado escuchando cosas maravillosas sobre ti!",
    ["Come, Player, let us converse a while on your future with us."] = "Ven, Player, déjanos conversar un rato sobre tu futuro con nosotros.",
    ["What have you come to ask of us, honourable Player?"] = "¿Qué ha venido a pedirnos, honorable Player?",
    ["It's an honour to meet you!"] = "¡Es un honor conocerte!",
    ["Fine, fine, now what did you want to talk about?"] = "Bien, bien, ¿ahora de qué querías hablar?",
    ["And what was it that you wanted of me, Player?"] = "¿Y qué era lo que querías de mí, Player?",
    ["It certainly must be."] = "Ciertamente debe serlo.",
    ["Yes, well, don't overdo it now, will you?"] = "Sí, bueno, no te excedas ahora, ¿quieres?",
    ["You are one of our best people, Player, naturally I have time for you."] = "Eres una de nuestras mejores personas, Player, naturalmente tengo tiempo para ti.",
    ["I can imagine!"] = "¡Me lo imagino!",
    ["It's not everyday that you run into someone as important as me, I'm sure."] = "No todos los días te encuentras con alguien tan importante como yo, estoy seguro.",
    ["Do you have any more tasks for me?"] = "¿Tienes más tareas para mí?",
    ["**Player:** Do you have any more tasks for me?"] = "**Player:** ¿Tienes más tareas para mí?",
    ["Verily, I believe I do."] = "En verdad, creo que sí.",
    ["Why, certainly."] = "Pues, claro.",
    ["I do believe so, yes."] = "Eso creo, sí.",
    ["A moment please, let me check."] = "Un momento, por favor, déjame comprobarlo.",
    ["Yes, I have something appropriate for you here."] = "Sí, tengo algo apropiado para ti aquí.",
    ["**Purple Pewter Director:** We need [number] bars of [metal] in the next [number] minutes."] = "**Purple Pewter Director:** Necesitamos barras [número] de [metal] en los próximos minutos [número].",
    ["I'll take it."] = "Lo aceptaré.",
    ["Excellent, get to it now!"] = "Excelente, ¡hazlo ahora!",
    ["Happy to hear that!"] = "¡Feliz de escuchar eso!",
    ["Admirable attitude, Player!"] = "¡Actitud admirable, Player!",
    ["The Purple Pewter appreciates what you're doing, Player."] = "The Purple Pewter aprecia lo que estás haciendo, Player.",
    ["Then hurry back, Player, I'm counting on you!"] = "Entonces vuelve rápido, Player, ¡cuento contigo!",
    ["I'm sorry to hear that, Player, the company really needed those bars."] = "Lamento escuchar eso, Player, la compañía realmente necesitaba esas barras.",
    ["I don't understand, I thought you were a loyal follower?"] = "No entiendo, ¿pensé que eras un seguidor leal?",
    ["Then why did you ask, Player?"] = "Entonces, ¿por qué preguntaste, Player?",
    ["That is an unusual thing to say for you, Player."] = "Eso es algo inusual para ti, Player.",
    ["Oh? I thought you liked doing this kind of work?"] = "¿Ah? Pensé que te gustaba hacer este tipo de trabajo.",
    ["Have you completed your current task yet? Did you get me my [number] bars of [metal]?"] = "¿Ya has completado tu tarea actual? ¿Me conseguiste mis barras [número] de [metal]?",
    ["I'm still working on it, sorry."] = "Todavía estoy trabajando en ello, lo siento.",
    ["Hurry then, I don't have time for all this."] = "Entonces date prisa, no tengo tiempo para todo esto.",
    ["Since you're so fond of the [chosen company during The Giant Dwarf], why don't you ask them?"] = "Ya que te gustan tanto los [chosen company during The Giant Dwarf], ¿por qué no les preguntas?",
    ["You are in league with the [chosen company], aren't you? Your question is inappropriate."] = "Estás aliado con [chosen company], ¿no? Tu pregunta es inapropiada.",
    ["Ask the [chosen company] for a job instead!"] = "¡Pide trabajo al [chosen company]!",
    ["Aren't you an associate of [chosen company]? Why do you ask me?"] = "¿No eres asociado de [chosen company]? ¿Por qué me preguntas?",
    ["I believe that you have business with [other Company] to finish first."] = "Creo que tienes asuntos pendientes con [other Company] para terminar primero.",
    ["*(Only after The Giant Dwarf:)* The trade floor guards keep attacking me!"] = "*(Sólo después de The Giant Dwarf:)* ¡Los guardias del piso de comercio siguen atacándome!",
    ["The trade floor guards keep attacking me."] = "Los guardias del piso comercial siguen atacándome.",
    ["No doubt they thought you were stealing from the traders. You should speak to your own company director."] = "Sin duda pensaron que les estabas robando a los comerciantes. Debería hablar con el director de su propia empresa.",
    ["Thank you for your time."] = "Gracias por tu tiempo.",
    ["Don't mention it."] = "No lo menciones.",
    ["I've completed your task! Here are your bars!"] = "¡He completado tu tarea! ¡Aquí están tus barras!",
    ["The Purple Pewter can always rely on you, Player."] = "The Purple Pewter siempre puede confiar en ti, Player.",
    ["I will get my secretary to send this to the trade floor at once!"] = "¡Haré que mi secretaria envíe esto al parqué de inmediato!",
    ["Welcome back, Player, it's great to see you again!"] = "Bienvenido de nuevo, Player, ¡es un placer verte de nuevo!",
    ["And how can the Purple Pewter be of service to you today, Player?"] = "¿Y cómo puede servirte el Purple Pewter hoy, Player?",
    ["Come in, come in my friend!"] = "¡Entra, entra amigo mío!",
    ["The Purple Pewter is pleased to see you again!"] = "¡Purple Pewter se complace en verte de nuevo!",
    ["Hello again, Player, come in!"] = "Hola de nuevo, Player, ¡pasa!",
    ["**Player:** It's an honour to meet you!"] = "**Player:** ¡Es un honor conocerte!",
    ["Delightful to see you again as well!"] = "¡Encantado de verte de nuevo también!",
    ["And I am honoured to make some time for you, Player!"] = "¡Y es un honor para mí dedicar algo de tiempo a ti, Player!",
    ["Don't mention it, Player!"] = "¡Ni lo menciones, Player!",
    ["Almost as much an honour as it is to meet you again, Player!"] = "¡Es casi tan honor como volver a encontrarte, Player!",
    ["I'm always happy to make time for you, Player!"] = "¡Siempre estoy feliz de tener tiempo para ti, Player!",
    ["It was time well spent!"] = "¡Fue un tiempo bien empleado!",
    ["Not at all, it was a delight to speak to you once more!"] = "Para nada, ¡fue un placer hablar contigo una vez más!",
    ["Guthix be praised!"] = "¡Alabado sea Guthix!",
    ["I am well pleased with your work, Player!"] = "¡Estoy muy satisfecho con tu trabajo, Player!",
    ["You are a true asset to the Purple Pewter!"] = "¡Eres un verdadero activo para Purple Pewter!",
    ["You never fail to satisfy, Player!"] = "¡Nunca dejas de satisfacer, Player!",
    ["Hello Player! Have you seen the statue? It looks beautiful! The Purple Pewter is indebted to you for your dedication in making this happen!"] = "¡Hola Player! ¿Has visto la estatua? ¡Se ve hermoso! ¡Purple Pewter está en deuda contigo por tu dedicación para hacer que esto sucediera!",
    ["More work? My, you certainly are an asset to the company."] = "¿Más trabajo? Vaya, ciertamente eres un activo para la empresa.",
    ["Really, Player, you don't need to do this anymore."] = "De verdad, Player, ya no necesitas hacer esto.",
    ["But I want to!"] = "¡Pero quiero hacerlo!",
    ["Well, if you insist..."] = "Bueno, si insistes...",
    ["You don't need to do this anymore, you know?"] = "Ya no necesitas hacer esto, ¿sabes?",
    ["Ah, if only all the members of the Purple Pewter had such dedication as you."] = "Ah, si tan solo todos los miembros de Purple Pewter tuvieran tanta dedicación como tú.",
    ["The trade floor guards keep attacking me!"] = "¡Los guardias del piso de comercio siguen atacándome!",
    ["I might be able to get the guards off your back, if you perform a task for the company."] = "Quizás pueda quitarte los guardias de encima si realizas una tarea para la empresa.",
    ["Alright."] = "Muy bien.",
    ["Until later, then, my friend! I'm sure the Purple Pewter will play a role in your future again at some point!"] = "¡Hasta luego, amigo! ¡Estoy seguro de que Purple Pewter volverá a desempeñar un papel en tu futuro en algún momento!",
    ["I'll have a word with the guards. They won't be watching you for the next ten minutes."] = "Hablaré con los guardias. No te estarán mirando durante los próximos diez minutos.",
    ["The trade floor guards are now bribed to ignore you."] = "Los guardias del piso de comercio ahora están sobornados para que lo ignoren.",
    ["Hello Player! Have you seen the statue? It looks beautiful! It's a pity it's been overshadowed by the departure of the Red Axe."] = "¡Hola Player! ¿Has visto la estatua? ¡Se ve hermoso! Es una pena que se haya visto eclipsado por la marcha del Red Axe.",
    ["Handing over power to the monarchy was the worst day of my life. At least King Veldaban has kept the Consortium around as an advisory body."] = "Entregar el poder a la monarquía fue el peor día de mi vida. Al menos el rey Veldaban ha mantenido al Consorcio como organismo asesor.",
    ["I hope you understand what you've done, human. You could have convinced Veldaban to step down and let the experts take over. Instead we're saddled with his ridiculous policies again."] = "Espero que entiendas lo que has hecho, humano. Podrías haber convencido a Veldaban de que renunciara y dejara que los expertos se hicieran cargo. En cambio, volvemos a cargar con sus ridículas políticas.",
    ["Things could be worse, I suppose. The new king is listening to the Consortium's advice... on the few occasions he's sober enough to understand it."] = "Las cosas podrían ser peores, supongo. El nuevo rey está escuchando los consejos del Consorcio... en las pocas ocasiones en que está lo suficientemente sobrio como para entenderlos.",
    ["Thanks for your support in the meeting, Player. Now Keldagrim can put the silly business of kings behind it and let the company directors manage things properly."] = "Gracias por tu apoyo en la reunión, Player. Ahora Keldagrim puede dejar atrás los tontos negocios de los reyes y dejar que los directores de la empresa gestionen las cosas correctamente.",
    ["I don't have much time for you, what do you want?"] = "No tengo mucho tiempo para ti, ¿qué quieres?",
    ["You're blocking my view, human, so hurry up."] = "Estás bloqueando mi vista, humano, así que date prisa.",
    ["Can we hurry this along?"] = "¿Podemos apurarnos?",
    ["Say what you want or get out of our office, human!"] = "¡Di lo que quieras o sal de nuestra oficina, humano!",
    ["Do not test the patience of the Purple Pewter, human. Say what you need!"] = "No pongas a prueba la paciencia del Purple Pewter, humano. ¡Di lo que necesites!",
    ["I think I've misplaced my quill somewhere..."] = "Creo que perdí mi pluma en alguna parte...",
    ["Oh, and what did you want?"] = "Ah, ¿y qué querías?",
    ["I am the head secretary of the Purple Pewter."] = "Soy el secretario principal de Purple Pewter.",
    ["I said, the Purple Pewter. Together with the other companies, we rule Keldagrim and the dwarven realm."] = "Dije, el peltre morado. Junto con las demás empresas, gobernamos Keldagrim y el reino de los enanos.",
    ["Where am I?"] = "¿Dónde estoy?",
    ["I'm not here to give directions!"] = "¡No estoy aquí para dar instrucciones!",
    ["Do I look like a tour guide to you?"] = "¿Te parezco un guía turístico?",
    ["I'd tell you, human, but you wouldn't understand anyway."] = "Te lo diría, humano, pero de todos modos no lo entenderías.",
    ["These are the offices of the Purple Pewter."] = "Estas son las oficinas de Purple Pewter.",
    ["We share this floor of the palace with the other companies of the Consortium. And trade with them on the Trade Octagon."] = "Compartimos esta planta del palacio con el resto de empresas del Consorcio. Y comercie con ellos en el octágono comercial.",
    ["The Trade Octagon?"] = "¿El octágono comercial?",
    ["See those traders standing out there, just out the door? They're all standing in the Trade Octagon. There's an awful lot of trade going on in the palace, you know."] = "¿Ves a esos comerciantes parados ahí afuera, justo afuera de la puerta? Todos están parados en el octágono comercial. Hay muchísimo comercio en el palacio, ¿sabes?",
    ["Anything else of interest in the palace?"] = "¿Algo más de interés en el palacio?",
    ["You will have to find that out on your own, I'm afraid. I do have more work to do."] = "Me temo que tendrás que descubrirlo por tu cuenta. Tengo más trabajo que hacer.",
    ["Is there anything I can help you with?"] = "¿Hay algo en lo que pueda ayudarte?",
    ["Come to redeem yourself at our company, have you?"] = "Ven a redimirte en nuestra empresa, ¿verdad?",
    ["So you're looking for work with us all of a sudden?"] = "¿Entonces de repente estás buscando trabajo con nosotros?",
    ["You're lucky the Purple Pewter is very forgiving, human."] = "Tienes suerte de que Purple Pewter sea muy indulgente, humano.",
    ["I'm not sure if I'm allowed to give someone like you a task, I'll check."] = "No estoy seguro de poder asignarle una tarea a alguien como tú, lo comprobaré.",
    ["All right, you've been cleared."] = "Muy bien, has sido autorizado.",
    ["Your motives are questionable but we'll give you a chance."] = "Tus motivos son cuestionables, pero te daremos una oportunidad.",
    ["We need [number] pieces of [ore] in the next [number] minutes."] = "Necesitamos [número] piezas de [ore] en los próximos minutos [número].",
    ["Do no disappoint the Purple Pewter, human."] = "No decepciones al Purple Pewter, humano.",
    ["Go then! The longer you stand here the more time you waste!"] = "¡Vete entonces! ¡Cuanto más tiempo estés aquí, más tiempo perderás!",
    ["Hurry back or don't come back at all!"] = "¡Date prisa o no vuelvas!",
    ["Let's hope I was wrong about you, human."] = "Esperemos haberme equivocado contigo, humano.",
    ["You'd better not fail!"] = "¡Será mejor que no falles!",
    ["Oh, so you were just stopping by to waste my time, then? Goodbye!"] = "Oh, ¿entonces viniste a hacerme perder el tiempo? ¡Adiós!",
    ["To say a thing like that after the mercy I just showed you! Go away!"] = "¡Decir algo así después de la misericordia que te acabo de mostrar! ¡Irse!",
    ["You dare!"] = "¡Te atreves!",
    ["Thought you wouldn't. Now get out of here!"] = "Pensé que no lo harías. ¡Ahora sal de aquí!",
    ["Leave now, don't make me call the Black Guard to throw you out!"] = "¡Vete ahora, no me hagas llamar al Black Guard para echarte!",
    ["Get out of our office then!"] = "¡Entonces sal de nuestra oficina!",
    ["The Purple Pewter offers you a chance and you say this? Just stay away!"] = "El Purple Pewter te ofrece una oportunidad ¿y dices esto? ¡Sólo mantente alejado!",
    ["Have you completed your current task yet? Did you get me my [number] pieces of [ore]?"] = "¿Ya has completado tu tarea actual? ¿Me conseguiste mis piezas [número] de [ore]?",
    ["No, not yet."] = "No, todavía no.",
    ["You're a disgrace to the Purple Pewter. Hurry up if you want to redeem yourself."] = "Eres una vergüenza para Purple Pewter. Date prisa si quieres redimirte.",
    ["Go back to your friends at the [other Company], I hear you're in league with them."] = "Vuelve con tus amigos del [other Company], he oído que estás aliado con ellos.",
    ["I have to go!"] = "¡Tengo que irme!",
    ["Finally...back to work at last."] = "Finalmente... por fin volvemos al trabajo.",
    ["Good."] = "Bien.",
    ["Don't hurry back."] = "No te apresures a regresar.",
    ["The door is over there. I suggest you use it."] = "La puerta está por ahí. Te sugiero que lo uses.",
    ["And good riddance to you."] = "Y adiós.",
    ["I've completed your task! Here is your ore!"] = "¡He completado tu tarea! ¡Aquí está tu mineral!",
    ["How unusual for you, but it is appreciated nonetheless."] = "Qué inusual para ti, pero de todos modos se agradece.",
    ["The Purple Pewter is pleased that the trust it put in you has not been put to shame after all."] = "The Purple Pewter se complace en saber que, después de todo, la confianza que depositó en usted no ha sido avergonzada.",
    ["That is quite a pleasant and unexpected surprise."] = "Es una sorpresa bastante agradable e inesperada.",
    ["Perhaps I was wrong about you after all..."] = "Quizás me equivoqué contigo después de todo...",
    ["Thanks... I suppose."] = "Gracias... Supongo.",
    ["What did you need of the Purple Pewter?"] = "¿Qué necesitabas del Purple Pewter?",
    ["And what can I do for you?"] = "¿Y qué puedo hacer por ti?",
    ["Is there anything you need assistance with?"] = "¿Hay algo con lo que necesites ayuda?",
    ["Can I help you with anything?"] = "¿Puedo ayudarte en algo?",
    ["Was there anything you wanted?"] = "¿Había algo que quisieras?",
    ["What can I do for you, human?"] = "¿Qué puedo hacer por ti, humano?",
    ["Oh, by the way, I really like that outfit of yours!"] = "Ah, por cierto, ¡me gusta mucho ese conjunto tuyo!",
    ["Why, this is the headquarters of the Purple Pewter."] = "Vaya, esta es la sede de Purple Pewter.",
    ["There's always work to be done, yes."] = "Siempre hay trabajo por hacer, sí.",
    ["Just a moment."] = "Un momento.",
    ["Yes, the Purple Pewter always has work to do!"] = "Sí, ¡Purple Pewter siempre tiene trabajo que hacer!",
    ["Let's see... yes, yes, I do have a task for you."] = "Veamos... sí, sí, tengo una tarea para ti.",
    ["Yes, I think we do have something for you."] = "Sí, creo que tenemos algo para ti.",
    ["I believe we have some work available, yes."] = "Creo que tenemos trabajo disponible, sí.",
    ["The Purple Pewter has noted your willingness to help."] = "The Purple Pewter ha notado su voluntad de ayudar.",
    ["That ore needs to go on the trade floor soon, player, please hurry back with it."] = "Ese mineral debe estar pronto en la sala de operaciones, jugador, por favor regresa con él.",
    ["Thanks, it's appreciated."] = "Gracias, se agradece.",
    ["The clock is ticking, please hurry back."] = "El tiempo corre, por favor regresa rápido.",
    ["I will await your return soon, then."] = "Entonces, esperaré tu regreso pronto.",
    ["Fair enough, maybe some other time?"] = "Muy bien, ¿tal vez en otro momento?",
    ["Please, it would be appreciated if you made up your mind before you ask. I'm very busy you know."] = "Por favor, le agradeceríamos que tomara una decisión antes de preguntar. Estoy muy ocupado, ¿sabes?",
    ["Please, in that case, you're wasting my time."] = "Por favor, en ese caso, estás perdiendo el tiempo.",
    ["That's unfortunate to hear."] = "Es lamentable escuchar eso.",
    ["I can't say I'm too pleased to hear that, to be honest."] = "Para ser honesto, no puedo decir que esté muy contento de escuchar eso.",
    ["That does not reflect well on you."] = "Eso no te refleja bien.",
    ["The Purple Pewter isn't too pleased to hear that."] = "The Purple Pewter no está muy contento de escuchar eso.",
    ["Then please, hurry up before time runs out."] = "Entonces, por favor, apúrate antes de que se acabe el tiempo.",
    ["From what I understand, you have some business to finish with the [other Company] first."] = "Por lo que tengo entendido, primero tienes algunos asuntos que terminar con el [other Company].",
    ["Goodbye, human."] = "Adiós, humano.",
    ["I have to admit, I was worried for a moment, but I'm glad to see you came through for us."] = "Tengo que admitir que estuve preocupado por un momento, pero me alegra ver que nos ayudaste.",
    ["I am happy to see that the trust we put in you has not been in vain."] = "Me alegra comprobar que la confianza que depositamos en vosotros no ha sido en vano.",
    ["And not a minute too late as well. Well done."] = "Y ni un minuto tarde también. Bien hecho.",
    ["The Purple Pewter recognizes your performance."] = "El Purple Pewter reconoce tu desempeño.",
    ["That's good to hear, thanks."] = "Es bueno escucharlo, gracias.",
    ["How may the Purple Pewter assist you today?"] = "¿Cómo puede ayudarte el Purple Pewter hoy?",
    ["And what can I do for you on this fine day?"] = "¿Y qué puedo hacer por ti en este lindo día?",
    ["Come to help us some more, Player?"] = "¿Ven a ayudarnos un poco más, Player?",
    ["Oh, hello there Player! Nice to see you!"] = "¡Oh, hola Player! ¡Qué bueno verte!",
    ["Welcome back to the palace of Keldagrim, Player!"] = "¡Bienvenido de nuevo al palacio de Keldagrim, Player!",
    ["Come in, come in! And tell us what you need!"] = "¡Entra, entra! ¡Y cuéntanos qué necesitas!",
    ["The top floor of the palace is the Meeting Octagon. That's the place where the Consortium makes all the important decisions."] = "El último piso del palacio es el Octágono de Reuniones. Ese es el lugar donde el Consorcio toma todas las decisiones importantes.",
    ["Can I go there?"] = "¿Puedo ir allí?",
    ["Oh, yes, you certainly can. But not while the Consortium is in session, I would imagine."] = "Oh, sí, ciertamente puedes. Pero me imagino que no mientras el Consorcio esté en sesión.",
    ["Even though you are a very friendly human, I'm not sure if you would be allowed to visit during a meeting."] = "Aunque eres una persona muy amigable, no estoy seguro de si se te permitiría visitarnos durante una reunión.",
    ["But I don't know enough about that, the director probably knows more."] = "Pero no sé lo suficiente sobre eso, el director probablemente sepa más.",
    ["Thanks for the info!"] = "¡Gracias por la información!",
    ["Ah, always looking for ways to help us!"] = "¡Ah, siempre buscando formas de ayudarnos!",
    ["Naturally, my good human, naturally!"] = "¡Por supuesto, mi buen humano, por supuesto!",
    ["Of course, we reserve our best tasks just for you, Player!"] = "¡Por supuesto, reservamos nuestras mejores tareas solo para ti, Player!",
    ["I do believe we do, yes!"] = "Creo que sí, ¡sí!",
    ["I dare say we have something for you, yes."] = "Me atrevo a decir que tenemos algo para ti, sí.",
    ["Oh yes, as you know the Purple Pewter always has work!"] = "¡Oh, sí, como sabes, Purple Pewter siempre tiene trabajo!",
    ["You never disappoint, Player!"] = "¡Nunca decepcionas, Player!",
    ["Excellent, I thought you'd like this!"] = "¡Excelente, pensé que te gustaría esto!",
    ["I'm happy to hear that!"] = "¡Me alegra escuchar eso!",
    ["The Purple Pewter appreciates the hard work you do."] = "The Purple Pewter aprecia el arduo trabajo que haces.",
    ["Thanks! But hurry back please, we really need that ore!"] = "¡Gracias! Pero date prisa, por favor, ¡realmente necesitamos ese mineral!",
    ["I suppose you have other important business to attend to?"] = "Supongo que tienes otros asuntos importantes que atender.",
    ["Oh. Didn't know you were the type to refuse work."] = "Ah. No sabía que eras del tipo que rechaza el trabajo.",
    ["Is everything okay? I didn't think you normally refused our tasks."] = "¿Está todo bien? No pensé que normalmente rechazaras nuestras tareas.",
    ["That's a great shame, Player."] = "Es una gran lástima, Player.",
    ["No? That's unusual for you, Player."] = "¿No? Eso es inusual para ti, Player.",
    ["Sorry to hear that, but please hurry up!"] = "Lamento escuchar eso, ¡pero apúrate!",
    ["Don't you have some business with [other company] to deal with first? Hurry back when you're done!"] = "¿No tienes algún asunto con [other company] que tratar primero? ¡Date prisa cuando hayas terminado!",
    ["It was a pleasure to talk to you again, Player."] = "Fue un placer volver a hablar contigo, Player.",
    ["Come back any time!"] = "¡Vuelve cuando quieras!",
    ["See you soon!"] = "¡Hasta pronto!",
    ["Wonderful! I will personally oversee that it goes to the trade floor on time!"] = "¡Maravilloso! ¡Supervisaré personalmente que llegue a tiempo al parqué!",
    ["Well done, well done!"] = "¡Bien hecho, bien hecho!",
    ["I knew you were the right human for the job!"] = "¡Sabía que eras la persona adecuada para el trabajo!",
    ["Thanks, I will make sure the director hears of your expeditiousness!"] = "¡Gracias, me aseguraré de que el director se entere de su rapidez!",
    ["You're always reliable, Player!"] = "¡Siempre eres confiable, Player!",
    ["I'm afraid I have no more work to offer you, Player, please speak to the director."] = "Me temo que no tengo más trabajo que ofrecerte, Player, por favor habla con el director.",
    ["You should speak directly to the director."] = "Deberías hablar directamente con el director.",
    ["[Earn some Cosy Pyjamas and Cosy Slippers by getting onto Santa's nice list and visiting him at his lodge in the Christmas Village at 8pm game time each Sunday in December.]"] = "[Gana pijamas acogedores y pantuflas acogedoras ingresando a la linda lista de Santa y visitándolo en su albergue en Christmas Village a las 8 p. m., hora del juego, todos los domingos de diciembre.]",
    ["[Unlock the Hot Chocolate rest animation by helping out Diango and Cait in Diango's Workshop, with the new seasonal quest 'A Christmas Reunion'.]"] = "[Desbloquea la animación del descanso de chocolate caliente ayudando a Diango y Cait en el taller de Diango, con la nueva misión de temporada 'Una reunión de Navidad'.]",
    ["[The Christmas festivities have now ended.]"] = "[Las fiestas navideñas ya han terminado.]",
}

return dialogues
